        .jrpg-modal-overlay{ position:fixed; top:0;left:0;right:0;bottom:0; background:rgba(0,0,0,.6); z-index:9999; display:none; justify-content:center; align-items:center; backdrop-filter:blur(2px); }
        .jrpg-modal-content{ background:#fdf8f0; width:90%; max-width:800px; height:85vh; border:4px solid #8b6b4a; border-radius:8px; box-shadow:0 10px 30px rgba(0,0,0,.5); display:flex; flex-direction:column; font-family:"Georgia","Times New Roman","Microsoft YaHei",serif; }
        .jrpg-modal-header{ background:#8b6b4a; color:#fff; padding:12px 15px; font-size:16px; font-weight:bold; display:flex; justify-content:space-between; align-items:center; border-radius:3px 3px 0 0; }
        .jrpg-modal-close{ cursor:pointer; font-size:18px; color:#eed; }
        .jrpg-modal-body{ flex:1; overflow-y:auto; padding:20px; background-color: #f4ebd8; background-image: radial-gradient(#e6d5b8 1px, transparent 1px); background-size: 20px 20px; color: #4a3623; }
        .jrpg-modal-footer{ padding:12px 15px; border-top:2px solid #8b6b4a; background:#fdf8f0; display:flex; justify-content:flex-end; gap:10px; border-radius:0 0 3px 3px; }
        .jrpg-btn{ padding:6px 15px; border:2px solid #8b6b4a; border-radius:4px; font-weight:bold; cursor:pointer; background:#e6d5b8; color:#4a3623; transition:all .2s; font-family:inherit; }
        .jrpg-btn:hover{ background:#d4c4b7; }
        .jrpg-btn.primary{ background:#27ae60; border-color:#1e8449; color:#fff; }
        .jrpg-btn.primary:hover{ background:#2ecc71; }
        .vt-ul{ list-style:none; padding-left:20px; margin:5px 0; border-left:1px dashed #d2b48c; }
