        .vt-input{ background:#fff; border:1px solid #b8a080; border-radius:3px; padding:3px 6px; font-size:12px; color:#333; flex:1; min-width:100px; max-width:300px; }
        .vt-input:focus{ outline:none; border-color:#8e44ad; }
        .vt-btn-del{ background:#e74c3c; color:#fff; border:none; border-radius:3px; padding:2px 6px; font-size:10px; cursor:pointer; }
        .vt-btn-add{ background:#2ecc71; color:#fff; border:none; border-radius:3px; padding:2px 6px; font-size:10px; cursor:pointer; }
        .vt-type-badge{ font-size:9px; color:#7f8c8d; background:#e0e0e0; padding:1px 4px; border-radius:3px; }
        /* 全局修改器·快捷分区导航 */
        .vt-nav-btn{ padding:3px 10px; border:1px solid #b8a080; background:#e6d5b8; color:#4a3623; border-radius:4px; font-size:11px; cursor:pointer; font-family:inherit; transition:all .2s; }
        .vt-nav-btn:hover{ background:#d4c4b7; }
        .vt-nav-btn.active{ background:#8e44ad; border-color:#6b2e6b; color:#fff; }
        /* 变体技能学习按钮 */
        .jrpg-btn-sm{ font-family:inherit; font-weight:bold; cursor:pointer; }
        .jrpg-vs-learn{ background:#2980b9; color:#fff; border:2px solid #2980b9; border-radius:4px; padding:2px 10px; font-size:11px; }
        .jrpg-vs-learn:hover{ background:#3498db; }
        /* ===== 装备栏 ===== */
        .jrpg-equip-slot{ display:flex; align-items:center; gap:10px; padding:9px 10px; border:1px solid #d2b48c; border-radius:4px; margin-bottom:6px; background:rgba(255,250,240,.55); }
        .jrpg-equip-slot:last-child{ margin-bottom:0; }
        .jrpg-equip-slot .slot-name{ width:60px; font-weight:bold; color:#6b2e2e; font-size:12px; flex-shrink:0; }
        .jrpg-equip-slot .slot-item{ flex:1; min-width:0; font-size:11px; color:#4a3623; }
        .jrpg-equip-btn{ background:#8e44ad; color:#fff; border:2px solid #8e44ad; border-radius:4px; padding:3px 10px; font-size:11px; font-family:inherit; font-weight:bold; cursor:pointer; transition:all .2s; }
        .jrpg-equip-btn:hover{ background:#9b59b6; }
        .jrpg-unequip-btn{ background:#c0392b; color:#fff; border:2px solid #c0392b; border-radius:4px; padding:3px 10px; font-size:11px; font-family:inherit; font-weight:bold; cursor:pointer; transition:all .2s; }
        .jrpg-unequip-btn:hover{ background:#e74c3c; }
        /* ===== 同伴装备按钮（椭圆形·更醒目·可交互） ===== */
        .jrpg-comp-equip-btn{
            display:inline-flex; align-items:center; gap:4px;
            background:linear-gradient(180deg,#f6c945,#e0a61f);
            color:#3d1d00; text-shadow:0 1px 0 rgba(255,255,255,.35);
            border:2px solid #7a5200; border-radius:999px;
            padding:6px 18px; font-size:12px; font-family:inherit;
            font-weight:900; letter-spacing:1px; cursor:pointer;
            box-shadow:0 2px 5px rgba(80,55,0,.35), inset 0 1px 0 rgba(255,255,255,.45);
            transition:all .2s ease;
        }
        .jrpg-comp-equip-btn:hover{
            background:linear-gradient(180deg,#ffd95e,#eeb42e);
            transform:translateY(-1px) scale(1.05);
            box-shadow:0 4px 12px rgba(80,55,0,.4), inset 0 1px 0 rgba(255,255,255,.5);
        }
        .jrpg-comp-equip-btn:active{
            transform:translateY(1px) scale(.96);
            box-shadow:0 1px 2px rgba(80,55,0,.3), inset 0 2px 5px rgba(0,0,0,.18);
        }
        .jrpg-comp-equip-btn:disabled{
            background:#d8cbb4; color:#8b8b8b; border-color:#b0a18a;
            cursor:not-allowed; transform:none; box-shadow:none; text-shadow:none;
        }
        /* ===== 同伴物品锁定（支持写入·拒绝删除） ===== */
        .jrpg-comp-lock-btn, .jrpg-attr-lock-btn{
            display:inline-flex; align-items:center; gap:4px;
            background:#e6d5b8; color:#4a3623;
            border:1.5px solid #b8a080; border-radius:999px;
            padding:3px 12px; font-size:11px; font-family:inherit;
            font-weight:bold; cursor:pointer; transition:all .2s ease;
        }
        .jrpg-comp-lock-btn:hover, .jrpg-attr-lock-btn:hover{ background:#d4c4b7; border-color:#8b6b4a; }
        .jrpg-comp-lock-btn.locked, .jrpg-attr-lock-btn.locked{ background:#2f4d1b; color:#eaffcf; border-color:#1f3512; }
        .jrpg-comp-lock-btn.locked:hover, .jrpg-attr-lock-btn.locked:hover{ background:#3a5d22; }
        /* ===== 同伴一键全锁按钮（属性+物品栏只读，拒绝删除） ===== */
        .jrpg-comp-full-lock-btn{ display:inline-flex; align-items:center; gap:2px; background:linear-gradient(180deg,#d94f4f,#b93a3a); color:#fff; border:1px solid #7a1f1f; border-radius:999px; padding:1px 8px; font-size:9px; font-family:inherit; font-weight:bold; letter-spacing:0.3px; cursor:pointer; box-shadow:0 1px 2px rgba(120,20,20,.25); transition:all .2s ease; }
        .jrpg-comp-full-lock-btn:hover{ background:linear-gradient(180deg,#e96b6b,#cc4a4a); transform:translateY(-1px); box-shadow:0 2px 6px rgba(120,20,20,.4); }
        .jrpg-comp-full-lock-btn:active{ transform:translateY(1px); }
        .jrpg-comp-full-lock-btn.locked{ background:linear-gradient(180deg,#3f8f3f,#2f742f); border-color:#1f521f; color:#eaffcf; }
        .jrpg-comp-full-lock-btn.locked:hover{ background:linear-gradient(180deg,#4aa84a,#3a8a3a); }
        .jrpg-attr-lock-btn{ font-size:10px; padding:2px 10px; margin-left:6px; vertical-align:2px; }
        .jrpg-item-lock-badge{
            display:inline-block; margin-left:4px; padding:0 5px;
            background:#2f4d1b; color:#eaffcf; border-radius:3px;
            font-size:9px; font-weight:bold; vertical-align:1px;
        }
        .jrpg-comp-inv-actions{
            display:flex; align-items:center; gap:8px; flex-wrap:wrap;
            margin-top:8px; padding-top:6px; border-top:1px dotted #e6d5b8;
        }
        /* ===== 升级分配 ===== */
        .alloc-targets{ display:flex; flex-wrap:wrap; gap:6px; margin-bottom:10px; }
        .alloc-target-btn{ padding:5px 12px; border:2px solid #b8a080; background:#e6d5b8; color:#4a3623; border-radius:4px; font-size:12px; font-weight:bold; cursor:pointer; font-family:inherit; transition:all .2s; }
        .alloc-target-btn:hover{ background:#d4c4b7; }
        .alloc-target-btn.active{ background:#8b6b4a; border-color:#6b4e31; color:#fff; }
        .alloc-res{ display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:6px; margin-bottom:10px; }
        .alloc-res-item{ background:rgba(255,250,240,.6); border:1px dashed #d2b48c; border-radius:3px; padding:5px 8px; font-size:11px; color:#4a3623; }
        .alloc-res-item b{ color:#d35400; font-size:13px; }
        .alloc-sec-title{ font-size:12px; font-weight:bold; color:#6b2e2e; margin:12px 0 6px; border-bottom:1px dashed #d2b48c; padding-bottom:4px; }
        .alloc-row{ display:flex; align-items:center; justify-content:space-between; gap:8px; padding:4px 0; border-bottom:1px dotted #e6d5b8; font-size:12px; }
        .alloc-row:last-child{ border-bottom:none; }
        .alloc-row .alloc-name{ font-weight:bold; color:#4a3623; }
        .alloc-stepper{ display:flex; align-items:center; gap:6px; }
        .alloc-step-btn{ width:24px; height:24px; border-radius:4px; border:1px solid #8b6b4a; background:#f4ebd8; color:#6b2e2e; font-weight:bold; font-size:14px; cursor:pointer; line-height:1; font-family:inherit; }
        .alloc-step-btn:disabled{ opacity:.35; cursor:not-allowed; }
        .alloc-step-btn.minus:hover:not(:disabled){ background:#e74c3c; color:#fff; }
        .alloc-step-btn.plus:hover:not(:disabled){ background:#27ae60; color:#fff; }
        .alloc-step-val{ min-width:52px; text-align:center; font-weight:bold; color:#8e44ad; }
        .alloc-diff{ font-size:10px; color:#27ae60; font-weight:bold; }
        .alloc-diff.neg{ color:#e74c3c; }
        .alloc-skill-item{ display:flex; justify-content:space-between; align-items:center; gap:8px; padding:5px 0; border-bottom:1px dotted #e6d5b8; font-size:11px; }
        .alloc-skill-item .sk-name{ font-weight:bold; color:#4a3623; }
        .alloc-skill-item .sk-meta{ font-size:10px; color:#8b6b4a; margin-top:1px; }
        .alloc-skill-badge{ display:inline-block; background:#8e44ad; color:#fff; border-radius:3px; padding:0 5px; font-size:9px; font-weight:bold; margin-left:4px; vertical-align:1px; }
        .alloc-add-skill{ background:#2980b9; color:#fff; border:2px solid #2980b9; border-radius:4px; padding:2px 8px; font-size:11px; font-weight:bold; cursor:pointer; font-family:inherit; flex-shrink:0; }
        .alloc-add-skill:hover{ background:#3498db; }
        .alloc-add-skill:disabled{ background:#bbb; border-color:#bbb; cursor:not-allowed; }
        .alloc-draft{ background:rgba(142,68,173,.06); border:1px dashed #8e44ad; border-radius:4px; padding:8px 10px; margin-top:10px; font-size:11px; }
        .alloc-draft-item{ display:flex; justify-content:space-between; align-items:center; padding:3px 0; border-bottom:1px dotted #d2b48c; }
        .alloc-draft-item:last-child{ border-bottom:none; }
        .alloc-rm{ background:#e74c3c; color:#fff; border:none; border-radius:3px; padding:1px 7px; font-size:10px; cursor:pointer; }
        .alloc-actions{ display:flex; flex-wrap:wrap; gap:8px; margin-top:12px; }
        .alloc-btn{ padding:6px 14px; border:2px solid #8b6b4a; border-radius:4px; font-weight:bold; cursor:pointer; font-family:inherit; font-size:12px; }
        .alloc-btn:hover{ background:#d4c4b7; }
        .alloc-btn.confirm{ background:#27ae60; border-color:#1e8449; color:#fff; }
        .alloc-btn.confirm:hover{ background:#2ecc71; }
        .alloc-btn.notice{ background:#8e44ad; border-color:#6b2e6b; color:#fff; }
        .alloc-btn.notice:hover{ background:#9b59b6; }
        .alloc-btn.reset{ background:#e6d5b8; color:#4a3623; }
        .alloc-hint{ font-size:10px; color:#8b6b4a; margin-top:8px; line-height:1.6; }
        .alloc-empty{ text-align:center; color:#bbb; font-size:12px; padding:12px 0; font-style:italic; }
        .alloc-mode-row{ display:flex; align-items:center; gap:6px; font-size:11px; color:#6b4e31; margin-bottom:10px; flex-wrap:wrap; }
        .alloc-mode-btn{ padding:3px 10px; border:1px solid #b8a080; background:#e6d5b8; color:#4a3623; border-radius:4px; font-size:11px; cursor:pointer; font-family:inherit; }
        .alloc-mode-btn:hover{ background:#d4c4b7; }
        .alloc-mode-btn.active{ background:#8e44ad; border-color:#6b2e6b; color:#fff; }
        /* ===== 领地建设·中世纪卷轴主题 ===== */
        #territory-inner{ position:relative; }
        .trt-wrap{ position:relative; }
        .trt-settings{ position:absolute; top:-4px; right:6px; z-index:6; display:flex; gap:4px; }
        .trt-set-btn{ font-family:inherit; font-size:11px; padding:3px 10px; border:1px solid #a08860; background:rgba(255,250,240,.85); color:#5a4a30; border-radius:3px; cursor:pointer; }
        .trt-set-btn:hover{ background:#e8dcc0; }
        .trt-theme-menu{ position:absolute; right:0; top:26px; background:#fdf8f0; border:2px solid #8b6b4a; border-radius:4px; box-shadow:0 4px 14px rgba(60,40,10,.35); padding:6px; display:none; z-index:10; min-width:130px; }
        .trt-theme-menu.open{ display:block; }
        .trt-theme-item{ display:block; width:100%; text-align:left; font-family:inherit; font-size:11px; padding:5px 8px; border:none; background:transparent; color:#4a3623; cursor:pointer; border-radius:3px; }
        .trt-theme-item:hover{ background:#e6d5b8; }
        .trt-theme-item.active{ background:#8b6b4a; color:#fff; }
        .trt-panel{ border-radius:10px; padding:16px 16px 14px; margin-bottom:12px; position:relative; overflow:hidden; }
        /* 主题1：羊皮卷（暖纸·墨水·手写感） */
        .trt-theme-parchment{
          color:#3a2a12;
          background:
            radial-gradient(ellipse at 15% 20%, rgba(150,110,60,.10), transparent 55%),
            radial-gradient(ellipse at 85% 80%, rgba(150,110,60,.08), transparent 50%),
            repeating-linear-gradient(0deg, rgba(139,101,32,.028) 0 1px, transparent 1px 4px),
            linear-gradient(168deg,#f9eed2 0%,#f1e0b8 45%,#f6e9c9 100%);
          border:2px solid #a07840;
          box-shadow:0 4px 14px rgba(90,58,26,.28), inset 0 0 0 1px rgba(255,244,210,.6);
        }
        .trt-theme-parchment::before{ content:''; position:absolute; inset:6px; border:1px solid rgba(139,101,32,.32); border-radius:7px; pointer-events:none; }
        /* 主题2：王廷暗金（黑金·烛光·纹章） */
        .trt-theme-royal{
          color:#ecd9a8;
          background:
            radial-gradient(ellipse at 50% -10%, rgba(212,175,55,.18), transparent 55%),
            linear-gradient(175deg,#171006 0%,#2a1f0c 45%,#191104 100%);
          border:2px solid #8a6a20;
          box-shadow:0 0 16px rgba(212,175,55,.22), 0 4px 14px rgba(0,0,0,.5), inset 0 0 0 1px rgba(212,175,55,.15), inset 0 0 40px rgba(0,0,0,.5);
        }
        .trt-theme-royal::before{ content:''; position:absolute; inset:6px; border:1px solid rgba(212,175,55,.28); border-radius:7px; pointer-events:none; }
        /* 主题3：苔痕古碑（深石·浮雕·苔绿） */
        .trt-theme-stone{
          color:#cdd8c8;
          background:
            repeating-linear-gradient(45deg, rgba(90,110,80,.05) 0 2px, transparent 2px 9px),
            linear-gradient(172deg,#343c32 0%,#272e26 55%,#30382e 100%);
          border:2px solid #4a5a44;
          box-shadow:0 4px 14px rgba(0,0,0,.45), inset 0 0 0 1px rgba(190,210,180,.12), inset 0 3px 10px rgba(0,0,0,.45);
        }
        .trt-theme-stone::before{ content:''; position:absolute; inset:6px; border:1px solid rgba(150,170,140,.2); border-radius:7px; pointer-events:none; }
        /* 纹章横幅标题（各主题差异化装饰） */
        .trt-title{ position:relative; text-align:center; font-size:15px; font-weight:900; letter-spacing:3px; padding:2px 34px 8px; margin-bottom:10px; }
        .trt-title::before,.trt-title::after{ position:absolute; top:1px; font-size:13px; }
        .trt-title::before{ left:8px; } .trt-title::after{ right:8px; }
        .trt-theme-parchment .trt-title{ color:#5a3a10; font-family:'Cinzel','Noto Serif SC',serif; border-bottom:2px solid rgba(139,101,32,.35); text-shadow:0 1px 0 rgba(255,244,210,.7); }
        .trt-theme-parchment .trt-title::before,.trt-theme-parchment .trt-title::after{ content:'❖'; color:#a07840; }
        .trt-theme-royal .trt-title{ color:#f0d48a; font-family:'Cinzel','Noto Serif SC',serif; border-bottom:2px solid rgba(212,175,55,.4); text-shadow:0 0 10px rgba(212,175,55,.5), 0 1px 2px rgba(0,0,0,.8); }
        .trt-theme-royal .trt-title::before,.trt-theme-royal .trt-title::after{ content:'⚜'; color:#d4af37; text-shadow:0 0 6px rgba(212,175,55,.6); }
        .trt-theme-stone .trt-title{ color:#b8c8a8; font-family:'Cinzel','Noto Serif SC',serif; border-bottom:2px solid rgba(150,170,140,.35); text-shadow:0 1px 0 rgba(0,0,0,.7), 0 -1px 0 rgba(255,255,255,.07); }
        .trt-theme-stone .trt-title::before,.trt-theme-stone .trt-title::after{ content:'◆'; color:#7a9a6a; }
        .trt-sub{ font-size:11px; opacity:.75; font-weight:normal; letter-spacing:0; margin-left:6px; }
        .trt-divider{ text-align:center; font-size:12px; letter-spacing:8px; margin:12px 0; opacity:.8; }
        .trt-theme-parchment .trt-divider{ color:#a08040; }
        .trt-theme-royal .trt-divider{ color:#d4af37; text-shadow:0 0 6px rgba(212,175,55,.4); }
        .trt-theme-stone .trt-divider{ color:#7a9a6a; }
        .trt-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:8px; }
        .trt-block{ border-radius:7px; padding:8px 10px; position:relative; }
        .trt-theme-parchment .trt-block{ background:linear-gradient(180deg, rgba(255,250,238,.75), rgba(240,226,196,.55)); border:1px solid rgba(139,101,32,.35); }
        .trt-theme-royal .trt-block{ background:linear-gradient(180deg, rgba(58,44,20,.5), rgba(30,22,10,.45)); border:1px solid rgba(212,175,55,.25); }
        .trt-theme-stone .trt-block{ background:linear-gradient(180deg, rgba(70,84,66,.4), rgba(42,52,42,.4)); border:1px solid rgba(150,170,140,.25); }
        .trt-block-title{ font-size:12px; font-weight:800; margin-bottom:6px; padding:2px 0 2px 8px; border-left:3px solid #a07840; }
        .trt-theme-parchment .trt-block-title{ color:#5a3a10; border-left-color:#a07840; }
        .trt-theme-royal .trt-block-title{ color:#f0d48a; border-left-color:#d4af37; }
        .trt-theme-stone .trt-block-title{ color:#b8c8a8; border-left-color:#7a9a6a; }
        .trt-field{ font-size:11px; line-height:1.7; }
        /* 建筑位槽位 */
        .trt-slots{ margin-top:8px; }
