        function formatCurrency(copper) {
            if (copper <= 0) return '0 铜盾';
            var gold = Math.floor(copper / 1000);
            var silver = Math.floor((copper % 1000) / 100);
            var rem = copper % 100;
            var parts = [];
            if (gold > 0) parts.push(gold + '金盾');
            if (silver > 0) parts.push(silver + '银盾');
            if (rem > 0 || parts.length === 0) parts.push(rem + '铜盾');
            return parts.join(' ');
