                                // 自我状态美化：判定增益/减益/中性（优先条目类型字段，缺失按名称关键词兜底）
        function relmapStatusMeta(v, name) {
            var type = (v && v.类型) ? v.类型 : '中性';
            if (type !== '增益' && type !== '减益') {
                var bad = /中毒|灼烧|冰冻|麻痹|诅咒|虚弱|流血|眩晕|昏迷|压制|恐惧|混乱|束缚|沉默|疲劳|中毒|致盲|减速/;
                var good = /祝福|守护|护盾|振奋|鼓舞|加速|再生|圣光|护体|增益|力量/;
                if (bad.test(name || '')) type = '减益';
                else if (good.test(name || '')) type = '增益';
                else type = '中性';
            }
            return {
                type: type,
                icon: type === '增益' ? '✨' : (type === '减益' ? '⚠️' : '▪️'),
                color: type === '增益' ? '#27ae60' : (type === '减益' ? '#c0392b' : '#7f8c8d'),
                label: type === '增益' ? '增益' : (type === '减益' ? '减益' : '中性')
            };
        }
        function renderRelationMap() {
            var $container = $('#list-npcs');
            if (!$container || !$container.length) return;
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var npcs = _.get(all, 'stat_data.主要NPC', {});
            var names = Object.keys(npcs);
            if (!names.length) { $container.html('<div class="jrpg-list-empty">暂无羁绊</div>'); return; }
            var heroName = _.get(all, 'stat_data.主角.基础信息.姓名', '') || '主角';
            var catOrder = ['家人', '盟友', '熟识', '陌生人', '初识', '仇敌'];
            var catIcon = { '家人': '👨‍👩‍👧', '盟友': '🤝', '熟识': '🙂', '陌生人': '👤', '初识': '❓️', '仇敌': '⚔️' };
            var catColor = { '家人': '#c0392b', '盟友': '#27ae60', '熟识': '#5a6472', '陌生人': '#7f8c8d', '初识': '#a08a6a', '仇敌': '#8e1f1f' };
            var cats = {};
            catOrder.forEach(function (c) { cats[c] = { items: [] }; });
            names.forEach(function (nm) {
                var v = npcs[nm] || {};
                var fav = _.clamp(parseInt(v.好感度, 10) || 0, -100, 100);
                // 关系分类缺失/无效 → 按好感度自动归类（规则约定；旧档/开场白旧结构兜底）：
                // 仇敌<0 / 陌生人0~9 / 熟识10~29 / 盟友30~79 / 家人80+
                function relmapAutoCat(fv) { return fv < 0 ? '仇敌' : (fv < 10 ? '陌生人' : (fv < 30 ? '熟识' : (fv < 80 ? '盟友' : '家人'))); }
                var cat = v.关系分类;
                if (!cat || ['家人', '盟友', '熟识', '陌生人', '初识', '仇敌'].indexOf(cat) === -1) cat = relmapAutoCat(fav);
                if (cat === '萍水相逢') cat = '初识'; // 旧名归一
                if (!cats[cat]) cat = '初识';
                cats[cat].items.push({ name: nm, v: v, fav: fav });
            });
            var html = '<div class="jrpg-relmap-doc">';
            html += '<div class="jrpg-relmap-root">' + escapeAttr(heroName) + '</div>';
            html += '<div class="jrpg-relmap-branch">';
            catOrder.forEach(function (c) {
                var C = cats[c];
                if (!C.items.length) return;
                html += '<div class="jrpg-relmap-group" style="color:' + catColor[c] + ';">' + catIcon[c] + ' ' + c + '</div>';
                C.items.forEach(function (it) {
                    var v = it.v;
                    html += '<div class="jrpg-relmap-doc-item" data-npc="' + escapeAttr(it.name) + '">' +
                        '<span class="dn">' + escapeAttr(it.name) + '</span>' +
                        '<button class="jrpg-del-tag" data-del-path="主要NPC.' + it.name + '" title="删除该NPC">🗑</button>' +
                        (v.身份 ? '<span class="did">' + escapeAttr(v.身份) + '</span>' : '') +
                        (v.当前位置 ? '<span class="dloc" style="font-size:10px;color:#2980b9;margin-left:4px;">📍 ' + escapeAttr(v.当前位置) + '</span>' : '') +
                        '<span class="dfav" style="color:' + relmapFavColor(it.fav) + ';">♥ ' + it.fav + '</span>' +
                        (v.关系描述 ? '<span class="drel">' + escapeAttr(v.关系描述) + '</span>' : '') +
                        '</div>';
                });
            });
            html += '</div>';
            html += '</div>';
            html += '<div class="jrpg-relmap-tip"></div>';
            $container.html(html);
        }

        function renderItemDetail(v) {
            var desc = v.其它说明 || '';
            var category = v.物品大类 || '';
            var equipSlot = v.装备位 || '无';
            var panelProps = v.面板效果 || {};
            var extraWords = v.附加词条 || {};
