            if (desc) html += '<div class="jrpg-item-detail-desc">' + desc + '</div>';
            html += '<div class="jrpg-item-detail-row">';
            if (category) html += '<span>📂 ' + category + '</span>';
            if (equipSlot && equipSlot !== '无') html += '<span>⚔️ 装备位: ' + equipSlot + '</span>';
            html += '</div>';

            var bpEntries = Object.entries(panelProps).filter(function(e) { return e[1] !== '' && e[1] !== undefined && e[1] !== null; });
            if (bpEntries.length > 0) {
                html += '<div class="jrpg-item-detail-subtitle" style="color:#6b4e31;">面板效果</div>';
