        /* 渲染同伴详情模态框（直接读取 Mvu 实时消息变量，保证装备/锁定后刷新到最新状态） */
        function renderCompanionDetail(compName) {
            if (!compName) return;
            if (typeof Mvu === 'undefined') return;
            // 规范化旧格式同伴数据（顶层 等级/HP/MP/SP → 基础状态），保证弹窗内数据正确
            normalizeCompanionData();
            // 当前楼层确认：优先读最新楼层，若无该同伴（如最新一层是玩家消息、其 stat_data 快照缺失）则回退 chat/全局变量，
            // 保证任何楼层都能打开并确认同伴档案
            var mvuData = null;
            try { mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' }); } catch (e) {}
            var c = _.get(mvuData, ['stat_data', '同伴', compName], null);
            if (!c) {
                try { var chatD = Mvu.getMvuData({ type: 'chat' }); c = _.get(chatD, ['stat_data', '同伴', compName], null); } catch (e) {}
            }
            if (!c) {
                try { var vars = getVariables({ type: 'chat' }); c = _.get(vars, ['stat_data', '同伴', compName], null); } catch (e) {}
            }
            if (!c) {
                try { var all = (typeof getAllVariables === 'function') ? getAllVariables() : {}; c = _.get(all, ['stat_data', '同伴', compName], null); } catch (e) {}
            }
            if (!c) return;

            var fav = _.clamp(c.好感度 || 0, 0, 100);
