            html += '<div style="display:flex; justify-content:flex-end; margin-top:4px;"><button class="jrpg-comp-full-lock-btn' + (c._全锁定 ? ' locked' : '') + '" data-comp="' + escapeAttr(compName) + '" title="' + (c._全锁定 ? '已一键锁定：点击解除全锁（属性+物品栏恢复可写）' : '一键锁定：属性+物品栏只读，拒绝 AI 删除/修改') + '">' + (c._全锁定 ? '🔒 解除全锁' : '🔐 一键全锁') + '</button></div>';
            html += '<div style="display:flex; align-items:center; gap:6px; font-size:14px;"><span style="color:' + favColor + ';">❤</span><div class="jrpg-npc-bar" style="width:80px; margin:0;"><div class="jrpg-npc-bar-fill" style="width:' + fav + '%;background:' + favColor + ';"></div></div><span class="jrpg-edit-val" data-path="同伴.' + compName + '.好感度" style="font-weight:bold; color:' + favColor + ';">' + fav + '</span></div>';
