                if (affiliation) html += '<div style="margin-bottom:4px;"><strong style="color:#8b6b4a;">所属势力：</strong>' + '<span class="jrpg-edit-val" data-path="同伴.' + compName + '.所属势力">' + affiliation + '</span></div>';
                if (backstory) html += '<div style="margin-top:8px; padding-top:8px; border-top:1px dashed #d2b48c;"><strong style="color:#8b6b4a;">背景故事：</strong><br>' + '<span class="jrpg-edit-val" data-path="同伴.' + compName + '.背景故事">' + backstory + '</span></div>';
                html += '</div></div>';
            }

            // 职业信息
            var jobInfo = _.get(c, '基础状态.职业信息', {});
            if (Object.keys(jobInfo).length > 0) {
                html += '<div class="jrpg-box" style="margin-bottom:15px;"><div class="jrpg-box-title">职业信息</div><div class="jrpg-list">';
                Object.entries(jobInfo).forEach(function(jobEntry){
                    html += '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>⚔️ ' + jobEntry[0] + '</span><span>Lv.' + (jobEntry[1].等级||1) + '</span></div><div class="jrpg-item-desc">技能点: ' + (jobEntry[1].技能点||0) + '</div></div>';
                });
                html += '</div></div>';
            }

            // 技能
            var skills = c.技能 || {};
            if (Object.keys(skills).length > 0) {
                html += '<div class="jrpg-box" style="margin-bottom:15px;"><div class="jrpg-box-title">技能</div><div class="jrpg-list">';
                Object.entries(skills).forEach(function(skEntry){
                    html += '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>' + skEntry[0] + '</span><button class="jrpg-del-tag" data-del-path="同伴.' + compName + '.技能.' + skEntry[0] + '" title="删除该技能">🗑</button></div><div class="jrpg-item-desc">' + (skEntry[1].描述 || '') + '</div></div>';
                });
                html += '</div></div>';
            }
            // 权能（同伴顶层字段，传说级自悟之力）
            var authorities = c.权能 || {};
            if (Object.keys(authorities).length > 0) {
                html += '<div class="jrpg-box" style="margin-bottom:15px;"><div class="jrpg-box-title">👑 权能</div><div class="jrpg-list">';
                Object.entries(authorities).forEach(function(auEntry){
                    html += '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#8e44ad;">👑 ' + auEntry[0] + '</span></div><div class="jrpg-item-desc">' + (auEntry[1].描述 || '') + '</div></div>';
                });
                html += '</div></div>';
            }
            // 奥义（同伴顶层字段，史诗级大招）
            var ultimates = c.奥义 || {};
            if (Object.keys(ultimates).length > 0) {
                html += '<div class="jrpg-box" style="margin-bottom:15px;"><div class="jrpg-box-title">🔥 奥义</div><div class="jrpg-list">';
                Object.entries(ultimates).forEach(function(ulEntry){
                    html += '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#c0392b;">🔥 ' + ulEntry[0] + '</span><button class="jrpg-del-tag" data-del-path="同伴.' + compName + '.奥义.' + ulEntry[0] + '" title="删除该奥义">🗑</button></div><div class="jrpg-item-desc">SP消耗: ' + (ulEntry[1].消耗SP || 0) + ' | MP消耗: ' + (ulEntry[1].消耗MP || 0) + ' | ' + (ulEntry[1].描述 || '') + '</div></div>';
                });
                html += '</div></div>';
            }
            // 装备栏 (重构为独立区块)
            var equip = c.装备栏 || {};
            var slotNames = ['头部', '颈部', '躯干', '腿部', '双手'];
            html += '<div class="jrpg-box" style="margin-bottom:15px;"><div class="jrpg-box-title">⚔️ 装备栏</div>';
            slotNames.forEach(function(slot) {
                var item = equip[slot] || {};
                var hasItem = item && Object.keys(item).length > 0 && !!item.物品名;
                html += '<div class="jrpg-equip-slot" style="padding:6px 10px; margin-bottom:4px;">';
                html += '<span class="slot-name" style="width:40px;">' + slot + '</span>';
                if (hasItem) {
                    var rank = item.品阶 || '普通';
                    html += '<span class="slot-item"><span class="rank-' + rank + '">[' + rank + ']</span> ' + escapeAttr(item.物品名);
                    html += renderEquipEffects(item);
                    html += '</span>';
                    html += '<button class="jrpg-comp-unequip-btn" data-comp="' + escapeAttr(compName) + '" data-slot="' + slot + '" style="background:#c0392b;color:#fff;border:2px solid #c0392b;border-radius:4px;padding:2px 8px;font-size:10px;cursor:pointer;">卸下</button>';
                } else {
                    html += '<span class="slot-item" style="color:#bbb;font-style:italic;">— 空 —</span>';
                }
                html += '</div>';
            });
            html += '</div>';

            // 物品栏
            html += renderCompanionInventorySection(c.物品栏, compName);

            html += '</div>'; // 右列结束
            html += '</div>'; // jrpg-grid-2col 结束

            // 心里话 (底部引言)
            var thought = safeStr(c.心里话);
            if (thought) {
                html += '<div style="margin-top:20px; padding:12px 15px; background:rgba(210,180,140,.2); border-left:4px solid #8b6b4a; border-radius:0 4px 4px 0; font-size:14px; font-style:italic; color:#6b4e31;">';
                html += '💭 "<span class="jrpg-edit-val" data-path="同伴.' + compName + '.心里话">' + thought + '</span>"';
                html += '</div>';
            }

            $('#comp-modal-body').html(html);
            $('#companion-detail-modal').css('display', 'flex');
        }

        /* 获取头像 URL：优先 $avatarMap，其次内置 AVATAR_MAP */
        function getAvatarUrl(name) {
            const all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            const customMap = _.get(all, 'stat_data.$avatarMap', {});
            return customMap[name] || AVATAR_MAP[name] || AVATAR_MAP["默认"];
        }

        /* 上传头像并保存 */
        async function uploadAvatar(characterName) {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.onchange = async (e) => {
                const file = e.target.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = async () => {
                    try {
                        const dataUrl = reader.result;
                        const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        const avatarMap = _.get(mvuData, 'stat_data.$avatarMap', {});
                        avatarMap[characterName] = dataUrl;
                        _.set(mvuData, 'stat_data.$avatarMap', avatarMap);
                        await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                        // 刷新头像显示
                        populateCharacterData();
                        toastr?.success?.('头像已更新！');
                    } catch (err) {
                        console.error('头像上传失败:', err);
                        toastr?.error?.('头像保存失败');
                    }
                };
                reader.readAsDataURL(file);
            };
            input.click();
        }

        /* 清理对象中键名为 "undefined" 的属性 */
        function cleanUndefinedKeys(obj) {
            if (!obj || typeof obj !== 'object') return;
            if (Array.isArray(obj)) {
                obj.forEach(cleanUndefinedKeys);
            } else {
                delete obj['undefined'];
                Object.values(obj).forEach(cleanUndefinedKeys);
            }
        }

        /* 渲染前端界面核心逻辑 */
        function populateCharacterData() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};

            // 合并持久锁定（聊天变量）——锁定状态必须跨楼层有效，
            // 保证任意楼层的界面实例都显示锁定（修复"下一楼层失效"）
            try { mergePersistLocksTo(all.stat_data); } catch (e) { console.error('[状态栏] 合并持久锁定失败:', e); }

            // 清理所有可能由 AI 引入的 "undefined" 键
            cleanUndefinedKeys(all.stat_data);

            // 同伴物品锁定守卫：拒绝删除（锁定物品若从同伴物品栏消失则自动还原）
            if (enforceCompItemLocks()) {
                all = typeof getAllVariables === 'function' ? getAllVariables() : {};
                cleanUndefinedKeys(all.stat_data);
            }

            // 同伴数据规范化：旧格式（顶层 等级/HP/MP/SP 等）自动迁移到 基础状态，保证预览卡显示等级/三维
            if (normalizeCompanionData()) {
                all = typeof getAllVariables === 'function' ? getAllVariables() : {};
                cleanUndefinedKeys(all.stat_data);
            }

            /* ================= 世界状态 ================= */
            $('#val-world-date').text(_.get(all, 'stat_data.世界.日期', '-') || '-');
            $('#val-world-time').text(_.get(all, 'stat_data.世界.时间', '-') || '-');
            $('#val-world-weather').text(_.get(all, 'stat_data.世界.天气', '-') || '-');
            $('#val-world-location').text(_.get(all, 'stat_data.世界.当前地点', '-') || '-');
            $('#val-world-pos').text(_.get(all, 'stat_data.世界.当前位置', '-') || '-');
            var tensionVal = _.get(all, 'stat_data.$flags.紧张度.当前值', 35);
            var tensionLevel = _.get(all, 'stat_data.$flags.紧张度.等级', '暗流期');
            $('#val-world-tension').html('<span class="' + getTensionClass(tensionLevel) + '">' + tensionLevel + ' (' + tensionVal + ')</span>');

            /* ================= 主角基础信息 ================= */
            var heroName = _.get(all, 'stat_data.主角.基础信息.姓名', '') || '';
            $('.jrpg-profile-name').text(heroName || '冒险者档案');
            $('#val-race').text(_.get(all, 'stat_data.主角.基础信息.种族', '-') || '-');
            $('#val-gender').text(_.get(all, 'stat_data.主角.基础信息.性别', '-') || '-');
            $('#val-age').text(_.get(all, 'stat_data.主角.基础信息.年龄', 0));
            $('#val-adv-rank').text(_.get(all, 'stat_data.主角.基础状态.冒险者等级', 'F'));

            // 新增：主角等阶（按总等级推导，符合位阶等级规则）
            var tier = _.get(all, 'stat_data.主角.等阶', '普通');
            var tierLv = _.get(all, 'stat_data.主角.基础状态.总等级', 0);
            var shownTier = displayTier(tier, tierLv);
            $('#val-tier').text(shownTier).attr('class', 'jrpg-comp-tier ' + getCompTierClass(shownTier));

            var money = _.get(all, 'stat_data.主角.资产与能力.货币', 0);
            $('.jrpg-profile-money').html(
                '<span title="可通过全局修改器修改">💰 <strong style="color: #d35400;">' + formatCurrency(money) + '</strong></span>');

            /* ================= 主角基础状态 ================= */
            var hpCur = _.get(all, 'stat_data.主角.基础状态.HP.当前', 0);
            var hpMax = _.get(all, 'stat_data.主角.基础状态.HP.最大', 0);
            $('#ctrl-hp-display').html('<span class="jrpg-edit-val" data-path="主角.基础状态.HP.当前">' + hpCur + '</span> / <span class="jrpg-edit-val" data-path="主角.基础状态.HP.最大">' + hpMax + '</span>');
            $('#val-hp-bar').css('width', (hpMax > 0 ? Math.min((hpCur / hpMax) * 100, 100) : 0) + '%');
            var mpCur = _.get(all, 'stat_data.主角.基础状态.MP.当前', 0);
            var mpMax = _.get(all, 'stat_data.主角.基础状态.MP.最大', 0);
            $('#ctrl-mp-display').html('<span class="jrpg-edit-val" data-path="主角.基础状态.MP.当前">' + mpCur + '</span> / <span class="jrpg-edit-val" data-path="主角.基础状态.MP.最大">' + mpMax + '</span>');
            $('#val-mp-bar').css('width', (mpMax > 0 ? Math.min((mpCur / mpMax) * 100, 100) : 0) + '%');
            var spCur = _.get(all, 'stat_data.主角.基础状态.SP.当前', 0);
            var spMax = _.get(all, 'stat_data.主角.基础状态.SP.最大', 0);
            $('#ctrl-sp-display').html('<span class="jrpg-edit-val" data-path="主角.基础状态.SP.当前">' + spCur + '</span> / <span class="jrpg-edit-val" data-path="主角.基础状态.SP.最大">' + spMax + '</span>');
            $('#val-sp-bar').css('width', (spMax > 0 ? Math.min((spCur / spMax) * 100, 100) : 0) + '%');
            var expCur = _.get(all, 'stat_data.主角.基础状态.经验值.当前', 0);
            var expMax = _.get(all, 'stat_data.主角.基础状态.经验值.升级所需', 100);
            $('#ctrl-exp-display').text(expCur + ' / ' + expMax);
            $('#val-exp-bar').css('width', (expMax > 0 ? Math.min((expCur / expMax) * 100, 100) : 0) + '%');

            /* ================= 主角防御值（随装备栏面板效果自动变化） ================= */
            var defTotal = _.get(all, 'stat_data.主角.防御值', 10);
            if (typeof defTotal !== 'number') defTotal = 10;
            var defBonus = 0;
            var equipAll = _.get(all, 'stat_data.主角.资产与能力.装备栏', {});
            ['头部', '颈部', '躯干', '腿部', '双手'].forEach(function(slot) {
                var it = equipAll[slot] || {};
                if (!it || typeof it !== 'object') return;
                var srcs = [it.面板效果, it.附加词条];
                srcs.forEach(function(src) {
                    if (!src || typeof src !== 'object') return;
                    defBonus += parseEffectNum(src.防御值);
                });
            });
            var defHtml = '<span style="font-weight:bold;color:#16a085;">' + defTotal + '</span>';
            if (defBonus > 0) defHtml += ' <span style="font-size:11px;color:#27ae60;">(装备+' + defBonus + ')</span>';
            $('#ctrl-def-display').html(defHtml);

            var attrs = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
            var attrIds = ['str', 'dex', 'con', 'int', 'wis', 'cha'];
            attrs.forEach(function(name, i) {
                var val = _.get(all, 'stat_data.主角.基础属性.' + name, 10);
                $('#val-' + attrIds[i]).html('<span class="jrpg-stat-val">' + val + '</span> <span class="jrpg-stat-mod">(' + getModifier(val) + ')</span>');
            });

            var totalLv = _.get(all, 'stat_data.主角.基础状态.总等级', 1);
            var unallocAttr = _.get(all, 'stat_data.主角.基础属性.未分配点数', 0);
            var unallocProf = _.get(all, 'stat_data.主角.基础状态.待分配职业等级', 0);
            // 全局修改器：总等级 / 未分配属性点 / 待分配职业等级 可直接点击修改（jrpg-edit-val 仅在修改模式下生效）
            $('#level-info-row').html('<span>总等级: <strong class="jrpg-edit-val" data-path="主角.基础状态.总等级">' + totalLv + '</strong></span>' + (unallocAttr > 0 ? '<span class="has-points">未分配属性点: <span class="jrpg-edit-val" data-path="主角.基础属性.未分配点数">' + unallocAttr + '</span></span>' : '<span>未分配属性点: <span class="jrpg-edit-val" data-path="主角.基础属性.未分配点数">0</span></span>') + (unallocProf > 0 ? '<span class="has-points">待分配职业等级: <span class="jrpg-edit-val" data-path="主角.基础状态.待分配职业等级">' + unallocProf + '</span></span>' : '<span>待分配职业等级: <span class="jrpg-edit-val" data-path="主角.基础状态.待分配职业等级">0</span></span>'));

            var upgradeNotify = _.get(all, 'stat_data.主角.基础状态.自身状态.升级通知', null);
            if (upgradeNotify && upgradeNotify.描述) {
                $('#upgrade-notify-banner').text('⬆ ' + upgradeNotify.描述).show();
            } else {
                $('#upgrade-notify-banner').hide();
            }

            var rawStatuses = _.get(all, 'stat_data.主角.基础状态.自身状态', {});
            var filteredStatuses = {};
            Object.entries(rawStatuses).forEach(function(e) { if (e[0] !== '升级通知') filteredStatuses[e[0]] = e[1]; });
            renderRecord($('#list-status'), filteredStatuses, function(k, v) {
                var meta = relmapStatusMeta(v, k);
                var dur = (v.持续 || v.持续轮数) ? ' <span style="color:#a07830;">⏳' + escapeAttr(String(v.持续 || v.持续轮数)) + '</span>' : '';
                return '<div class="jrpg-list-item" style="border-left:3px solid ' + meta.color + ';"><div class="jrpg-item-header"><span style="color:' + meta.color + ';">' + meta.icon + ' ' + k + '</span><button class="jrpg-del-tag" data-del-path="主角.基础状态.自身状态.' + k + '" title="删除该状态">🗑</button><span class="jrpg-status-badge jrpg-edit-val" data-path="主角.基础状态.自身状态.' + k + '.类型" style="background:' + meta.color + ';color:#fff;border-radius:4px;padding:0 6px;font-size:10px;margin-left:6px;">' + meta.label + '</span>' + dur + '</div><div class="jrpg-item-desc jrpg-edit-val" data-path="主角.基础状态.自身状态.' + k + '.描述">' + escapeAttr(v.描述 || '') + '</div></div>';
            }, '无异常状态');

            /* ============ 信仰（自身状态下方） ============ */
            var faithName = _.get(all, 'stat_data.主角.基础信息.信仰', '') || '无信仰';
            var faithDesc = _.get(all, 'stat_data.主角.基础信息.信仰简述', '') || '';
            var faithHtml = '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#f1c40f;">🙏 ' + faithName + '</span></div>';
            if (faithDesc) faithHtml += '<div class="jrpg-item-desc" style="color:#8b6b4a;font-size:12px;">' + faithDesc + '</div>';
            faithHtml += '</div>';
            $('#list-faith').html(faithHtml);

            /* ============ 种族 ============ */
            var baseInfo = _.get(all, 'stat_data.主角.基础信息', {});
            var raceName = baseInfo.种族 || '-';
            var raceMod = baseInfo.种族修正 || '';
            var raceHtml = '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>' + raceName + '</span></div>';
            if (raceMod) raceHtml += '<div class="jrpg-item-desc">' + raceMod + '</div>';
            raceHtml += '</div>';
            $('#list-race').html(raceHtml);
            /* ============ 魔力回路 ============ */
            var circuit = baseInfo.魔力回路 || {};
            var circuitGrade = circuit.品阶 || '无回路';
            var circuitDesc = circuit.描述 || '';
            var circuitHtml = '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>' + circuitGrade + '</span></div>';
            if (circuitDesc) circuitHtml += '<div class="jrpg-item-desc">' + circuitDesc + '</div>';
            circuitHtml += '</div>';
            $('#list-circuit').html(circuitHtml);

            /* ============ 资质（只读展示，与魔回路/种族同级；设置在首页创建器） ============ */
            if (typeof renderTalentInfo === 'function') { try { renderTalentInfo(); } catch (e) {} }

            renderRecord($('#list-classes'), _.get(all, 'stat_data.主角.基础状态.职业信息', {}), function(k, v) {
                var keyAttr = getJobKeyAttrs(k);
                var attrText = keyAttr ? ' | 关键属性: <strong style="color:#d35400;">' + keyAttr + '</strong>' : '';
                // 全局修改器：职业等级 / 剩余技能点 可直接点击修改（等级改大后升级脚本自动补 HP/MP/SP/技能点与总等级）
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>⚔️ ' + k + '</span><span>Lv.<span class="jrpg-edit-val" data-path="主角.基础状态.职业信息.' + escapeAttr(k) + '.等级">' + (v.等级 || 1) + '</span></span></div><div class="jrpg-item-desc">剩余技能点: <span class="jrpg-edit-val" data-path="主角.基础状态.职业信息.' + escapeAttr(k) + '.技能点">' + (v.技能点 || 0) + '</span>' + attrText + '</div></div>';
            }, '暂无职业');

            /* ================= 主角资产与能力 ================= */
            var inventoryData = _.get(all, 'stat_data.主角.资产与能力.物品栏', {});
            $('#list-inventory').html(renderInventoryCards(inventoryData));

            renderRecord($('#list-skills'), _.get(all, 'stat_data.主角.资产与能力.角色技能', {}), function(k, v) {
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>' + k + '</span><button class="jrpg-del-tag" data-del-path="主角.资产与能力.角色技能.' + k + '" title="删除该技能">🗑</button><span>Lv.' + (v.等级 || 0) + skillUpgradeSuffix('角色技能', k, v.等级) + '</span></div><div class="jrpg-item-desc">' + (v.描述 || '') + '</div></div>';
            }, '未掌握技能');
            renderRecord($('#list-magic'), _.get(all, 'stat_data.主角.资产与能力.魔法栏', {}), function(k, v) {
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#2980b9;">✦ ' + k + '</span><button class="jrpg-del-tag" data-del-path="主角.资产与能力.魔法栏.' + k + '" title="删除该魔法">🗑</button><span>Lv.' + (v.等级 || 0) + skillUpgradeSuffix('魔法栏', k, v.等级) + '</span></div><div class="jrpg-item-desc">MP消耗: ' + (v.消耗MP || 0) + ' | ' + (v.描述 || '') + '</div></div>';
            }, '未掌握魔法');
            renderRecord($('#list-divine'), _.get(all, 'stat_data.主角.资产与能力.神术栏', {}), function(k, v) {
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#f1c40f;">✧ ' + k + '</span><button class="jrpg-del-tag" data-del-path="主角.资产与能力.神术栏.' + k + '" title="删除该神术">🗑</button><span>Lv.' + (v.等级 || 0) + skillUpgradeSuffix('神术栏', k, v.等级) + '</span></div><div class="jrpg-item-desc">MP消耗: ' + (v.消耗MP || 0) + ' | ' + (v.描述 || '') + '</div></div>';
            }, '未信仰神明');
            renderRecord($('#list-blessings'), _.get(all, 'stat_data.主角.资产与能力.加护', {}), function(k, v) {
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#e67e22;">🌟 ' + k + '</span><span>Lv.' + (v.等级 || 0) + '</span></div><div class="jrpg-item-desc">' + (v.描述 || '') + '</div></div>';
            }, '无加护');
            renderRecord($('#list-authorities'), _.get(all, 'stat_data.主角.资产与能力.权能', {}), function(k, v) {
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#8e44ad;">👑 ' + k + '</span></div><div class="jrpg-item-desc">' + (v.描述 || '') + '</div></div>';
            }, '无权能');
            renderRecord($('#list-ultimates'), _.get(all, 'stat_data.主角.资产与能力.奥义', {}), function(k, v) {
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span style="color:#c0392b;">🔥 ' + k + '</span><button class="jrpg-del-tag" data-del-path="主角.资产与能力.奥义.' + k + '" title="删除该奥义">🗑</button></div><div class="jrpg-item-desc">SP消耗: ' + (v.消耗SP || 0) + ' | MP消耗: ' + (v.消耗MP || 0) + ' | ' + (v.描述 || '') + '</div></div>';
            }, '无奥义');

            /* ================= 任务 ================= */
            renderRecord($('#list-quests'), _.get(all, 'stat_data.主角.任务', {}), function(k, v) {
                var rankClass = getQuestRankClass(v.等级 || '普通');
                var statusClass = getQuestStatusClass(v.状态 || '进行中');
                return '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>📋 ' + k + '</span><button class="jrpg-del-tag" data-del-path="主角.任务.' + k + '" title="删除该任务">🗑</button><span class="jrpg-quest-status ' + statusClass + '">' + (v.状态 || '进行中') + '</span></div><div class="jrpg-quest-meta"><span class="jrpg-quest-rank ' + rankClass + '">' + (v.等级 || '普通') + '</span><span>📂 ' + (v.类型 || '-') + '</span><span>📨 ' + (v.来源 || '-') + '</span></div><div class="jrpg-quest-content">' + (v.内容 || '') + '</div></div>';
            }, '暂无接取的任务');

            /* ================= 契约英灵（英灵共鸣系统 v2） ================= */
            /* ---- 英灵静态档案：英灵固定，直接按名字匹配（执念文案/被动/英灵技名）；
                   运行时数值（残响/羁绊/进度/冷却）从 stat_data.英灵 读取 ---- */
            function matchSpiritArchive(name) {
                var archive = {
                    '断钢的勇者·艾莉卡': { 执念: '这一次，没有人再需要被牺牲。', 英灵技: '绝境斩杀·残响', 被动: [['钢铁执念Ⅰ', '力量+1'], ['断钢之志Ⅱ', '力量+2；每日1次，HP归零时以1HP存活'], ['绝境之势Ⅲ', '对精英级及以上敌人首次攻击伤害骰+1']] },
                    '燃尽的贤者·伊利亚': { 执念: '证明知识可以救下所有人。', 英灵技: '万象真理·残响', 被动: [['真理之眼Ⅰ', '智力+1'], ['万象解析Ⅱ', '智力+2；每日1次，施法失败可重投'], ['燃尽之理Ⅲ', 'MP上限+10%；每日1次，免疫一次魔力反噬']] },
                    '末代的神龙·科里维坦': { 执念: '极光……还亮着吗。', 英灵技: '半龙化 / 绝对零度龙息', 被动: [['龙威Ⅰ', '精英级以下魔兽自动恐惧（先攻检定+2）'], ['极寒之血Ⅱ', '寒冰抗性；体质+1'], ['龙之躯壳Ⅲ', '体质+2；每日1次，受到致命一击时伤害减半']] },
                    '被夺的魔女·莉莉丝': { 执念: '把我的东西……还给我。', 英灵技: '湮灭法则·残响', 被动: [['混沌腐蚀Ⅰ', '攻击附带暗属性腐蚀（每回合额外1d4伤害，持续2回合）'], ['异端之眼Ⅱ', '对深渊教廷相关法术/结界/伪装的侦测检定自动成功'], ['湮灭法则Ⅲ', '对"有信仰/有神明加护"的目标伤害+1d6']] },
                    '初代勇者雷恩': { 执念: '那兽人替老子去送了死……得知道他是谁。', 英灵技: '不讲武德的痛击', 被动: [['烂人的直觉Ⅰ', '暴击率+5%'], ['下三滥战术Ⅱ', '对精英级以下敌人命中+2'], ['活下来的本事Ⅲ', '敏捷+2；每日1次，逃跑/脱离检定自动成功']] },
                    '第四代魔女莎提拉': { 执念: '他到底……去了哪里？', 英灵技: '血祭·幽魂之拥', 被动: [['死气共鸣Ⅰ', '感知周围1公里内亡者（位置/死因/死亡时间）'], ['血祭之体Ⅱ', '对活物伤害+1d4（暗属性）；自身HP<50%时再+1d4'], ['幽魂之拥Ⅲ', '击杀敌人时回复自身HP上限5%']] },
                    '指引妖精莉耶芙': { 执念: '把这出戏，演到落幕。', 英灵技: '森之降临', 被动: [['甜美谎言Ⅰ', '说服/欺骗检定+1'], ['命运的巧合Ⅱ', '每日1次，让一次不利判定重投（结果可能更好——也可能更糟）'], ['黑山羊之吻Ⅲ', '濒死时获得一次"恶意祝福"：攻击+2持续3轮，但沾染深渊气息']] },
                    '小圣女索菲亚': { 执念: '那场讨伐……最后成功了吗？', 英灵技: '绝境圣壁', 被动: [['微光庇护Ⅰ', '受到伤害-1'], ['信仰之池Ⅱ', '每日1次，HP<30%时回复1d6+2'], ['绝境圣壁Ⅲ', '每日1次，抵挡一次精英级致命一击']] },
                    '小魔王伊莉丝': { 执念: '为什么我被创造出来……就是送死？', 英灵技: '弱者的反击', 被动: [['魔兽感知Ⅰ', '感知周围魔兽的情绪/饥饿/敌意方向'], ['陷阱大师Ⅱ', '布置/识破陷阱检定+2'], ['弱小者的反击Ⅲ', '受到史诗级及以上存在攻击时，第一次伤害-50%']] },
                    '盲目的莉莉娅': { 执念: '这世上……有没有不必用眼睛去换的结局？', 英灵技: '死亡回溯', 被动: [['结局之眼Ⅰ', '每场战斗开始前，获得一条关于本场战斗的模糊警示'], ['历史切片Ⅱ', '对"过去十年内"的事件记忆全知；历史/预言/考古检定+2'], ['因果偏移Ⅲ', '每日1次，在冒险者即将承受致命伤害时改写"那个瞬间"（代价：莉莉丝当晚无法对话）']] },
                    '圣光神索利昂': { 执念: '看见由她指引的勇者，走到自己选择的结局。', 英灵技: '神恩降临·残响', 被动: [['神选之眼Ⅰ', '社交洞察+1：感知交谈对象的意图与"勇者潜质"'], ['拂晓祝福Ⅱ', '每日1次，黎明时刻（或每日首次行动）的下一次检定+2'], ['神恩共鸣Ⅲ', 'HP<30%时，受到的下一次致命伤害转化为等同数值的HP回复（每日1次）']] },
                    '深渊的魅魔·阿丝茉德': { 执念: '体验一次"不被魅惑的爱"——让一个人真心爱上她，而不是被魔法迷住。', 英灵技: '魅魔领域·残响', 被动: [['天生媚骨Ⅰ', '魅力相关检定+1'], ['欲望低语Ⅱ', '对意志检定低于冒险者的目标，说服/魅惑/审讯检定+2'], ['沉沦之拥Ⅲ', '攻击被"沉沦/魅惑"状态影响的目标时伤害+1d6；击杀时回复自身HP上限5%']] }
                };
                if (!name) return null;
                /* 名称归一化：去掉 ·・/ 空格与「英灵」前缀，兼容 AI 写入的多种写法 */
                function normName(s) { return String(s).replace(/[·・\/\s]/g, '').replace(/^英灵/, ''); }
                var n = normName(name);
                for (var key in archive) {
                    if (archive.hasOwnProperty(key) && (n.indexOf(normName(key)) >= 0 || normName(key).indexOf(n) >= 0)) return archive[key];
                }
                return null;
            }
            /* 被动列表块：按羁绊档位显示解锁状态，匹配 stat_data.英灵.被动效果 判定"生效中" */
            function passiveBlockHtml(archive, bondTier, passives) {
                if (!archive || !archive.被动) return '';
                var unlockAt = [30, 60, 90];
                var html = '<div style="font-size:11px; margin:8px 0 3px; color:#6b2e6b;">共鸣被动</div>';
                for (var i = 0; i < archive.被动.length; i++) {
                    var p = archive.被动[i];
                    var idx = i + 1;
                    var unlocked = bondTier >= idx;
                    var active = false;
                    for (var k in passives) {
                        if (passives.hasOwnProperty(k) && (String(k).indexOf(p[0]) >= 0 || p[0].indexOf(String(k)) >= 0)) { active = true; break; }
                    }
                    html += '<div style="font-size:10px; line-height:1.6; ' + (unlocked ? 'color:#1e8449;' : 'color:#b2a49a;') + '">' +
                        (unlocked ? '●' : '○') + ' ' + p[0] + '：' + p[1] +
                        (unlocked && active ? ' <span style="color:#27ae60; font-weight:bold;">✔ 生效中</span>' : '') +
                        (unlocked && !active ? ' <span style="color:#7f8c8d;">（待AI写入生效）</span>' : '') +
                        (!unlocked ? ' <span style="color:#7f8c8d;">（羁绊' + unlockAt[i] + '解锁）</span>' : '') +
                        '</div>';
                }
                return html;
            }

            var spiritName = _.get(all, 'stat_data.英灵.名称', '');
            var $spiritContainer = $('#list-spirit');
            if (!spiritName) {
                $spiritContainer.html('<div class="jrpg-list-empty">暂无契约英灵</div>');
            } else {
                var spiritPower = _.clamp(_.get(all, 'stat_data.英灵.残响之力', 0), 0, 100);
                var spiritStatus = _.get(all, 'stat_data.英灵.状态', '苏醒');
                var spiritBond = _.clamp(_.get(all, 'stat_data.英灵.羁绊值', 0), 0, 100);
                var passives = _.get(all, 'stat_data.英灵.被动效果', {}) || {};
                var obsession = _.get(all, 'stat_data.英灵.执念', {}) || {};
                var skillInfo = _.get(all, 'stat_data.英灵.英灵技', {}) || {};
                var statusClass = spiritStatus === '苏醒' ? 'awake' : 'sleeping';
                var archive = matchSpiritArchive(spiritName);
                var obsText = (obsession.内容 && String(obsession.内容).trim()) ? obsession.内容 : (archive ? archive.执念 : '');
                var obsProgress = _.clamp(_.get(obsession, '进度', 0), 0, 100);
                var obsDone = !!obsession.是否完成;
                var skillName = (skillInfo.名称 && String(skillInfo.名称).trim()) ? skillInfo.名称 : (archive ? archive.英灵技 : '');
                var skillCd = _.get(skillInfo, '冷却', 0);
                var skillUsed = _.get(skillInfo, '已释放', 0);
                var bondTier = spiritBond >= 90 ? 3 : (spiritBond >= 60 ? 2 : (spiritBond >= 30 ? 1 : 0));
                var tierNames = ['未解锁', '被动Ⅰ', '被动Ⅱ', '被动Ⅲ'];

                var spiritHtml = '<div class="jrpg-spirit-card">' +
                    '<div class="jrpg-spirit-header"><span class="jrpg-spirit-name">' + spiritName + '</span><span class="jrpg-spirit-status ' + statusClass + '">' + spiritStatus + '</span></div>' +
                    /* 残响 */
                    '<div style="font-size:11px; margin-bottom:4px; color:#6b2e6b;">残响之力' + (spiritPower >= 100 && spiritStatus === '苏醒' && skillCd <= 0 ? ' <span style="color:#27ae60; font-weight:bold;">⚡ 可释放英灵技</span>' : '') + '</div>' +
                    '<div class="jrpg-resonance-bar-bg"><div class="jrpg-resonance-fill" style="width:' + spiritPower + '%;"></div><div class="jrpg-resonance-text">' + spiritPower + '%</div></div>' +
                    /* 羁绊 */
                    '<div style="display:flex; justify-content:space-between; font-size:11px; margin:8px 0 3px; color:#6b2e6b;"><span>羁绊值</span><span style="font-weight:bold; color:#1e8449;">' + spiritBond + ' <span style="color:#7f8c8d; font-weight:normal;">· ' + tierNames[bondTier] + '</span></span></div>' +
                    '<div style="background:#d4c4b7; height:10px; border-radius:5px; border:1px solid #27ae60; overflow:hidden; position:relative;"><div style="background:linear-gradient(90deg,#27ae60,#82e0aa); height:100%; width:' + spiritBond + '%; border-radius:5px;"></div></div>' +
                    /* 被动 */
                    passiveBlockHtml(archive, bondTier, passives) +
                    /* 执念 */
                    (obsText ? '<div style="font-size:11px; margin:8px 0 3px; color:#6b2e6b;">执念' + (obsDone ? ' <span style="color:#27ae60; font-weight:bold;">✔ 已完成</span>' : '') + '</div>' +
                        '<div style="font-size:10px; color:#4a3623; line-height:1.5; margin-bottom:4px;">「' + obsText + '」</div>' +
                        '<div style="background:#d4c4b7; height:10px; border-radius:5px; border:1px solid #c0392b; overflow:hidden; position:relative;"><div style="background:linear-gradient(90deg,#c0392b,#e8a878); height:100%; width:' + obsProgress + '%; border-radius:5px;"></div><div style="position:absolute; top:0; left:0; right:0; bottom:0; text-align:center; font-size:9px; font-weight:bold; color:#4a3623; line-height:10px;">' + obsProgress + '%</div></div>' : '') +
                    /* 英灵技 */
                    (skillName ? '<div style="font-size:11px; margin:8px 0 3px; color:#6b2e6b;">英灵技 · ' + skillName + '</div>' +
                        '<div style="font-size:10px; color:#7f8c8d;">' + (skillCd > 0 ? '⏳ 冷却中（剩余 ' + skillCd + '）' : '✓ 可用') + ' · 已释放 ' + skillUsed + ' 次</div>' : '') +
                    '</div>';
                $spiritContainer.html(spiritHtml);
            }

            /* ================= 同伴（精简卡片） ================= */
            var companions = _.get(all, 'stat_data.同伴', {});
            var $compContainer = $('#list-companions');
            if (!companions || Object.keys(companions).length === 0) {
                $compContainer.html('<div class="jrpg-list-empty">暂无同伴</div>');
            } else {
                var compHtml = '';
                Object.entries(companions).forEach(function(entry) {
                    var name = entry[0];
                    var c = entry[1];
                    var safeName = name.replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                    var fav = _.clamp(c.好感度 || 0, 0, 100);
                    var favColor = fav > 80 ? '#e74c3c' : (fav > 50 ? '#27ae60' : (fav > 25 ? '#f39c12' : '#7f8c8d'));
                    var avatarUrl = getAvatarUrl(name);
                    var cTier = displayTier(c.等阶, _.get(c, '基础状态.总等级', 0));

                    compHtml += '<div class="jrpg-comp-card" data-comp-name="' + escapeAttr(name) + '">';
                    compHtml += '<div class="jrpg-comp-header-wrapper" style="border-bottom:none; margin-bottom:0; padding-bottom:0;">';
                    compHtml += '<img class="jrpg-comp-avatar" src="' + avatarUrl + '" title="点击更换头像" style="cursor:pointer;" data-character="' + name + '">';
                    compHtml += '<div class="jrpg-comp-header-info">';
                    compHtml += '<div class="jrpg-comp-header-top"><div><span class="jrpg-comp-name">' + name + '</span><button class="jrpg-del-tag" data-del-path="同伴.' + name + '" title="删除该同伴（离队）">🗑</button>' + (c._全锁定 ? ' <span class="jrpg-item-lock-badge" title="已一键锁定：属性+物品栏只读，拒绝删除">🔒 全锁定</span>' : (c._属性锁定 ? ' <span class="jrpg-item-lock-badge" title="属性已锁定：AI 禁止修改，只能通过升级分配写入">🔒 属性锁定</span>' : '')) + '<span class="jrpg-comp-tier ' + getCompTierClass(cTier) + '">' + cTier + '</span></div><button class="jrpg-comp-full-lock-btn' + (c._全锁定 ? ' locked' : '') + '" data-comp="' + escapeAttr(name) + '" title="' + (c._全锁定 ? '点击解除全锁' : '一键锁定：属性+物品栏只读，拒绝删除') + '" style="margin-left:4px;">' + (c._全锁定 ? '🔒' : '🔐') + '</button></div>';

                    compHtml += '<div class="jrpg-comp-meta">' + (calcActorAge(c) !== null && calcActorAge(c) !== undefined ? calcActorAge(c) + '岁 · ' : '') + (safeStr(c.种族) ? safeStr(c.种族) + ' · ' : '') + 'Lv.' + (_.get(c, '基础状态.总等级', 1)) + ' · ' + (safeStr(c.身份, '-')) + '</div>';

                    // 状态条简显
                    var hpCur = _.get(c, '基础状态.HP.当前', 0), hpMax = _.get(c, '基础状态.HP.最大', 0);
                    var mpCur = _.get(c, '基础状态.MP.当前', 0), mpMax = _.get(c, '基础状态.MP.最大', 0);
                    var spCur = _.get(c, '基础状态.SP.当前', 0), spMax = _.get(c, '基础状态.SP.最大', 0);
                    compHtml += '<div style="display:flex; gap:8px; font-size:10px; margin-top:4px;">';
                    compHtml += '<span style="color:#c0392b">❤ ' + hpCur + '/' + hpMax + '</span>';
                    compHtml += '<span style="color:#2980b9">◆ ' + mpCur + '/' + mpMax + '</span>';
                    compHtml += '<span style="color:#d35400">▲ ' + spCur + '/' + spMax + '</span>';
                    compHtml += '</div>';

                    // 好感度简显
                    compHtml += '<div style="display:flex; align-items:center; gap:4px; font-size:10px; margin-top:4px;">';
                    compHtml += '<span style="color:' + favColor + ';">❤</span>';
                    compHtml += '<div class="jrpg-npc-bar" style="flex:1; margin:0;"><div class="jrpg-npc-bar-fill" style="width:' + fav + '%;background:' + favColor + ';"></div></div>';
                    compHtml += '<span style="font-weight:bold; color:' + favColor + ';">' + fav + '</span>';
                    compHtml += '</div>';

                    compHtml += '</div></div>'; // header
                    compHtml += '<div class="jrpg-comp-click-hint">🔍 点击查看详情</div>';
                    compHtml += '</div>'; // jrpg-comp-card
                });
                $compContainer.html(compHtml);
            }

            /* ================= 召唤物（独立路径 stat_data.召唤物.{名字}） ================= */
            var summons = _.get(all, 'stat_data.召唤物', {});
            var $summonContainer = $('#list-summons');
            if (!summons || Object.keys(summons).length === 0) {
                $summonContainer.html('<div class="jrpg-list-empty">暂无召唤物</div>');
            } else {
                var sumHtml = '';
                Object.entries(summons).forEach(function(entry) {
                    var name = entry[0];
                    var s = entry[1];
                    var safeName = name.replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                    var sTier = displayTier(s.等阶, s.等级);

                    sumHtml += '<div class="jrpg-comp-card jrpg-summon-card">';
                    sumHtml += '<div class="jrpg-comp-header-wrapper">';
