            "不死人": [
                { lvl: 1, n: "余烬之躯", c: 1, d: "[被动·核心] 你不会真正死亡。HP归零时，灵魂残留在最近的「篝火」（本源锚点）处重燃，恢复50%HP与全部SP。重生后敌人仇恨重置。每次长休限用3次，超过则需找到篝火处手动休整恢复。" },
                { lvl: 1, n: "黑色铠甲", c: 1, d: "[被动] 全身被漆黑的全覆式铠甲笼罩，不见面容。基础防御+3，对毒素、流血、诅咒拥有基础抗性（减免50%）。因铠甲沉重，游泳速度减半。" },
                { lvl: 1, n: "全能武备", c: 1, d: "[被动] 作为战斗人偶的万能适配体质，可熟练使用一切简易/军用武器、轻甲/中甲/重甲。切换武器不消耗额外动作。" },
                { lvl: 3, n: "篝火传承", c: 2, d: "[动作] 在篝火（本源锚点）处休整至少10分钟，恢复全部HP/SP，重置余烬之躯的使用次数，并清除所有非诅咒类负面状态。同一篝火每日限用1次。" },
                { lvl: 3, n: "战斗翻滚", c: 2, d: "[反应] SP2。受击前瞬间向前方或侧方翻滚闪避，本轮内物理攻击防御+5（翻滚无敌帧）。翻滚后若紧接近战攻击，该攻击检定+2。" },
                { lvl: 3, n: "韧性意志", c: 2, d: "[被动] 战斗人偶的躯壳不会被轻易打断。受到攻击时不会因伤害而失去动作连贯性（免疫攻击中断和击退），且硬直时间减半。" },
                { lvl: 5, n: "处决", c: 3, d: "[主动] SP3。对陷入倒地、眩晕、束缚或失衡状态的敌人发动致命一击。该次攻击自动暴击，伤害骰取最大值。若目标等阶不高于自身，直接触发即死判定——力量豁免DC(8+力量修正)，失败则被一击毙命。" },
                { lvl: 5, n: "灵魂附魔", c: 3, d: "[附赠] SP2。将本源意志的碎片短暂附着于武器上，持续3轮。可选择：火焰（+2d6火伤/对魔族+1d6）、暗月（+2d6力场/穿透护盾）、雷电（+2d6雷伤/暴击范围+1）。切换附魔需重新消耗SP。" },
                { lvl: 5, n: "余火状态", c: 3, d: "[主动] SP4。激活体内残存的本源之力，铠甲缝隙中透出橙红色余烬光芒，持续5轮。期间：HP上限+30%，近战攻击额外+1d8火伤，移动速度+10尺。结束后陷入1级力竭。" },
                { lvl: 7, n: "武器质变", c: 4, d: "[被动·升级] 在篝火处可花费10分钟重塑手中武器的属性。包括：厚重（力量修正+2）、锋利（敏捷修正+2）、熟练（双修正取高）、雷电（附加雷伤）、火焰（附加火伤）、暗月（附加力场穿透）。每次仅能维持一种质变，可随时在篝火切换。" },
                { lvl: 7, n: "盾反", c: 4, d: "[反应] SP3。持盾时在受击瞬间精准格挡。成功则完全抵消该次近战伤害，并使攻击者陷入1轮大硬直（可接【处决】）。对大型及以上体型敌人的盾反仅抵消伤害，不造成硬直。" },
                { lvl: 7, n: "原力迸发", c: 4, d: "[主动] SP3。从铠甲中爆发出一圈无形的冲击波，击退周围10尺内所有敌人，造成2d6+力量修正的力场伤害。敏捷豁免DC14失败者倒地。" },
                { lvl: 9, n: "幽邃灵魂", c: 5, d: "[被动] 在篝火处长休后，获得临时的「幽邃记忆」——可选择一项基础属性+2（持续至下次篝火长休），或习得一种消耗性技能（由GM裁定）。幽邃记忆随篝火长休重置。" },
                { lvl: 9, n: "血源回响", c: 5, d: "[被动] 每亲手击杀一个敌人，恢复1d6HP与1SP。击杀精英/首领级敌人时，额外获得一个暂时性的「灵魂碎片」——可储存最多3枚，每枚可在篝火长休时兑换为等级×2的额外经验值或一项临时增益。" },
                { lvl: 9, n: "大剑精通", c: 5, d: "[被动] 双手持重型武器（大剑/大斧/大锤）时，攻击检定+2，伤害骰+1d6。且每次命中可打断正在蓄力的敌方术式（需力量对抗）。" },
                { lvl: 11, n: "钢铁守护", c: 6, d: "[主动] SP5。将黑色铠甲化为绝对壁垒，持续2轮。期间：防御+8，免疫一切物理暴击和背刺，所有元素抗性+50%。但移动速度减半，且无法翻滚。" },
                { lvl: 11, n: "余烬爆发", c: 6, d: "[被动·升级] 余火状态下，每次近战命中触发小范围爆炸（半径5尺），对周围敌人造成2d6火伤。且余火状态持续时间延长至8轮，力竭降级消失。" },
                { lvl: 11, n: "双持战技", c: 6, d: "[被动] 可双持两把非重型的武器，进行双武器战斗时副手攻击不再减值，且主手命中后可用附赠动作立刻追加一次副手攻击。" },
                { lvl: 13, n: "薪王化身", c: 7, d: "[主动] SP8。彻底点燃体内的本源碎片，铠甲缝隙喷涌出金色的火焰。全属性+3，所有武器攻击附带3d8神圣火焰伤害，免疫一切恐惧/魅惑/即死，移动速度翻倍，持续5轮。每日1次。持续期间每秒流失最大HP的2%，可提前解除。" },
