                    { min: 5, max: 8, name: '超凡阶' },
                    { min: 9, max: 12, name: '精英阶' },
                    { min: 13, max: 16, name: '史诗阶' },
                    { min: 17, max: 20, name: '传说阶' },
                    { min: 21, max: 999, name: '神话阶' }
                ];
                var byLv = {};
                filtered.forEach(function(sk) { var lv = sk.lvl || 1; (byLv[lv] = byLv[lv] || []).push(sk); });
                var lvKeys = Object.keys(byLv).map(Number).sort(function(a, b) { return a - b; });
                var bandIdBase = jobName.replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                var bandSections = [];
                BANDS.forEach(function(band, bi) {
                    var lvs = lvKeys.filter(function(lv) { return lv >= band.min && lv <= band.max; });
                    if (!lvs.length) return;
                    var bandSkills = lvs.reduce(function(arr, lv) { return arr.concat(byLv[lv]); }, []);
                    var learnedCount = bandSkills.filter(function(sk) {
                        var t = (isFuse && sk.type) ? sk.type : skillTypeOf(sk, jobName);
                        return !!(learned[t] && learned[t][sk.n]);
                    }).length;
                    var isCurrent = jobLv >= band.min && jobLv <= band.max;
                    bandSections.push({ band: band, lvs: lvs, count: bandSkills.length, learnedCount: learnedCount, isCurrent: isCurrent });
                });
                if (bandSections.length && !bandSections.some(function(s) { return s.isCurrent; })) {
                    // 角色等级超出全部已解锁段（如高等级低阶树）：展开最后一段兜底
                    bandSections[bandSections.length - 1].isCurrent = true;
                }
                bandSections.forEach(function(sec) {
                    var bandId = 'lvband-' + bandIdBase + '-' + sec.band.min;
                    var open = (window.__isuriaFoldState && window.__isuriaFoldState['#' + bandId] !== undefined) ? window.__isuriaFoldState['#' + bandId] : sec.isCurrent;
                    html += '<div style="font-weight:bold;color:#5a4430;margin:8px 0 0;font-size:12px;background:rgba(139,107,74,0.1);border-radius:4px;padding:4px 8px;cursor:pointer;user-select:none;" data-fold-target="#' + bandId + '" title="点击折叠/展开">';
                    html += '📚 ' + sec.band.name + ' <span style="font-size:10px;color:#8b6b4a;font-weight:normal;">Lv.' + sec.band.min + (sec.band.max <= 20 ? '-' + sec.band.max : '+') + ' · ' + sec.count + ' 技能' + (sec.learnedCount ? ' · 已学 ' + sec.learnedCount : '') + '</span>' + (sec.isCurrent ? ' <span style="font-size:10px;color:#27ae60;font-weight:normal;">📍当前</span>' : '');
                    html += '<span class="jrpg-fold-arrow" style="float:right;color:#8b6b4a;">' + (sec.isCurrent ? '▾' : '▸') + '</span></div>';
                    html += '<div id="' + bandId + '" style="display:' + (sec.isCurrent ? '' : 'none') + ';">';
                    sec.lvs.forEach(function(lv) {
                        var locked = jobLv < lv;
                        html += '<div style="font-weight:bold;color:' + (locked ? '#aaa' : '#8b6b4a') + ';margin:8px 0 2px;font-size:12px;border-bottom:1px dashed #d2b48c;">Lv.' + lv + (locked ? ' <span style="color:#e74c3c;font-size:10px;font-weight:normal;">🔒 需' + escapeAttr(jobName) + ' ' + lv + '级</span>' : '') + '</div>';
                        byLv[lv].forEach(function(sk) {
                            // 融合技能自带 type；普通技能用描述前缀推断
                            var type = (isFuse && sk.type) ? sk.type : skillTypeOf(sk, jobName);
                            var skillName = sk.n || '';
                            if (!skillName) return;
                            var typeIcon = type === '魔法' ? '✦' : (type === '神术' ? '✧' : '⚔️');
                            var isLearned = !!(learned[type] && learned[type][skillName]);
                            var cost = parseInt(sk.c, 10) || 1;
                            var spNotEnough = cost > totalSp;
                            html += '<div class="jrpg-list-item" style="' + (isLearned ? 'opacity:0.75;' : (locked || spNotEnough ? 'opacity:0.55;' : '')) + '">';
                            html += '<div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(skillName) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + type + ']</span></span>';
                            if (isLearned) html += '<span style="color:#27ae60;font-size:11px;font-weight:bold;">✅ 已学习</span>';
                            else if (locked) html += '<span style="color:#e74c3c;font-size:11px;">🔒 需 ' + lv + '级</span>';
                            else if (spNotEnough) html += '<button class="jrpg-btn-sm" disabled style="background:#bbb;color:#fff;border-color:#bbb;padding:2px 10px;font-size:11px;cursor:not-allowed;" title="需要 ' + cost + ' 点技能点，当前可用 ' + totalSp + ' 点">技能点不足</button>';
                            else html += '<button class="jrpg-btn-sm ' + (isFuse ? 'jrpg-vs-learn' : 'jrpg-st-learn') + '" data-job="' + escapeAttr(jobName) + '" data-skill="' + escapeAttr(skillName) + '" data-type="' + type + '" style="background:#2980b9;color:#fff;border-color:#2980b9;padding:2px 10px;font-size:11px;">学习 (-' + cost + '点)</button>';
                            html += '</div>';
                            html += '<div class="jrpg-item-desc">' + escapeAttr(sk.d || '') + (isFuse && sk.lvl ? '　<span style="color:#e74c3c;">[需融合 Lv.' + sk.lvl + ']</span>' : '') + '</div>';
                            html += '</div>';
                        });
                    });
                    html += '</div>';
                });
                }
                html += '</div>';
                html += '</div>';
            });
            $container.html(html);
        }

        // 学习职业技能：从 dbSkills 取定义，校验职业等级与技能点，写入对应技能栏
        async function learnSkillTreeSkill(jobName, skillName, type) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var jobInfo = _.get(stat, '主角.基础状态.职业信息', {});
                var jf = jobElemFilter(jobName);
                var skDef = null;
                // 先查自定义技能树（$customSkillTrees[职业]），再查内置技能库（dbSkills）
                var cst = _.get(stat, '$customSkillTrees', {});
                Object.keys(cst).forEach(function (cj) {
                    var cBase = (typeof jobElemFilter === 'function') ? jobElemFilter(cj).base : cj;
                    if (cBase !== jf.base && cj !== jobName) return;
                    var vMap = cst[cj] || {};
                    Object.keys(vMap).forEach(function (vn) {
                        var vData = vMap[vn] || {};
                        (vData.skills || []).forEach(function (sk) { if (sk && sk.n === skillName && !skDef) skDef = sk; });
                    });
                });
                if (!skDef) {
                    ((typeof dbSkills !== 'undefined' && dbSkills[jf.base]) || []).forEach(function (sk) { if (sk.n === skillName) skDef = sk; });
                }
                if (!skDef) { if (window.toastr) toastr.error('未找到职业技能「' + skillName + '」的定义'); return; }
                // 元素流派校验（如「元素法师（水）」只允许 水/无元素通用 技能）
                if (!jobSkillAllowed(jobName, skDef)) {
                    var es2 = detectSkillElements(skDef);
                    if (window.toastr) toastr.error('「' + skillName + '」属于[' + (es2.join('、') || '无元素') + ']流派，不在当前职业（' + jobName + '）允许的流派内');
                    return;
                }
                // 校验职业等级
                var jobLv = parseInt(jobInfo[jobName] && jobInfo[jobName].等级, 10) || 1;
                if (jobLv < (skDef.lvl || 1)) { if (window.toastr) toastr.error('需 ' + jobName + ' Lv.' + skDef.lvl + ' 才能学习'); return; }
                var cost = parseInt(skDef.c, 10) || 1;
                var slotKey = skillSlotKeyOf(type);
                var slot = _.get(stat, '主角.资产与能力.' + slotKey, {});
                if (slot[skillName]) { if (window.toastr) toastr.warning('已掌握「' + skillName + '」，无需重复学习'); return; }
                // 技能点：优先扣该职业技能点，不足扣其它职业
                var realJob = jobInfo[jobName] ? jobName : null;
                if (!realJob) { Object.keys(jobInfo).forEach(function(k) { if (!realJob && (k.indexOf(jobName) !== -1 || jobName.indexOf(k) !== -1)) realJob = k; }); }
                var totalJobSp = 0;
                Object.keys(jobInfo).forEach(function(k) { totalJobSp += parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0; });
                if (totalJobSp < cost) { if (window.toastr) toastr.error('技能点不足！学习「' + skillName + '」需要 ' + cost + ' 点，当前可用 ' + totalJobSp + ' 点'); return; }
                var jobSp = realJob ? (parseInt(_.get(jobInfo, [realJob, '技能点'], 0), 10) || 0) : 0;
                if (jobSp >= cost) { _.set(jobInfo, [realJob || jobName, '技能点'], jobSp - cost); }
                else {
                    var remain = cost;
                    if (realJob) { _.set(jobInfo, [realJob, '技能点'], 0); remain -= jobSp; }
                    Object.keys(jobInfo).forEach(function(k) {
                        if (remain <= 0) return;
                        var sp = parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0;
                        if (sp > 0) { var take = Math.min(sp, remain); _.set(jobInfo, [k, '技能点'], sp - take); remain -= take; }
                    });
                }
                var entry = { 描述: skDef.d || '', 等级: 1 };
                if (type !== '技能') {
                    entry.消耗MP = parseInt(skDef.mp, 10) || parseMpCost(skDef.d) || 0;
                }
                slot[skillName] = entry;
                _.set(stat, '主角.资产与能力.' + slotKey, slot);
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                // 上下文注入「技能学习」通知（不产生楼层，下一次生成生效）
                try { await emitAllocPrompt('【技能学习】' + jobName + ' 学习了职业技能「' + skillName + '」（消耗技能点 -' + cost + '）。该技能已写入技能栏，请勿重复学习或修改。', 'skill_'); } catch (e) { console.error('注入技能学习通知失败:', e); }
                if (window.toastr) toastr.success('✅ 已学习「' + skillName + '」！');
                populateCharacterData();
            } catch (e) {
                console.error('学习职业技能失败:', e);
                if (window.toastr) toastr.error('学习失败：' + (e && e.message ? e.message : e));
            }
        }

        function renderVariantSkills() {
