            // 同伴专属技能树（顶层键为同伴名）不在主角变体技能 tab 渲染
            var compNames = Object.keys(_.get(all, 'stat_data.同伴', {}));

            var filteredTrees = {};
            Object.keys(trees).forEach(function(k) { if (compNames.indexOf(k) === -1) filteredTrees[k] = trees[k]; });
            trees = filteredTrees;

            if (!trees || Object.keys(trees).length === 0) {
                $container.html('<div class="jrpg-list-empty">暂无变体技能树。请先在「角色创建」页生成并保存变体技能树。</div>');
