                    html += '<div style="font-weight:bold;color:#8e44ad;margin:10px 0 4px 0;border-bottom:2px solid #8e44ad;background:rgba(142,68,173,0.06);padding:4px 8px;border-radius:4px;">🎨 ' + escapeAttr(jobName) + ' · ' + escapeAttr(variantName) + (fuseLv ? ' <span style="font-size:10px;color:#8e44ad;">继承Lv.' + fuseLv + '</span>' : '') + '</div>';
