                        { min: 13, max: 16, name: '史诗阶' },
                        { min: 17, max: 20, name: '传说阶' },
                        { min: 21, max: 999, name: '神话阶' }
                    ];
                    function vType(sk) { var t = sk.type || '技能'; return t === '魔法' ? '魔法' : (t === '神术' ? '神术' : '技能'); }
                    function vLearned(sk) {
                        var typeName = vType(sk);
                        var skillName = sk.n || '';
                        if (!learned[typeName]) return false;
                        if (learned[typeName][skillName]) return true;
                        var hit = false;
                        Object.keys(learned[typeName]).forEach(function(learnedKey) {
                            if (!hit && (learnedKey === skillName || learnedKey.indexOf('] ' + skillName) !== -1 || learnedKey.indexOf('「' + skillName + '」') !== -1)) hit = true;
                        });
                        return hit;
