                    var vLvKeys = Object.keys(vByLv).map(Number).sort(function(a, b) { return a - b; });
                    var vBandIdBase = (jobName + '-' + variantName).replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                    var vSections = [];
