                        var learnedCount = bandSkills.filter(function(sk) { return sk.n && vLearned(sk); }).length;
                        vSections.push({ band: band, lvs: lvs, count: bandSkills.length, learnedCount: learnedCount });
                    });
                    // 默认展开：第一个含「未学习且未锁等级」技能的段；全学完则展开最后一段
