                                var lvlLocked = fuseLv > 0 && sk.lvl && (parseInt(sk.lvl, 10) > fuseLv);
                                var spNotEnough = cost > totalSp;
                                html += '<div class="jrpg-list-item" style="' + (isLearned ? 'opacity:0.75;' : ((lvlLocked || spNotEnough) ? 'opacity:0.55;' : '')) + '">';
                                html += '<div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(skillName) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + typeName + ']</span></span>';
