                                } else if (spNotEnough) {
                                    html += '<button class="jrpg-btn-sm" disabled style="background:#bbb;color:#fff;border-color:#bbb;padding:2px 10px;font-size:11px;cursor:not-allowed;" title="需要 ' + cost + ' 点技能点，当前可用 ' + totalSp + ' 点">技能点不足</button>';
                                } else {
