        async function learnVariantSkill(jobName, skillName, type) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var trees = _.get(stat, '$customSkillTrees', {});

                var skDef = null;
                Object.keys(trees[jobName] || {}).forEach(function(vn) {
                    (trees[jobName][vn].skills || []).forEach(function(sk) {
                        if (sk.n === skillName) skDef = sk;
                    });
                });
                if (!skDef) { if (window.toastr) toastr.error('未找到变体技能「' + skillName + '」的定义'); return; }
                var cost = parseInt(skDef.c, 10) || 1;

                var slotKey = type === '魔法' ? '魔法栏' : (type === '神术' ? '神术栏' : '角色技能');
                var slot = _.get(stat, '主角.资产与能力.' + slotKey, {});
                if (slot[skillName]) { if (window.toastr) toastr.warning('已掌握「' + skillName + '」，无需重复学习'); return; }

                // 定位职业技能点（兼容职业信息键名与变体技能树职业名不一致的情况）
                var jobInfo = _.get(stat, '主角.基础状态.职业信息', {});
                var realJob = null;
                if (jobInfo[jobName]) realJob = jobName;
                else {
                    Object.keys(jobInfo).forEach(function(k) {
                        if (!realJob && (k.indexOf(jobName) !== -1 || jobName.indexOf(k) !== -1)) realJob = k;
                    });
                }
                // 汇总所有职业技能点作为可用技能点（学习只消耗「技能点」，与 SP 条无关）
                var totalJobSp = 0;
                Object.keys(jobInfo).forEach(function(k) { totalJobSp += (parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0); });
                var jobSp = realJob ? (parseInt(_.get(jobInfo, [realJob, '技能点'], 0), 10) || 0) : 0;
                if (totalJobSp < cost) {
                    if (window.toastr) toastr.error('技能点不足！学习「' + skillName + '」需要 ' + cost + ' 点技能点，当前可用技能点 ' + totalJobSp);
                    return;
                }

                // 优先扣对应职业技能点，不足再扣其它职业技能点
                if (jobSp >= cost) {
                    _.set(jobInfo, [realJob || jobName, '技能点'], jobSp - cost);
                } else {
                    var remain = cost;
                    if (realJob) { _.set(jobInfo, [realJob, '技能点'], 0); remain -= jobSp; }
                    Object.keys(jobInfo).forEach(function(k) {
                        if (remain <= 0) return;
                        var sp = parseInt(_.get(jobInfo, [k, '技能点'], 0), 10) || 0;
                        if (sp > 0) {
                            var take = Math.min(sp, remain);
                            _.set(jobInfo, [k, '技能点'], sp - take);
                            remain -= take;
                        }
                    });
                }
                var entry = { 描述: skDef.d || '', 等级: 1 };
                if (type !== '技能') entry.消耗MP = parseInt(skDef.mp, 10) || parseMpCost(skDef.d) || 0;
                slot[skillName] = entry;
