                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });

                // 上下文注入「技能学习」通知（不产生楼层，下一次生成生效）
                try { await emitAllocPrompt('【技能学习】' + jobName + ' 学习了变体技能「' + skillName + '」（消耗技能点 -' + cost + '）。该技能已写入技能栏，请勿重复学习或修改。', 'skill_'); } catch (e) { console.error('注入技能学习通知失败:', e); }

