            compNames.forEach(function(n) {
                var lv = _.get(comps[n], '基础状态.总等级', 1);
                html += '<option value="' + escapeAttr(n) + '"' + (n === companionSkillTarget ? ' selected' : '') + '>' + escapeAttr(n) + ' (Lv.' + lv + ')</option>';
            });
            html += '</select></div>';
