            html += '<div style="flex:1;min-width:170px;"><div style="font-size:11px;color:#6b4e31;margin-bottom:3px;">生成方式</div><div style="font-size:11px;color:#7f8c8d;padding:5px 0;">🧠 generateRaw（屏蔽预设/上下文，只读同伴变量）</div></div>';
