                var learned = allocLearned(c, companionSkillTarget);
                skills.forEach(function(sk) {
                    var type = sk.type || '技能';
                    var skillName = sk.n || '';
                    if (!skillName) return;
                    var typeName = type === '魔法' ? '魔法' : (type === '神术' ? '神术' : '技能');
                    var typeIcon = type === '魔法' ? '✦' : (type === '神术' ? '✧' : '⚔️');
                    var lvl = parseInt(sk.lvl, 10) || 1;
                    var cost = parseInt(sk.c, 10) || 1;
                    var isLearned = !!learned[skillName];
                    if (!isLearned) {
                        Object.keys(learned).forEach(function(k) { if (!isLearned && (k === skillName || k.indexOf('] ' + skillName) !== -1 || k.indexOf('「' + skillName + '」') !== -1)) isLearned = true; });
                    }
                    var lvlLocked = lvl > maxJobLv;
                    var spNotEnough = cost > totalSp;
                    html += '<div class="jrpg-list-item" style="' + (isLearned ? 'opacity:0.75;' : ((lvlLocked || spNotEnough) ? 'opacity:0.55;' : '')) + '">';
                    html += '<div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(skillName) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + typeName + '] · 需Lv.' + lvl + '</span></span>';
                    if (isLearned) html += '<span style="color:#27ae60;font-size:11px;font-weight:bold;">✅ 已学习</span>';
                    else if (lvlLocked) html += '<span style="color:#e74c3c;font-size:11px;font-weight:bold;">🔒 需职业 Lv.' + lvl + '</span>';
                    else if (spNotEnough) html += '<button class="jrpg-btn-sm" disabled style="background:#bbb;color:#fff;border-color:#bbb;padding:2px 10px;font-size:11px;cursor:not-allowed;" title="需要 ' + cost + ' 点技能点，当前可用 ' + totalSp + ' 点">技能点不足</button>';
                    else html += '<button class="jrpg-btn-sm jrpg-cs-learn" data-comp="' + escapeAttr(companionSkillTarget) + '" data-skill="' + escapeAttr(skillName) + '" data-type="' + typeName + '" style="background:#8e44ad;color:#fff;border-color:#8e44ad;padding:2px 10px;font-size:11px;">学习 (-' + cost + '点)</button>';
