        }

        function updateFuseLevelHint() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var jobInfo = _.get(all, 'stat_data.主角.基础状态.职业信息', {});
            var a = $('#fuse-job-a').val();
            var b = $('#fuse-job-b').val();
            var la = parseInt(jobInfo[a] && jobInfo[a].等级, 10) || 0;
            var lb = parseInt(jobInfo[b] && jobInfo[b].等级, 10) || 0;
            var $hint = $('#fuse-level-hint');
            if (!$hint.length) return;
            if (a && b) {
                $hint.html('⚖️ ' + escapeAttr(a) + ' Lv.' + la + ' ＋ ' + escapeAttr(b) + ' Lv.' + lb + ' → <strong>融合等级 Lv.' + (la + lb) + '</strong>（技能树将继承该等级）');
            } else {
                $hint.html('');
            }
        }

        async function generateFusedSkillTree() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var jobInfo = _.get(all, 'stat_data.主角.基础状态.职业信息', {});
            var $status = $('#fuse-status');
            var a = $('#fuse-job-a').val();
            var b = $('#fuse-job-b').val();
            if (!a || !b) { if (window.toastr) toastr.error('请先选择主职业与副职业'); return; }
            if (a === b) { if (window.toastr) toastr.error('主职业与副职业不能相同！请选择两个<strong>不同</strong>职业进行融合。'); return; }
            if (typeof generate === 'undefined') {
                $status.show().html('❌ 当前环境不支持 AI 生成（generate 不可用）。').css('color', '#c0392b');
                return;
            }
            var la = parseInt(jobInfo[a] && jobInfo[a].等级, 10) || 1;
            var lb = parseInt(jobInfo[b] && jobInfo[b].等级, 10) || 1;
            var combined = la + lb;
            var treeMaxLv = Math.min(20, combined); // 技能树等级上限：继承融合等级，封顶 20
            var fusedName = ($('#fuse-name').val() || '').trim() || (a + '×' + b);
            var refA = (typeof dbSkills !== 'undefined' && dbSkills[a]) || [];
            var refB = (typeof dbSkills !== 'undefined' && dbSkills[b]) || [];
            // 关键等级：1,3,5,…,19（奇数）＋ 等级上限本身，保证每个关键等级都有技能
            var keyLevels = [];
            for (var kl = 1; kl <= treeMaxLv; kl += 2) keyLevels.push(kl);
            if (keyLevels[keyLevels.length - 1] !== treeMaxLv) keyLevels.push(treeMaxLv);
            var skillCount = Math.min(24, keyLevels.length * 2);

            $status.show().html('🔄 正在请求 AI 融合「' + escapeAttr(a) + '(Lv.' + la + ')」×「' + escapeAttr(b) + '(Lv.' + lb + ')」→ 融合等级 Lv.' + combined + ' …').css('color', '#8e44ad');

            var promptText = '以下是角色当前的职业信息，请将两个职业融合生成一套全新的融合技能树。\n\n';
            promptText += '【当前职业】\n';
            promptText += '主职业：' + a + '（Lv.' + la + '）\n';
            promptText += '副职业：' + b + '（Lv.' + lb + '）\n';
            promptText += '融合职业名（拟定）：' + fusedName + '\n';
            promptText += '融合等级（继承两职业等级之和）：Lv.' + combined + '（技能树等级上限 Lv.' + treeMaxLv + '）\n';
            promptText += '主职业默认技能参考：' + (refA.length ? refA.map(function(s) { return s.n + '(Lv' + (s.lvl || 1) + ')'; }).join('、') : '（无内置数据）') + '\n';
            promptText += '副职业默认技能参考：' + (refB.length ? refB.map(function(s) { return s.n + '(Lv' + (s.lvl || 1) + ')'; }).join('、') : '（无内置数据）') + '\n\n';
            promptText += '请融合两者定位与核心机制，生成一套与两者默认技能树既有联系又完全不同的融合技能树。\n';
            promptText += '【必须】以下每个关键等级都要有至少 1 个技能：' + keyLevels.join('、') + '（共 ' + keyLevels.length + ' 个等级点）。\n';
            promptText += '低级等级（Lv.1/3/5）可多放 1~2 个技能；总技能数约 ' + skillCount + ' 个，且不得少于 ' + keyLevels.length + ' 个。\n';
            promptText += '每个技能的 lvl 必须落在上述关键等级上（可多技能共用同一等级）。\n\n';
            promptText += '请严格按照以下 JSON 格式输出技能数据（不要输出其他文字，只输出 JSON）：\n';
            promptText += '```json\n[\n  { "n": "技能名称", "t": "类型（技能/魔法/神术）", "c": "学习消耗（技能点数值，1~5）", "lvl": "所需融合职业等级（必须为关键等级之一：' + keyLevels.join('/') + '）", "d": "技能效果描述，需同时体现 ' + a + ' 与 ' + b + ' 的特色，说明机制与数值" },\n  ...\n]\n```';

            try {
                // 职业融合用 generateRaw（屏蔽预设/上下文）→ 同样打非 RP 标志，跳过紧张度世界动态注入
                window.__ISURIA_NON_RP__ = true;
                try {
                var result = await generateRaw({
                user_input: promptText,
                should_silence: true,
                overrides: {
                    world_info_before: '', world_info_after: '', persona_description: '',
                    char_description: '', char_personality: '', scenario: '',
                    dialogue_examples: '', chat_history: { prompts: [] }
                }
            });
                } finally { window.__ISURIA_NON_RP__ = false; }
                $status.html('✅ AI 响应完成，正在解析…').css('color', '#8e44ad');
                var parsed = extractJsonArray(result);
                if (!Array.isArray(parsed)) throw new Error('返回数据不是数组');
                var validSkills = [];
                parsed.forEach(function(sk) {
                    if (sk.n && typeof sk.n === 'string' && sk.n.trim()) {
                        var rawType = String(sk.t || sk.type || '').trim();
                        var skType = rawType === '魔法' || rawType === '神术' ? rawType : '技能';
                        var lvl = Math.min(parseInt(sk.lvl, 10) || 1, combined);
                        validSkills.push({ n: sk.n.trim(), type: skType, c: parseInt(sk.c, 10) || 1, lvl: lvl, mp: parseInt(sk.mp, 10) || parseMpCost(sk.d), d: (sk.d || '').trim() });
                    }
                });
                if (!validSkills.length) throw new Error('未解析出有效技能数据');
                _fusedSkills = validSkills;
                _fusedPending = { jobA: a, levelA: la, jobB: b, levelB: lb, fusedName: fusedName, combinedLevel: combined };
                renderFusePreview();
                $('.jrpg-fuse-save').prop('disabled', false);
                $status.html('✅ AI 融合完成！生成 ' + validSkills.length + ' 个技能（融合等级 Lv.' + combined + '）。确认后点击「保存到变量」。').css('color', '#27ae60');
            } catch (err) {
                console.error('融合技能树生成失败:', err);
                $status.html('❌ AI 生成失败：' + (err && err.message ? err.message : err)).css('color', '#c0392b');
            }
        }

        function renderFusePreview() {
            var $preview = $('#fuse-preview');
            if (!$preview || !$preview.length) return;
            if (!_fusedPending || !_fusedSkills.length) { $preview.html(''); return; }
            var p = _fusedPending;
            var html = '<div style="font-size:12px;color:#6b4e31;margin-bottom:6px;border-top:1px dashed #d2b48c;padding-top:8px;line-height:1.5;">🔀 融合「' + escapeAttr(p.fusedName) + '」预览 · <strong>继承等级 Lv.' + p.combinedLevel + '</strong> · ' + _fusedSkills.length + ' 技能：</div>';
            _fusedSkills.forEach(function(sk) {
                var typeIcon = sk.type === '魔法' ? '✦' : (sk.type === '神术' ? '✧' : '⚔️');
                html += '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(sk.n) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + sk.type + '] · Lv.' + sk.lvl + '</span></span><span style="font-size:10px;color:#d35400;">-' + sk.c + ' 技能点</span></div><div class="jrpg-item-desc">' + escapeAttr(sk.d || '') + '</div></div>';
            });
            $preview.html(html);
        }

        async function saveFusedSkillTree() {
            if (!_fusedPending || !_fusedSkills.length) { if (window.toastr) toastr.warning('请先 AI 生成融合技能树'); return; }
            if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
            var p = _fusedPending;
            try {
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = mvuData.stat_data || (mvuData.stat_data = {});
                var trees = _.get(stat, '$customSkillTrees', {});
                if (!trees[p.fusedName]) trees[p.fusedName] = {};
                trees[p.fusedName]['职业融合'] = {
                    skills: _fusedSkills,
                    level: p.combinedLevel,
                    fusedFrom: [p.jobA, p.jobB]
                };
                _.set(stat, '$customSkillTrees', trees);
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });

                // 完成职业信息合并：移除源职业、加入融合职业（等级=继承等级、技能点=两源之和）、三维守恒
                // 由升级脚本执行，避免「源职业 + 融合职业」并存导致三维重复计骰
                var fuseApi = (typeof window !== 'undefined' && window.升级脚本) || (window.parent && window.parent.升级脚本);
                if (fuseApi && typeof fuseApi.执行融合 === 'function') {
                    try { await fuseApi.执行融合({ target: '主角', jobA: p.jobA, jobB: p.jobB, fusedName: p.fusedName, combinedLevel: p.combinedLevel }); } catch (fe) { console.error('执行融合失败:', fe); if (window.toastr) toastr.error('执行融合失败：' + (fe && fe.message ? fe.message : fe)); }
                } else {
                    // 降级：手动合并职业信息（移除源职业、加入融合职业），确保原技能树被直接清除
                    var ji = _.get(stat, '主角.基础状态.职业信息', {});
                    var spSum = (parseInt(ji[p.jobA] && ji[p.jobA].技能点, 10) || 0) + (parseInt(ji[p.jobB] && ji[p.jobB].技能点, 10) || 0);
                    delete ji[p.jobA];
                    delete ji[p.jobB];
                    ji[p.fusedName] = { 等级: p.combinedLevel, 技能点: spSum };
                    _.set(stat, '主角.基础状态.职业信息', ji);
                    await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                    console.warn('升级脚本未找到，已手动合并职业（源职业技能树已清除）；三维/技能点未守恒补齐，建议加载「升级代码」脚本后重新确认');
                    if (window.toastr) toastr.warning('⚠️ 未找到「升级代码」脚本，已手动合并职业并清除源职业技能树；三维/技能点未自动补齐，建议加载升级代码后重新确认');
                }

                try { await createChatMessages([{ role: 'system', message: '【职业融合】已将「' + p.jobA + '(Lv.' + p.levelA + ')」与「' + p.jobB + '(Lv.' + p.levelB + ')」融合为「' + p.fusedName + '」（继承等级 Lv.' + p.combinedLevel + '）。融合技能树已保存至变量 $customSkillTrees；源职业「' + p.jobA + '」「' + p.jobB + '」已从职业信息合并移除，职业信息中只保留「' + p.fusedName + '」Lv.' + p.combinedLevel + '，HP/MP/SP/技能点由升级脚本守恒处理。请勿重新添加源职业、勿重复计算三维或技能点。' }]); } catch (e) { console.error('输出融合消息失败:', e); }
                if (window.toastr) toastr.success('✅ 融合技能树已保存！\n融合职业：' + p.fusedName + '\n继承等级：Lv.' + p.combinedLevel);
                populateCharacterData();
            } catch (e) {
                console.error('保存融合技能树失败:', e);
                if (window.toastr) toastr.error('保存失败：' + (e && e.message ? e.message : e));
            }
        }

        /* ================= 🧩 技能融合（勾选低级技能 → AI 融合生成中级技能 → 扣技能点写入技能栏） ================= */
        var _skillFusionTarget = '主角';
        var _skillFusionSkills = [];
        var _skillFusionPending = null;
        var _skillFusionResult = [];

        // 读取目标技能栏：主角=角色技能/魔法栏/神术栏；同伴=技能。按等级升序（低级优先）
        function collectSkillFusionSkills(stat, target) {
            var list = [];
            if (target === '主角') {
                var actor = stat.主角 || {};
                [['角色技能', '技能'], ['魔法栏', '魔法'], ['神术栏', '神术']].forEach(function (s) {
                    var slot = _.get(actor, '资产与能力.' + s[0], {});
                    Object.keys(slot).forEach(function (k) {
                        var v = slot[k] || {};
                        list.push({ key: k, slot: s[0], type: s[1], 等级: parseInt(v.等级, 10) || 1, 描述: v.描述 || '', 消耗MP: v.消耗MP || 0 });
                    });
                });
            } else {
                var comp = _.get(stat, ['同伴', target], null);
                var slot = (comp && comp.技能) || {};
                Object.keys(slot).forEach(function (k) {
                    var v = slot[k] || {};
                    list.push({ key: k, slot: '技能', type: '技能', 等级: parseInt(v.等级, 10) || 1, 描述: v.描述 || '', 消耗MP: v.消耗MP || 0 });
                });
            }
            list.sort(function (a, b) { return a.等级 - b.等级 || (a.key < b.key ? -1 : 1); });
            return list;
        }

        function skillFusionTotalSp(stat, target) {
            var actor = allocActor(stat, target);
            var jobInfo = (actor && actor.基础状态 && actor.基础状态.职业信息) || {};
            var total = 0;
            Object.keys(jobInfo).forEach(function (j) { total += parseInt(jobInfo[j].技能点, 10) || 0; });
            return total;
        }

        function skillFusionGroups(sel, ratio) {
            if (sel.length < 2) return [];
            var groups = [];
            for (var i = 0; i < sel.length; i += ratio) groups.push(sel.slice(i, i + ratio));
            var last = groups[groups.length - 1];
            if (last && last.length === 1 && groups.length >= 2) { groups.pop(); groups[groups.length - 1] = groups[groups.length - 1].concat(last); }
            return groups;
        }

        function skillFusionLevelOf(group) {
            var maxLv = 1;
            group.forEach(function (sk) { maxLv = Math.max(maxLv, sk.等级); });
            return Math.min(20, maxLv + 2);
        }
        function renderSkillFusion() {
            var $container = $('#skill-fusion');
            if (!$container || !$container.length) return;
            _skillFusionPending = null;
            _skillFusionResult = [];
            var stat = allocStat();
            var targets = ['主角'].concat(Object.keys(_.get(stat, '同伴', {})));
            if (!targets.length) { $container.html('<div class="jrpg-list-empty">暂无角色数据</div>'); return; }
            if (targets.indexOf(_skillFusionTarget) === -1) _skillFusionTarget = '主角';
            var target = _skillFusionTarget;
            _skillFusionSkills = collectSkillFusionSkills(stat, target);
            var totalSp = skillFusionTotalSp(stat, target);
            var html = '<div style="display:flex;gap:8px;flex-wrap:wrap;">';
            html += '<div style="flex:1;min-width:130px;"><div style="font-size:11px;color:#6b4e31;margin-bottom:3px;">融合目标</div><select id="sf-target" style="width:100%;padding:5px;font-size:12px;background:#fff;border:1px solid #8b6b4a;border-radius:3px;color:#4a3623;">';
            targets.forEach(function (n) { html += '<option value="' + escapeAttr(n) + '"' + (n === target ? ' selected' : '') + '>' + escapeAttr(n) + '</option>'; });
            html += '</select></div>';
            html += '<div style="flex:1;min-width:110px;"><div style="font-size:11px;color:#6b4e31;margin-bottom:3px;">融合比例</div><select id="sf-ratio" style="width:100%;padding:5px;font-size:12px;background:#fff;border:1px solid #8b6b4a;border-radius:3px;color:#4a3623;"><option value="3">3合1</option><option value="2">2合1</option></select></div>';
            html += '<div style="flex:1;min-width:110px;"><div style="font-size:11px;color:#6b4e31;margin-bottom:3px;">保留最高级数量</div><input id="sf-keep" type="number" min="0" value="0" style="width:100%;padding:5px;font-size:12px;background:#fff;border:1px solid #8b6b4a;border-radius:3px;color:#4a3623;box-sizing:border-box;"></div>';
            html += '<div style="flex:1;min-width:110px;"><div style="font-size:11px;color:#6b4e31;margin-bottom:3px;">可用技能点</div><div style="font-size:13px;color:#d35400;padding:5px 0;font-weight:bold;">' + totalSp + ' 点</div></div>';
            html += '</div>';
            html += '<div style="font-size:11px;color:#7f8c8d;margin:8px 0 4px;line-height:1.6;">当前技能 ' + _skillFusionSkills.length + ' 个（按等级升序）。勾选要融合的低级技能，未勾选的保留不动。</div>';
            html += '<div class="jrpg-list" style="max-height:220px;overflow-y:auto;">';
            if (!_skillFusionSkills.length) {
                html += '<div class="jrpg-list-empty">该目标技能栏为空，没有可融合的技能</div>';
            } else {
                _skillFusionSkills.forEach(function (sk, idx) {
                    var typeIcon = sk.type === '魔法' ? '✦' : (sk.type === '神术' ? '✧' : '⚔️');
                    var mpText = sk.消耗MP ? ' <span style="color:#2980b9;">MP' + sk.消耗MP + '</span>' : '';
                    html += '<div class="jrpg-list-item"><label style="display:flex;align-items:flex-start;gap:6px;cursor:pointer;margin:0;"><input type="checkbox" class="sf-skill-check" data-idx="' + idx + '" checked style="margin-top:3px;"><span style="flex:1;">' + typeIcon + ' <strong>' + escapeAttr(sk.key) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + sk.type + '] · Lv.' + sk.等级 + '</span>' + mpText + '<div style="font-size:11px;color:#4a3623;line-height:1.4;">' + escapeAttr(sk.描述) + '</div></span></label></div>';
                });
            }
            html += '</div>';
            html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">';
            html += '<button class="jrpg-btn-sm" id="sf-auto-check" style="width:auto;padding:5px 12px;font-size:12px;background:#7f8c8d;color:#fff;border:2px solid #7f8c8d;border-radius:4px;">按「保留数量」自动勾选</button>';
            html += '<button class="jrpg-btn-sm jrpg-sf-gen" style="width:auto;padding:6px 14px;font-size:12px;background:#2980b9;color:#fff;border:2px solid #2980b9;border-radius:4px;">🤖 AI 生成融合技能</button>';
            html += '<button class="jrpg-btn-sm jrpg-sf-save" style="width:auto;padding:6px 14px;font-size:12px;background:#8e44ad;color:#fff;border:2px solid #8e44ad;border-radius:4px;" disabled>💾 保存到技能栏</button>';
            html += '</div>';
            html += '<div id="sf-status" style="font-size:12px;color:#8e44ad;margin-top:8px;line-height:1.5;display:none;"></div>';
            html += '<div id="sf-preview" style="margin-top:8px;"></div>';
            $container.html(html);
            updateSkillFusionCheckCount();
        }
        function autoCheckSkillFusion() {
            var keep = Math.max(0, Math.min(parseInt($('#sf-keep').val(), 10) || 0, _skillFusionSkills.length));
            var keepIdx = {};
            for (var i = _skillFusionSkills.length - keep; i < _skillFusionSkills.length; i++) keepIdx[i] = true;
            $('#skill-fusion .sf-skill-check').each(function () {
                $(this).prop('checked', !keepIdx[parseInt($(this).data('idx'), 10)]);
            });
            updateSkillFusionCheckCount();
        }

        function selectedSkillFusionSkills() {
            var sel = [];
            $('#skill-fusion .sf-skill-check:checked').each(function () {
                var idx = parseInt($(this).data('idx'), 10);
                if (_skillFusionSkills[idx]) sel.push(_skillFusionSkills[idx]);
            });
