            else msg = '已勾选 ' + sel.length + ' 个低级技能 → 预计融合成 ' + groups.length + ' 个中级技能';
            if (msg) $status.show().html('📋 ' + msg).css('color', sel.length < 2 ? '#c0392b' : '#8e44ad');
            else $status.hide();
        }

        async function generateSkillFusion() {
            var $status = $('#sf-status');
            var stat = allocStat();
            var target = _skillFusionTarget;
            var sel = selectedSkillFusionSkills();
            if (sel.length < 2) { if (window.toastr) toastr.error('请至少勾选 2 个技能参与融合'); return; }
            if (typeof generateRaw !== 'function') { $status.show().html('❌ 当前环境不支持 AI 生成（generateRaw 不可用）。').css('color', '#c0392b'); return; }
            var ratio = parseInt($('#sf-ratio').val(), 10) || 3;
            var groups = skillFusionGroups(sel, ratio);
            if (!groups.length) { if (window.toastr) toastr.error('没有可融合的技能组（每组至少 2 个技能）'); return; }
            if (skillFusionTotalSp(stat, target) < groups.length) { if (window.toastr) toastr.error('职业技能点不足：融合 ' + groups.length + ' 个中级技能至少需要 ' + groups.length + ' 点'); return; }

            var promptText = '以下是角色当前技能栏中的部分低级技能，请将它们融合成更高级的技能。\n\n';
            promptText += '【融合目标】' + target + '\n';
            promptText += '【融合规则】每组技能融合成 1 个更高一级的技能；融合后等级 = 组内最高等级 + 2（封顶 20）。\n\n';
            promptText += '【待融合技能组】（共 ' + groups.length + ' 组）\n';
            groups.forEach(function (g, gi) {
                promptText += '第' + (gi + 1) + '组（融合后 Lv.' + skillFusionLevelOf(g) + '）：' + g.map(function (sk) { return sk.key + '(Lv.' + sk.等级 + ')' + (sk.描述 ? '｜' + sk.描述 : ''); }).join('、') + '\n';
            });
            promptText += '\n请为每组生成一个融合技能，融合后的技能需继承并升华组内源技能的核心特色，效果数值应强于单个源技能。\n';
            promptText += '【必须】输出 JSON 数组，元素个数与技能组数一致（' + groups.length + ' 个）：\n';
            promptText += '```json\n[\n  { "n": "融合技能名称", "t": "类型（技能/魔法/神术）", "c": "学习消耗（技能点数值，1~5）", "d": "效果描述，说明机制与数值，MP/SP 消耗写进描述开头（如 MP6 | ...）" },\n  ...\n]\n```';

            $status.show().html('🔄 正在请求 AI 融合 ' + sel.length + ' 个低级技能 → ' + groups.length + ' 个中级技能 …').css('color', '#8e44ad');
            try {
                window.__ISURIA_NON_RP__ = true;
                try {
                    var result = await generateRaw({
                        user_input: promptText,
                        should_silence: true,
                        overrides: {
                            world_info_before: '', world_info_after: '', persona_description: '',
                            char_description: '', char_personality: '', scenario: '',
                            dialogue_examples: '', chat_history: { prompts: [] }
                        }
                    });
                } finally { window.__ISURIA_NON_RP__ = false; }
                $status.html('✅ AI 响应完成，正在解析…').css('color', '#8e44ad');
                var parsed = extractJsonArray(result);
                if (!Array.isArray(parsed)) throw new Error('返回数据不是数组');
                var valid = [];
                parsed.slice(0, groups.length).forEach(function (sk, i) {
                    if (sk.n && typeof sk.n === 'string' && sk.n.trim()) {
                        var rawType = String(sk.t || sk.type || '').trim();
                        var skType = rawType === '魔法' || rawType === '神术' ? rawType : '技能';
                        valid.push({ n: sk.n.trim(), type: skType, c: Math.max(1, parseInt(sk.c, 10) || 1), d: (sk.d || '').trim(), fusedLvl: skillFusionLevelOf(groups[i]) });
                    }
                });
                if (!valid.length) throw new Error('未解析出有效技能数据');
                _skillFusionPending = { target: target, groups: groups.slice(0, valid.length) };
                _skillFusionResult = valid;
                renderSkillFusionPreview();
                $('.jrpg-sf-save').prop('disabled', false);
                $status.html('✅ AI 融合完成！生成 ' + valid.length + ' 个融合技能。确认后点击「保存到技能栏」（将扣除对应职业技能点）。').css('color', '#27ae60');
            } catch (err) {
                console.error('技能融合生成失败:', err);
                $status.html('❌ AI 生成失败：' + (err && err.message ? err.message : err)).css('color', '#c0392b');
            }
        }
        function renderSkillFusionPreview() {
            var $preview = $('#sf-preview');
            if (!$preview || !$preview.length) return;
            if (!_skillFusionPending || !_skillFusionResult.length) { $preview.html(''); return; }
            var p = _skillFusionPending;
            var srcCount = p.groups.reduce(function (n, g) { return n + g.length; }, 0);
            var html = '<div style="font-size:12px;color:#6b4e31;margin-bottom:6px;border-top:1px dashed #d2b48c;padding-top:8px;line-height:1.5;">🧩 融合预览 · 目标「' + escapeAttr(p.target) + '」 · 源技能 ' + srcCount + ' 个 → 融合技能 ' + _skillFusionResult.length + ' 个：</div>';
            _skillFusionResult.forEach(function (sk) {
                var typeIcon = sk.type === '魔法' ? '✦' : (sk.type === '神术' ? '✧' : '⚔️');
                html += '<div class="jrpg-list-item"><div class="jrpg-item-header"><span>' + typeIcon + ' <strong>' + escapeAttr(sk.n) + '</strong> <span style="font-size:10px;color:#8e44ad;">[' + sk.type + '] · Lv.' + sk.fusedLvl + '</span></span><span style="font-size:10px;color:#d35400;">-' + sk.c + ' 技能点</span></div><div class="jrpg-item-desc">' + escapeAttr(sk.d || '') + '</div></div>';
            });
            $preview.html(html);
        }

        async function saveSkillFusion() {
            if (!_skillFusionPending || !_skillFusionResult.length) { if (window.toastr) toastr.warning('请先 AI 生成融合技能'); return; }
            if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
            var p = _skillFusionPending;
            try {
                var mvuData = currentMvuData();
                var stat = mvuData.stat_data;
                var actor = allocActor(stat, p.target);
                if (!actor) { if (window.toastr) toastr.error('未找到「' + p.target + '」数据'); return; }
                var jobInfo = (actor.基础状态 && actor.基础状态.职业信息) || {};
                var totalSp = 0;
                Object.keys(jobInfo).forEach(function (j) { totalSp += parseInt(jobInfo[j].技能点, 10) || 0; });
                var totalCost = _skillFusionResult.reduce(function (s, sk) { return s + sk.c; }, 0);
                if (totalSp < totalCost) { if (window.toastr) toastr.error('职业技能点不足！保存需要 ' + totalCost + ' 点，当前 ' + totalSp + ' 点'); return; }

                // 1) 删除被融合的源技能
                var srcNames = [];
                p.groups.forEach(function (g) {
                    g.forEach(function (sk) {
                        var slotRel = p.target === '主角' ? ('资产与能力.' + sk.slot) : sk.slot;
                        var slot = _.get(actor, slotRel, {});
                        delete slot[sk.key];
                        _.set(actor, slotRel, slot);
                        srcNames.push(sk.key);
                    });
                });

                // 2) 写入融合技能
                _skillFusionResult.forEach(function (sk) {
                    var slotPath = allocSlotPath(p.target, sk.type);
                    var slot = _.get(actor, slotPath, {});
                    var entry = { 描述: sk.d || '', 等级: sk.fusedLvl };
                    if (sk.type !== '技能') entry.消耗MP = parseMpCost(sk.d) || 0;
                    slot[sk.n] = entry;
                    _.set(actor, slotPath, slot);
                });

                // 3) 扣职业技能点（优先扣等级最高的职业，与学习逻辑一致）
                var remain = totalCost;
                Object.keys(jobInfo).sort(function (a, b) { return (parseInt(jobInfo[b].等级, 10) || 0) - (parseInt(jobInfo[a].等级, 10) || 0); }).forEach(function (j) {
                    if (remain <= 0) return;
                    var sp = parseInt(jobInfo[j].技能点, 10) || 0;
                    if (sp > 0) { var take = Math.min(sp, remain); jobInfo[j].技能点 = sp - take; remain -= take; }
                });
                if (remain > 0) { if (window.toastr) toastr.error('技能点不足！'); return; }
                _.set(actor, '基础状态.职业信息', jobInfo);

                await persistStatChange(mvuData);

                // 4) 注入下一层提示词
                var outNames = _skillFusionResult.map(function (sk) { return sk.n + '(Lv.' + sk.fusedLvl + ')'; });
                var promptMsg = '【技能融合】已将「' + p.target + '」的「' + srcNames.join('、') + '」融合为「' + outNames.join('、') + '」（消耗职业技能点 -' + totalCost + '）。源技能已从技能栏移除，融合技能已完整写入技能栏。请勿重新添加源技能、勿重复扣点。请在下一层输出融合后的技能面板（技能名、类型、等级与效果）。';
                try { await emitAllocPrompt(promptMsg, 'skillfuse_'); } catch (e) { console.error('注入技能融合通知失败:', e); }
                if (window.toastr) toastr.success('✅ 技能融合已保存！\n目标：' + p.target + '\n融合 ' + srcNames.length + ' 个源技能 → ' + outNames.length + ' 个融合技能\n扣除技能点 ' + totalCost);
                _skillFusionPending = null;
                _skillFusionResult = [];
                populateCharacterData();
            } catch (e) {
                console.error('保存技能融合失败:', e);
                if (window.toastr) toastr.error('保存失败：' + (e && e.message ? e.message : e));
            }
        }

        /* ================= ⬆️ 技能升级（功能开关 + 逐项 +级 + API 重写效果） ================= */
        var _skillUpgradeMode = false;
        var _upgradePending = {};

        function skillUpgradeSuffix(slot, key, level) {
            if (!_skillUpgradeMode) return '';
            var lv = parseInt(level, 10) || 0;
            var pend = _upgradePending[slot + '|' + key] || 0;
            if (lv + pend >= 10) return ' <span style="color:#aaa;font-size:11px;">MAX</span>';
            var pendHtml = pend > 0 ? ' <span style="color:#e67e22;font-weight:bold;">+' + pend + '</span>' : '';
            var plus = ' <button class="jrpg-skill-up-plus" data-slot="' + escapeAttr(slot) + '" data-key="' + escapeAttr(key) + '" title="点击 +1 级" style="margin-left:6px;background:#e67e22;color:#fff;border:none;border-radius:3px;padding:0 7px;font-size:13px;font-weight:bold;cursor:pointer;">＋</button>';
            return pendHtml + plus;
        }

        function toggleSkillUpgradeMode() {
            _skillUpgradeMode = !_skillUpgradeMode;
            if (!_skillUpgradeMode) _upgradePending = {};
            renderSkillUpgradeBar();
            populateCharacterData();
        }

        function addSkillUpgrade(slot, key) {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var cur = _.get(all, 'stat_data.主角.资产与能力.' + slot + '.' + key, null);
            if (!cur) return;
            var lv = parseInt(cur.等级, 10) || 0;
            var pend = _upgradePending[slot + '|' + key] || 0;
            if (lv + pend >= 10) { if (window.toastr) toastr.info('该技能已达最高等级 Lv.10'); return; }
            _upgradePending[slot + '|' + key] = pend + 1;
            renderSkillUpgradeBar();
            populateCharacterData();
        }

        function renderSkillUpgradeBar() {
            var $bar = $('#skill-upgrade-bar');
            var $btn = $('#skill-upgrade-toggle');
            if ($btn && $btn.length) {
                if (_skillUpgradeMode) { $btn.text('✔ 技能升级：开').css({ background: '#27ae60', borderColor: '#27ae60' }); }
                else { $btn.text('技能升级：关').css({ background: '#e67e22', borderColor: '#e67e22' }); }
            }
            if (!$bar || !$bar.length) return;
            if (!_skillUpgradeMode) { $bar.hide().html(''); return; }
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var actor = _.get(all, 'stat_data.主角', {});
            var jobInfo = (actor.基础状态 && actor.基础状态.职业信息) || {};
            var totalSp = 0;
            Object.keys(jobInfo).forEach(function(j) { totalSp += parseInt(jobInfo[j].技能点 || 0, 10) || 0; });
            var keys = Object.keys(_upgradePending);
            var totalLevels = 0;
            keys.forEach(function(k) { totalLevels += _upgradePending[k]; });
            var html = '<div style="margin-bottom:6px;font-size:12px;color:#4a3623;line-height:1.6;">已选 <b style="color:#e67e22;">' + keys.length + '</b> 个技能、共 <b style="color:#e67e22;">' + totalLevels + '</b> 级待升级，每级消耗 1 点技能点（可用 <b style="color:#d35400;">' + totalSp + '</b> 点）。</div>';
            if (keys.length) {
                html += '<div style="font-size:11px;color:#7f8c8d;margin-bottom:6px;">待升级：';
                keys.forEach(function(k) {
                    var parts = k.split('|');
                    html += escapeAttr(parts[1]) + '(+' + _upgradePending[k] + ')　';
                });
                html += '</div>';
            }
            var can = keys.length > 0 && totalLevels <= totalSp;
            html += '<div style="font-size:13px;color:#4a3623;">确定升级？&nbsp;&nbsp;<button class="jrpg-btn-sm jrpg-skill-up-yes" ' + (can ? 'style="background:#27ae60;color:#fff;border:2px solid #27ae60;border-radius:4px;padding:3px 16px;font-size:13px;"' : 'disabled style="background:#bbb;color:#fff;border:2px solid #bbb;border-radius:4px;padding:3px 16px;font-size:13px;cursor:not-allowed;"') + '>是</button>&nbsp;&nbsp;<button class="jrpg-btn-sm jrpg-skill-up-no" style="background:#95a5a6;color:#fff;border:2px solid #95a5a6;border-radius:4px;padding:3px 16px;font-size:13px;">否</button></div>';
            $bar.show().html(html);
        }

        async function apiUpgradeSkill(slot, key, curLevel, newLevel, cur) {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var actor = _.get(all, 'stat_data.主角', {});
            var race = _.get(actor, '基础信息.种族', '未知');
            var attr = actor.基础属性 || {};
            var attrDesc = ['力量', '敏捷', '体质', '智力', '感知', '魅力'].map(function(a) { return a + ' ' + (attr[a] || 10); }).join('、');
            var typeName = slot === '魔法栏' ? '魔法' : (slot === '神术栏' ? '神术' : '技能');
            var promptText = '你正在为角色升级技能，只依据下列角色信息与当前技能数据重写，不要参考其他上下文。\n\n';
            promptText += '【角色信息】种族：' + race + '；基础属性：' + attrDesc + '\n';
            promptText += '【当前技能】名称：' + key + '；类型：' + typeName + '；当前等级：Lv.' + curLevel + '；目标等级：Lv.' + newLevel + '\n';
            promptText += '当前效果：' + (cur.描述 || '') + '\n\n';
            promptText += '请将该技能从 Lv.' + curLevel + ' 提升至 Lv.' + newLevel + '（技能最高 Lv.10），重写为 Lv.' + newLevel + ' 的完整新版效果。要求：\n';
            promptText += '1. 效果需比 Lv.' + curLevel + ' 时更强、更完善（数值、范围、冷却、消耗、机制等相应增强）。\n';
            promptText += '2. ' + (typeName === '魔法' || typeName === '神术' ? '必须给出升级后的 MP 消耗（字段 mp，整数数值）。' : '技能类描述需体现体力/SP 消耗，字段 mp 填 0。') + '\n';
            promptText += '3. 描述需与原本风格、定位一致，仅增强，不改变技能名称与类型。\n';
            promptText += '4. 效果描述必须「电报式」精简：只写【效果+数值/骰子+伤害+范围/距离+持续/冷却】，多条用「；」分隔，每条≤20字；禁止完整句式、禁止形容词与风味描写（例：✗"剑刃迸发灼热火焰令敌胆寒" → ✓"伤害+2d6火焰；命中附加灼烧（2轮）"）。\n';
            promptText += '5. 只输出 Lv.' + newLevel + ' 的电报式新版效果描述本身（不要输出逐级提升说明、不要逐级罗列各级变化）。\n';
            promptText += '6. 只输出如下 JSON（不要输出其他文字）：\n```json\n{ "描述": "Lv.' + newLevel + ' 电报式新版效果描述", "mp": 数值 }\n```';
            window.__ISURIA_NON_RP__ = true;
            var result;
            try {
                result = await generateRaw({
                    user_input: promptText,
                    should_silence: true,
                    overrides: {
                        world_info_before: '', world_info_after: '', persona_description: '',
                        char_description: '', char_personality: '', scenario: '',
                        dialogue_examples: '', chat_history: { prompts: [] }
                    }
                });
            } finally { window.__ISURIA_NON_RP__ = false; }
            var obj = extractJsonObject(result);
            if (!obj || typeof obj !== 'object' || Array.isArray(obj)) throw new Error('AI 未返回有效 JSON');
            return { 描述: String(obj.描述 || obj.desc || '').trim(), mp: parseInt(obj.mp, 10) || 0 };
        }

        async function confirmSkillUpgrade() {
            if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
            if (typeof generateRaw !== 'function') { if (window.toastr) toastr.error('当前环境不支持 generateRaw（无法调用 AI 重写技能效果）'); return; }
            var keys = Object.keys(_upgradePending);
            if (!keys.length) { if (window.toastr) toastr.info('未选择任何技能，请先点击技能右侧的 ＋'); return; }
            try {
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = mvuData.stat_data;
                var actor = stat.主角 || (stat.主角 = {});
                var jobInfo = (actor.基础状态 && actor.基础状态.职业信息) || {};
                var totalSp = 0;
                Object.keys(jobInfo).forEach(function(j) { totalSp += parseInt(jobInfo[j].技能点 || 0, 10) || 0; });
                var totalLevels = 0;
                keys.forEach(function(k) { totalLevels += _upgradePending[k]; });
                if (totalLevels > totalSp) { if (window.toastr) toastr.error('技能点不足，需要 ' + totalLevels + ' 点，当前仅 ' + totalSp + ' 点'); return; }
                if (window.toastr) toastr.info('🤖 正在调用 AI 重写升级技能效果…');
                var toDeduct = totalLevels;
                for (var i = 0; i < keys.length; i++) {
                    var k = keys[i];
                    var parts = k.split('|');
                    var slot = parts[0], key = parts[1];
                    var cnt = _upgradePending[k];
                    var slotObj = _.get(actor, '资产与能力.' + slot, {});
                    var cur = slotObj[key] || {};
                    var curLevel = parseInt(cur.等级, 10) || 0;
                    var newLevel = Math.min(curLevel + cnt, 10);
                    var res = await apiUpgradeSkill(slot, key, curLevel, newLevel, cur);
                    slotObj[key] = slotObj[key] || {};
                    slotObj[key].等级 = newLevel;
                    if (res.描述) slotObj[key].描述 = res.描述;
                    if (slot === '魔法栏' || slot === '神术栏') slotObj[key].消耗MP = res.mp;
                    _.set(actor, '资产与能力.' + slot, slotObj);
                }
                var toD = toDeduct;
                Object.keys(jobInfo).sort(function(a, b) { return (parseInt(jobInfo[b].等级, 10) || 0) - (parseInt(jobInfo[a].等级, 10) || 0); }).forEach(function(j) {
                    if (toD <= 0) return;
                    var sp = parseInt(jobInfo[j].技能点 || 0, 10) || 0;
                    if (sp > 0) { var take = Math.min(sp, toD); jobInfo[j].技能点 = sp - take; toD -= take; }
                });
                if (!actor.基础状态) actor.基础状态 = {};
