                // 无职业：直接新建职业（Lv.1）
                jobInfo[newJob] = { 等级: 1, 技能点: sp, grantedLv: -1, grantedSp: -1 };
                msg = '✅ 已为角色新建职业「' + newJob + '」（Lv.1，技能点 ' + sp + '）。';
