                writeAgeGrowthIssued(r.expected);
                await persistStatChange(mvuData);
                alert('🎂 年龄成长：' + r.age + '岁 应得 ' + r.expected + '/20 点，已补 ' + r.missing + ' 点到未分配属性点（累计发放 ' + r.expected + ' 点）。升级所得属性点不会干扰年龄成长。');
            } else {
                alert('年龄成长已到位：' + r.age + '岁，应得 ' + r.expected + '/20，已发放 ' + r.issued + ' 点，无需补点。');
            }
        }
        // 被动（每层静默）：只要年龄在成长区间且未发满，就自动补
        async function passiveAgeGrowthCheck() {
            if (typeof Mvu === 'undefined') return;
            if (!ageGrowthEnabled()) return; // 首页开关关闭 → 完全不发放
            try {
                var mvuData = currentMvuData();
                var stat = mvuData.stat_data;
                var actor = allocActor(stat, '主角');
                if (!actor) return;
                var age = parseInt(_.get(actor, '基础信息.年龄', 0), 10) || 0;
                // 已成年（>18岁）不再补发：18 岁那天领满 20，之后完全停止，避免成年后仍被补全
                if (age > 18) return;
                var r = calcAgeGrowth(stat, actor);
                if (r.skip) return;
                if (r.firstTime) {
                    // 首次：仅初始化发放记录，不发多余点
                    stat.$flags = stat.$flags || {};
                    stat.$flags.年龄成长 = r.expected;
                    writeAgeGrowthIssued(r.expected);
                    await persistStatChange(mvuData);
                    return;
                }
                if (r.missing <= 0) return;
                actor.基础属性.未分配点数 = (parseInt(_.get(actor, '基础属性.未分配点数', 0), 10) || 0) + r.missing;
                stat.$flags = stat.$flags || {};
                stat.$flags.年龄成长 = r.expected;
                writeAgeGrowthIssued(r.expected);
                await persistStatChange(mvuData);
                if (typeof toastr !== 'undefined' && toastr.info) toastr.info('🎂 年龄成长：' + r.age + '岁 自动获得 ' + r.missing + ' 点未分配属性点（累计发放 ' + r.expected + '/20）。');
            } catch (e) { console.warn('[年龄成长] 被动检测失败:', e); }
        }

        function allocStat() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            return all.stat_data || {};
        }
        function allocActor(stat, target) {
            if (!stat) return null;
            if (target === '主角') return stat.主角 || null;
            return _.get(stat, ['同伴', target], null);
        }
        // 技能写入槽位路径（相对 actor）：主角 → 资产与能力.{角色技能|魔法栏|神术栏}；同伴 → 技能
        function allocSlotPath(target, type) {
            if (target === '主角') return type === '魔法' ? '资产与能力.魔法栏' : (type === '神术' ? '资产与能力.神术栏' : '资产与能力.角色技能');
            return '技能';
        }
        // 已学技能集合
        function allocLearned(actor, target) {
            var map = {};
            if (!actor) return map;
            if (target === '主角') {
                ['角色技能', '魔法栏', '神术栏'].forEach(function(sk) {
                    Object.keys(_.get(actor, '资产与能力.' + sk, {})).forEach(function(k) { map[k] = true; });
                });
            } else {
                Object.keys(_.get(actor, '技能', {})).forEach(function(k) { map[k] = true; });
            }
            return map;
        }

        /* ===== 状态栏升级分配：有未分配属性/职业点时在对应行显示 +，点确认一次写回（复用 confirmAlloc） ===== */
        var QA_ATTRS = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
        function qaGetStat() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            return (all && all.stat_data) || {};
        }
        function qaGetPools() {
            var st = qaGetStat();
            var hero = st.主角 || {};
            var attr = hero.基础属性 || {};
            var bs = hero.基础状态 || {};
            return { unalloc: parseInt(attr.未分配点数, 10) || 0, attr: attr, pendJob: parseInt(bs.待分配职业等级, 10) || 0, jobInfo: bs.职业信息 || {} };
        }
        // 草稿已占用的未分配点数/待分配职业等级
        function qaGetUsed() {
            var used = { au: 0, ju: 0 };
            if (!allocDraft || !allocDraft['主角']) return used;
            var d = allocDraft['主角'];
            Object.keys(d.attr || {}).forEach(function(a) { var v = d.attr[a] || 0; if (v > 0) used.au += v; });
            Object.keys(d.jobs || {}).forEach(function(j) { used.ju += d.jobs[j] || 0; });
            return used;
        }
        function qaMount() {
            var $lr = $('#level-info-row');
            if (!$lr || !$lr.length) return;
            var $box = $lr.closest('.jrpg-box');
            if (!$box || !$box.length) return;
            // 确认条容器（常驻，populate 不会重建它）
            var $bar = $('#quick-add-bar');
            if (!$bar || !$bar.length) { $box.append('<div id="quick-add-bar"></div>'); $bar = $('#quick-add-bar'); }
            var p = qaGetPools();
            var used = qaGetUsed();
            var d = allocDraftFor('主角');
            var totalPend = used.au + used.ju;
            // （计数项外层虚线框保留；仅数字内框去掉，已由 CSS 处理）
            // 六维属性行：有额度显示 +；有待确认显示 +N 与 −
            $box.find('.jrpg-stat-item').each(function() {
                var $it = $(this);
                $it.find('.qa-plus, .qa-minus, .qa-pend').remove();
                var label = ($it.children('span').first().text() || '').replace(/^\s+|\s+$/g, '');
                var idx = QA_ATTRS.indexOf(label);
                if (idx < 0) return;
                var aname = QA_ATTRS[idx];
                var pend = d.attr[aname] || 0;
                var canAdd = (p.unalloc - used.au) > 0 && (parseInt(p.attr[aname], 10) || 10) < 30;
                if (canAdd || pend > 0) {
                    var $val = $it.children('span').eq(1);
                    if ($val && $val.length) {
                        if (pend > 0) $val.append('<span class="qa-pend">+' + pend + '</span>');
                        if (pend > 0) $val.append('<button type="button" class="qa-minus" data-qa-type="attr" data-qa-name="' + aname + '" title="减少 1 点「' + aname + '」的预分配">−</button>');
                        if (canAdd) $val.append('<button type="button" class="qa-plus' + (pend > 0 ? ' on' : '') + '" data-qa-type="attr" data-qa-name="' + aname + '" title="+' + (pend + 1) + ' 未分配属性点 → ' + aname + '">+</button>');
                    }
                }
            });
            // 职业信息行：有待分配职业等级（或已有待确认）才显示 + 与 −（加在职业名旁）
            var $jobs = $('#list-classes');
            if ($jobs && $jobs.length) {
                $jobs.find('.jrpg-list-item').each(function() {
                    var $li = $(this);
                    $li.find('.qa-plus, .qa-minus, .qa-pend').remove();
                    var $hd = $li.find('.jrpg-item-header').first();
                    if (!$hd || !$hd.length) return;
                    var $nm = $hd.children('span').first();
                    if (!$nm || !$nm.length) return;
                    var name = ($nm.text() || '').replace(/^⚔️\s*/, '').replace(/^\s+|\s+$/g, '');
                    if (!name) return;
                    var pend = d.jobs[name] || 0;
                    var canAdd = (p.pendJob - used.ju) > 0;
                    if (canAdd || pend > 0) {
                        if (pend > 0) $nm.append('<span class="qa-pend">+' + pend + '</span>');
                        if (pend > 0) $nm.append('<button type="button" class="qa-minus" data-qa-type="job" data-qa-name="' + escapeAttr(name) + '" title="减少 1 点「' + escapeAttr(name) + '」的预分配">−</button>');
                        if (canAdd) $nm.append('<button type="button" class="qa-plus' + (pend > 0 ? ' on' : '') + '" data-qa-type="job" data-qa-name="' + escapeAttr(name) + '" title="+' + (pend + 1) + ' 待分配职业等级 → ' + escapeAttr(name) + '">+</button>');
                    }
                });
            }
            // 操作条：仅在有待确认时出现（刷新 / 重置 / 确认分配）
            if (totalPend === 0) { $bar.html(''); return; }
            var h = '<button type="button" class="qa-btn-sm qa-refresh" title="重新读取当前未分配点数（保留已点待确认）">🔄 刷新</button>' +
                '<button type="button" class="qa-btn-sm qa-reset" title="清空本次已点的待确认分配">↺ 重置</button>' +
                '<button type="button" class="qa-confirm" title="把已点的属性点/职业等级一次性写入并扣除对应未分配点数">✅ 确认分配（' + totalPend + '）</button>';
            $bar.html(h);
        }

        function renderAllocCenter() {
            var $inner = $('#alloc-inner');
            if (!$inner || !$inner.length) return;
            var stat = allocStat();
            var targets = ['主角'].concat(Object.keys(_.get(stat, '同伴', {})));
            var html = '';
            // 提示词注入方式
            var injectMode = _.get(stat, '$flags.allocInjectMode', 'inject');
            html += '<div class="alloc-mode-row">提示词注入：' +
                '<button class="alloc-mode-btn' + (injectMode === 'inject' ? ' active' : '') + '" data-alloc-mode="inject">注入上下文</button>' +
                '<button class="alloc-mode-btn' + (injectMode === 'message' ? ' active' : '') + '" data-alloc-mode="message">发送楼层</button>' +
                '</div>';
            // 角色选择
            html += '<div class="alloc-targets">';
            targets.forEach(function(t) {
                var active = t === allocTarget ? ' active' : '';
                html += '<button class="alloc-target-btn' + active + '" data-alloc-target="' + escapeAttr(t) + '">' + (t === '主角' ? '🦸 主角' : '🤝 ' + escapeAttr(t)) + '</button>';
            });
            html += '</div>';
            html += '<div style="display:flex;gap:8px;margin:8px 0;flex-wrap:wrap;">';
            html += '<button class="jrpg-change-job" data-target="' + escapeAttr(allocTarget) + '" style="padding:4px 12px;border:2px solid #b8882a;background:linear-gradient(180deg,#f6c945,#e0a61f);color:#3d1d00;border-radius:999px;font-size:12px;font-weight:900;cursor:pointer;font-family:inherit;">🔄 转职</button>';
            html += '<button class="jrpg-age-grow" data-target="' + escapeAttr(allocTarget) + '" style="padding:4px 12px;border:2px solid #8a5a8a;background:linear-gradient(180deg,#e8c6e8,#c49ac4);color:#4a2a4a;border-radius:999px;font-size:12px;font-weight:900;cursor:pointer;font-family:inherit;">🎂 年龄成长</button>';
            html += '</div>';
            var actor = allocActor(stat, allocTarget);
            if (!actor) {
                html += '<div class="alloc-empty">未找到该角色数据</div>';
            } else {
                html += renderAllocBody(stat, actor);
            }
            $inner.html(html);
        }

        function renderAllocBody(stat, actor) {
            var target = allocTarget;
            var draft = allocDraftFor(target);
            var attr = actor.基础属性 || {};
            var jobInfo = (actor.基础状态 && actor.基础状态.职业信息) || {};
            var origUnalloc = parseInt(attr.未分配点数, 10) || 0;
            var origPending = parseInt(_.get(actor, '基础状态.待分配职业等级', 0), 10) || 0;
            var totalSp = 0;
            Object.keys(jobInfo).forEach(function(j) { totalSp += parseInt(jobInfo[j].技能点, 10) || 0; });

            // 草稿统计
            var attrUsed = 0, attrRefund = 0;
            Object.keys(draft.attr).forEach(function(a) { var d = draft.attr[a] || 0; if (d > 0) attrUsed += d; else attrRefund += -d; });
            var remainAttr = origUnalloc - attrUsed + attrRefund;
            var jobUsed = 0;
            Object.keys(draft.jobs).forEach(function(j) { jobUsed += (draft.jobs[j] || 0); });
            var remainPending = origPending - jobUsed;
            var spUsed = 0;
            draft.skills.forEach(function(s) { spUsed += s.cost || 0; });
            var remainSp = totalSp - spUsed;

            var html = '';
            // 资源总览
            html += '<div class="alloc-res">';
            html += '<div class="alloc-res-item">未分配属性点: <b>' + remainAttr + '</b>' + (attrUsed ? ' <span class="alloc-diff">(-' + attrUsed + ')</span>' : '') + (attrRefund ? ' <span class="alloc-diff">(退回+' + attrRefund + ')</span>' : '') + '</div>';
            html += '<div class="alloc-res-item">待分配职业等级: <b>' + remainPending + '</b>' + (jobUsed ? ' <span class="alloc-diff">(-' + jobUsed + ')</span>' : '') + '</div>';
            html += '<div class="alloc-res-item">职业技能点: <b>' + remainSp + '</b>' + (spUsed ? ' <span class="alloc-diff">(-' + spUsed + ')</span>' : '') + '</div>';
            html += '</div>';

            // 属性分配
            html += '<div class="alloc-sec-title">⚔️ 属性加点（未分配点数 → 六维，可点 − 退回）</div>';
            var attrNames = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
            html += '<div class="jrpg-grid-2col" style="grid-template-columns:1fr 1fr;">';
            attrNames.forEach(function(a) {
                var orig = parseInt(attr[a], 10) || 10;
                var d = draft.attr[a] || 0;
                var val = orig + d;
                var canPlus = remainAttr >= 1 && val < 30;
                var canMinus = val > 0;
                html += '<div class="alloc-row"><span class="alloc-name">' + a + '</span>' +
                    '<span class="alloc-stepper">' +
                    '<button class="alloc-step-btn minus" data-alloc-attr="' + escapeAttr(a) + '" data-delta="-1"' + (canMinus ? '' : ' disabled') + '>−</button>' +
                    '<span class="alloc-step-val">' + val + (d ? ' <span class="alloc-diff' + (d < 0 ? ' neg' : '') + '">(' + (d > 0 ? '+' : '') + d + ')</span>' : '') + '</span>' +
                    '<button class="alloc-step-btn plus" data-alloc-attr="' + escapeAttr(a) + '" data-delta="1"' + (canPlus ? '' : ' disabled') + '>+</button>' +
                    '</span></div>';
            });
            html += '</div>';

            // 职业等级
            html += '<div class="alloc-sec-title">📈 职业等级提升（待分配职业等级 → 职业，HP/MP/SP/技能点由升级脚本自动补齐）</div>';
            var jobs = Object.keys(jobInfo);
            if (!jobs.length) {
                html += '<div class="alloc-empty">暂无职业</div>';
            } else {
                jobs.forEach(function(j) {
                    var orig = parseInt(jobInfo[j].等级, 10) || 1;
                    var d = draft.jobs[j] || 0;
                    var val = orig + d;
                    var canPlus = remainPending - (d > 0 ? d : 0) >= 1;
                    var canMinus = val > 1;
                    html += '<div class="alloc-row"><span class="alloc-name">⚔️ ' + escapeAttr(j) + '</span>' +
                        '<span class="alloc-stepper">' +
                        '<button class="alloc-step-btn minus" data-alloc-job="' + escapeAttr(j) + '" data-delta="-1"' + (canMinus ? '' : ' disabled') + '>−</button>' +
                        '<span class="alloc-step-val">Lv.' + val + (d ? ' <span class="alloc-diff">(+' + d + ')</span>' : '') + '</span>' +
                        '<button class="alloc-step-btn plus" data-alloc-job="' + escapeAttr(j) + '" data-delta="1"' + (canPlus ? '' : ' disabled') + '>+</button>' +
                        '</span></div>';
                });
            }

            // 技能学习（等级段模板分组，可折叠；默认展开当前可学技能所在段，折叠状态跨重渲染记忆）
            html += '<div class="alloc-sec-title">🎓 技能学习（职业技能树 + 变体技能，消耗技能点；按等级段折叠）</div>';
            var learned = allocLearned(actor, target);
            var added = {};
            draft.skills.forEach(function(s) { added[s.job + '|' + s.name] = true; });
            var customTrees = _.get(stat, '$customSkillTrees', {});
            var skillRows = [];
            var collectSkillRow = function(sk, jobName, label) {
                var name = sk.n || sk.name || '';
                if (!name) return;
                var key = jobName + '|' + name;
                if (learned[name] || added[key]) return;
                skillRows.push({ sk: sk, jobName: jobName, label: label });
            };
            jobs.forEach(function(j) {
                var jf = jobElemFilter(j);
                var db = (typeof dbSkills !== 'undefined' && dbSkills[jf.base]) || [];
                db.forEach(function(sk) { if (jobSkillAllowed(j, sk)) collectSkillRow(sk, j, ''); });
                var vMap = customTrees[j] || {};
                Object.keys(vMap).forEach(function(vn) {
                    (vMap[vn].skills || []).forEach(function(sk) { if (jobSkillAllowed(j, sk)) collectSkillRow(sk, j, '变体·' + vn); });
                });
            });
            if (!skillRows.length) {
                html += '<div class="alloc-empty">当前角色没有可学习的技能（可能已全部掌握，或职业等级/技能点不足）</div>';
            } else {
                var ABANDS = [
                    { min: 1, max: 4, name: '普通阶' },
                    { min: 5, max: 8, name: '超凡阶' },
                    { min: 9, max: 12, name: '精英阶' },
                    { min: 13, max: 16, name: '史诗阶' },
                    { min: 17, max: 20, name: '传说阶' },
                    { min: 21, max: 999, name: '神话阶' }
                ];
                var allocBandBase = String(target).replace(/[^a-zA-Z0-9\u4e00-\u9fa5]/g, '_');
                var allocSkillCount = 0;
                var renderAllocSkillRow = function(sk, jobName, label) {
                    var name = sk.n || sk.name || '';
                    var type = sk.type || (typeof skillTypeOf === 'function' ? skillTypeOf(sk, jobName) : '技能');
                    var cost = parseInt(sk.c, 10) || 1;
                    var lvl = parseInt(sk.lvl, 10) || 1;
                    var jobLv = parseInt((jobInfo[jobName] && jobInfo[jobName].等级) || 1, 10) || 1;
                    var isLocked = jobLv < lvl;
                    var spNotEnough = (totalSp - spUsed) < cost;
                    allocSkillCount++;
                    html += '<div class="alloc-skill-item"><div><span class="sk-name">' + escapeAttr(name) + '</span><span class="alloc-skill-badge">' + type + '</span>' +
                        '<div class="sk-meta">' + escapeAttr(jobName) + ' · 需' + lvl + '级 · 消耗' + cost + '点' + (label ? ' · ' + escapeAttr(label) : '') + '</div></div>';
                    if (isLocked) html += '<span style="font-size:10px;color:#e74c3c;flex-shrink:0;">🔒 需' + lvl + '级</span>';
                    else if (spNotEnough) html += '<span style="font-size:10px;color:#bbb;flex-shrink:0;">技能点不足</span>';
                    else html += '<button class="alloc-add-skill" data-alloc-skill-job="' + escapeAttr(jobName) + '" data-alloc-skill-name="' + escapeAttr(name) + '" data-alloc-skill-type="' + type + '" data-alloc-skill-cost="' + cost + '" data-alloc-skill-desc="' + escapeAttr(sk.d || '') + '" data-alloc-skill-mp="' + (parseInt(sk.mp, 10) || parseMpCost(sk.d) || 0) + '">+ 学习</button>';
                    html += '</div>';
                };
                ABANDS.forEach(function(band) {
                    var rows = skillRows.filter(function(r) { var lv = parseInt(r.sk.lvl, 10) || 1; return lv >= band.min && lv <= band.max; });
                    if (!rows.length) return;
                    var unlockedCount = rows.filter(function(r) {
                        var lv = parseInt(r.sk.lvl, 10) || 1;
                        var jlv = parseInt((jobInfo[r.jobName] && jobInfo[r.jobName].等级) || 1, 10) || 1;
                        return jlv >= lv;
                    }).length;
                    var bandId = 'alloc-skill-band-' + allocBandBase + '-' + band.min;
                    var open = (window.__isuriaFoldState && window.__isuriaFoldState['#' + bandId] !== undefined) ? window.__isuriaFoldState['#' + bandId] : (unlockedCount > 0);
                    html += '<div style="font-weight:bold;color:#5a4430;margin:8px 0 0;font-size:12px;background:rgba(139,107,74,0.1);border-radius:4px;padding:4px 8px;cursor:pointer;user-select:none;" data-fold-target="#' + bandId + '" title="点击折叠/展开">';
                    html += '📚 ' + band.name + ' <span style="font-size:10px;color:#8b6b4a;font-weight:normal;">Lv.' + band.min + (band.max <= 20 ? '-' + band.max : '+') + ' · ' + rows.length + ' 技能' + (unlockedCount ? ' · 可学 ' + unlockedCount : '') + '</span>';
                    html += '<span class="jrpg-fold-arrow" style="float:right;color:#8b6b4a;">' + (open ? '▾' : '▸') + '</span></div>';
                    html += '<div id="' + bandId + '" style="display:' + (open ? '' : 'none') + ';">';
                    rows.forEach(function(r) { renderAllocSkillRow(r.sk, r.jobName, r.label); });
                    html += '</div>';
                });
            }

            // 草稿清单
            var hasAttr = Object.keys(draft.attr).some(function(k) { return draft.attr[k]; });
            var hasJob = Object.keys(draft.jobs).some(function(k) { return draft.jobs[k]; });
            if (hasAttr || hasJob || draft.skills.length) {
                html += '<div class="alloc-draft">';
                html += '<div style="font-weight:bold;color:#8e44ad;margin-bottom:4px;">📋 待确认分配清单</div>';
                Object.keys(draft.attr).forEach(function(a) {
                    var d = draft.attr[a] || 0;
                    if (!d) return;
                    html += '<div class="alloc-draft-item"><span>属性 · ' + a + ' ' + (d > 0 ? '+' : '') + d + '</span><button class="alloc-rm" data-alloc-rm-attr="' + escapeAttr(a) + '">✕</button></div>';
                });
                Object.keys(draft.jobs).forEach(function(j) {
                    var d = draft.jobs[j] || 0;
                    if (!d) return;
                    html += '<div class="alloc-draft-item"><span>职业 · ' + escapeAttr(j) + ' Lv+' + d + '</span><button class="alloc-rm" data-alloc-rm-job="' + escapeAttr(j) + '">✕</button></div>';
                });
                draft.skills.forEach(function(s, i) {
                    html += '<div class="alloc-draft-item"><span>技能 · ' + escapeAttr(s.name) + '（' + escapeAttr(s.job) + '，-' + s.cost + '点）</span><button class="alloc-rm" data-alloc-rm-skill="' + i + '">✕</button></div>';
                });
                html += '</div>';
            }

            // 操作按钮
            var hasDraft = hasAttr || hasJob || draft.skills.length;
            var valid = remainAttr >= 0 && remainPending >= 0 && remainSp >= 0;
            var totalDrafts = 0;
            Object.keys(allocDraft).forEach(function(t) {
                var d = allocDraft[t];
                if (Object.keys(d.attr).some(function(k) { return d.attr[k]; }) || Object.keys(d.jobs).some(function(k) { return d.jobs[k]; }) || d.skills.length) totalDrafts++;
            });
            html += '<div style="font-size:11px;color:#8e44ad;margin:10px 0 4px;">👥 当前已选 <b>' + totalDrafts + '</b> 个角色待确认分配（可切换角色继续加点，最后一次性确认）</div>';
            html += '<div class="alloc-actions">';
            html += '<button class="alloc-btn confirm" id="alloc-confirm-btn"' + (hasDraft && valid ? '' : ' disabled style="opacity:.5;cursor:not-allowed;"') + '>✅ 确认分配</button>';
            html += '<button class="alloc-btn notice" id="alloc-ai-btn">🤖 AI 自动分配</button>';
            html += '<button class="alloc-btn reset" id="alloc-reset-btn">↺ 重置</button>';
            html += '</div>';
            html += '<div class="alloc-hint">提示：<b>确认分配</b> 会把草稿中的属性点/职业等级/技能写入变量，并在下一楼注入「分配确认」提示词，告知 AI 已完成分配。<b>AI 自动分配</b> 会向 AI 注入一条指令，要求它按变量更新规则为所有有可分配点数的角色（主角+同伴）自动分配属性点/职业等级/技能并输出变量更新（JSONPatch），适合点数较多时让 AI 代劳。升级产生的 HP/MP/SP/技能点由升级脚本自动补齐。</div>';

            return html;
        }

        // 确认分配：遍历所有角色草稿，一次性写入变量 + 注入「分配确认」通知
        async function confirmAlloc() {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                if (!allocDraft) { if (window.toastr) toastr.warning('没有待确认的分配'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = mvuData.stat_data || (mvuData.stat_data = {});
                var targets = Object.keys(allocDraft);
                var summary = [];
                var anyApplied = false;
                var allocGrowth = {}; // { target: { jobs, attr } } 供升级脚本补齐三维

                for (var ti = 0; ti < targets.length; ti++) {
                    var target = targets[ti];
                    var draft = allocDraft[target];
                    var hasAttr = Object.keys(draft.attr).some(function(k) { return draft.attr[k]; });
                    var hasJob = Object.keys(draft.jobs).some(function(k) { return draft.jobs[k]; });
                    if (!hasAttr && !hasJob && !draft.skills.length) continue;

                    var actor = allocActor(stat, target);
                    if (!actor) { if (window.toastr) toastr.error('未找到角色「' + target + '」数据'); return; }
                    var attr = actor.基础属性 || (actor.基础属性 = {});
                    var base = actor.基础状态 || (actor.基础状态 = {});
                    var jobInfo = base.职业信息 || (base.职业信息 = {});
                    var notes = [];

                    // 属性
                    var attrCost = 0, attrRefund = 0;
                    Object.keys(draft.attr).forEach(function(a) { var d = draft.attr[a] || 0; if (d > 0) attrCost += d; else attrRefund += -d; });
                    var remainAttr = (parseInt(attr.未分配点数, 10) || 0) - attrCost + attrRefund;
                    if (remainAttr < 0) { if (window.toastr) toastr.error(target + ' 未分配属性点不足'); return; }
                    var attrDelta = {};
                    Object.keys(draft.attr).forEach(function(a) {
                        var d = draft.attr[a] || 0;
                        if (!d) return;
                        attr[a] = Math.max(0, Math.min(30, (parseInt(attr[a], 10) || 10) + d));
                        attrDelta[a] = d;
                    });
                    attr.未分配点数 = remainAttr;
                    if (attrCost) notes.push('属性点 消耗' + attrCost + ' → ' + Object.keys(attrDelta).map(function(a) { return a + (attrDelta[a] > 0 ? '+' : '') + attrDelta[a]; }).join('、'));

                    // 职业等级
                    var jobCost = 0, jobDelta = {};
                    Object.keys(draft.jobs).forEach(function(j) { var d = draft.jobs[j] || 0; if (d) { jobCost += d; jobDelta[j] = d; } });
                    var remainPending = (parseInt(base.待分配职业等级, 10) || 0) - jobCost;
                    if (remainPending < 0) { if (window.toastr) toastr.error(target + ' 待分配职业等级不足'); return; }
                    Object.keys(draft.jobs).forEach(function(j) {
                        var d = draft.jobs[j] || 0;
                        if (!d) return;
                        if (!jobInfo[j]) jobInfo[j] = { 等级: 0, 技能点: 0 };
                        jobInfo[j].等级 = Math.max(1, (parseInt(jobInfo[j].等级, 10) || 1) + d);
                    });
                    base.待分配职业等级 = remainPending;
                    if (jobCost) notes.push('职业 ' + Object.keys(jobDelta).map(function(j) { return j + ' Lv+' + jobDelta[j]; }).join('、') + '（消耗待分配职业等级 ' + jobCost + '，HP/MP/SP/技能点由升级脚本补齐）');
                    // 记录本次分配的职业/属性增量，供升级脚本在写入后补齐 三维/技能点
                    if (Object.keys(jobDelta).length || Object.keys(attrDelta).length) {
                        allocGrowth[target] = { jobs: jobDelta, attr: attrDelta };
                    }

                    // 技能
                    var spNotes = [];
                    for (var si = 0; si < draft.skills.length; si++) {
                        var s = draft.skills[si];
                        var cost = s.cost || 1;
                        var jobName = s.job;
                        var realJob = jobInfo[jobName] ? jobName : null;
                        if (!realJob) Object.keys(jobInfo).forEach(function(k) { if (!realJob && (k.indexOf(jobName) !== -1 || jobName.indexOf(k) !== -1)) realJob = k; });
                        var remain = cost;
                        if (realJob) { var sp = parseInt(jobInfo[realJob].技能点, 10) || 0; if (sp > 0) { var take = Math.min(sp, remain); jobInfo[realJob].技能点 = sp - take; remain -= take; } }
                        Object.keys(jobInfo).forEach(function(k) {
                            if (remain <= 0) return;
                            var sp2 = parseInt(jobInfo[k].技能点, 10) || 0;
                            if (sp2 > 0) { var take2 = Math.min(sp2, remain); jobInfo[k].技能点 = sp2 - take2; remain -= take2; }
                        });
                        if (remain > 0) { if (window.toastr) toastr.error(target + ' 技能点不足：' + s.name); return; }
                        var slotPath = allocSlotPath(target, s.type);
                        var slot = _.get(actor, slotPath, null);
                        if (!slot || typeof slot !== 'object') { slot = {}; _.set(actor, slotPath, slot); }
                        var entry = { 描述: s.desc || '', 等级: 1 };
                        if (s.type !== '技能') entry.消耗MP = parseInt(s.mp, 10) || 0;
                        slot[s.name] = entry;
                        spNotes.push(s.name + '(-' + cost + '点)');
                    }
                    if (spNotes.length) notes.push('学习技能 ' + spNotes.join('、'));

                    var targetLabel = target === '主角' ? '主角' : '同伴「' + target + '」';
                    summary.push(targetLabel + '：' + notes.join('；'));
                    anyApplied = true;
                }

                if (!anyApplied) { if (window.toastr) toastr.warning('没有待确认的分配'); return; }

                // 写入
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });

                // 补齐 三维/技能点 成长：replaceMvuData 不触发升级脚本的 VARIABLE_UPDATE_ENDED，需显式调用
                var upgradeApi = (typeof window !== 'undefined' && window.升级脚本) || (window.parent && window.parent.升级脚本);
                if (upgradeApi && typeof upgradeApi.应用分配 === 'function') {
                    var growthTargets = Object.keys(allocGrowth);
                    for (var gi = 0; gi < growthTargets.length; gi++) {
                        var gt = growthTargets[gi];
                        try { await upgradeApi.应用分配({ target: gt, jobs: allocGrowth[gt].jobs, attr: allocGrowth[gt].attr }); } catch (ge) { console.error('升级脚本补齐三维失败:', ge); if (window.toastr) toastr.error('升级脚本补齐三维失败：' + (ge && ge.message ? ge.message : ge)); }
                    }
                } else {
                    console.warn('升级脚本未找到，三维/技能点成长未补齐（请确认已加载「升级代码」脚本）');
                    if (window.toastr) toastr.error('⚠️ 未找到「升级代码」脚本，三维/技能点未补齐！请先在酒馆扩展脚本中加载「升级代码」并刷新页面');
                }

                // 注入「分配确认」通知
                var notif = '【分配确认】玩家已在状态栏「升级分配」完成以下角色的点数分配并确认：\n' + summary.join('\n') + '\n以上分配已由玩家确认，对应的「未分配点数/待分配职业等级/技能点」已同步扣除。请 AI 遵循变量更新规则：这些点数只能减少、严禁增加，无需（也不得）再代为分配或修改。\n本次「学习技能」涉及的新增/升级技能，其效果词条必须电报式精简：每条≤20字，只写【效果+数值/骰子+范围/距离+持续/冷却】，禁止完整句式与形容词堆砌（风味叙述写在正文，不写入变量）。';
                var sentMode = await emitAllocPrompt(notif);
                if (window.toastr) toastr.success(sentMode === 'inject' ? '✅ 已确认分配，提示词已注入上下文（下次生成生效）！' : '✅ 已确认分配，已发送楼层！');
                allocDraft = null;
                populateCharacterData();
            } catch (e) {
                console.error('确认分配失败:', e);
                if (window.toastr) toastr.error('确认分配失败：' + (e && e.message ? e.message : e));
            }
        }

        // AI 自动分配：列出所有有可分配点数的角色 + 分配规则，注入下一楼让 AI 按变量更新规则自动分配
        async function injectAiAlloc() {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var stat = allocStat();
                var lines = [];
