                    }
                }
                var comps = stat.同伴 || {};
                Object.keys(comps).forEach(function(name) {
                    var c = comps[name];
                    var ca = (c.基础属性 || {}).未分配点数 || 0;
                    var cp = (c.基础状态 || {}).待分配职业等级 || 0;
                    var csp = 0;
                    var cj = (c.基础状态 || {}).职业信息 || {};
                    Object.keys(cj).forEach(function(k) { csp += parseInt(cj[k].技能点, 10) || 0; });
                    if (ca > 0 || cp > 0 || csp > 0) {
                        any = true;
                        lines.push('同伴「' + name + '」：未分配属性点 ' + ca + '，待分配职业等级 ' + cp + '，职业技能点 ' + csp + '（职业：' + (Object.keys(cj).join('、') || '无') + '）');
