        }

        /* ================= 变量编辑器(JSON Tree)核心逻辑 ================= */
        /* ================= 装备栏（一键装备/卸下） ================= */
        function renderEquipment() {
            var $container = $('#list-equipment');
            if (!$container || !$container.length) return;
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var equip = _.get(all, 'stat_data.主角.资产与能力.装备栏', {});
            var slotNames = ['头部', '颈部', '躯干', '腿部', '双手'];
            // 无图标，纯文字槽位
            var html = '';
            slotNames.forEach(function(slot) {
                var item = equip[slot] || {};
                var hasItem = item && Object.keys(item).length > 0 && !!item.物品名;
                html += '<div class="jrpg-equip-slot">';
                html += '<span class="slot-name">' + slot + '</span>';
                if (hasItem) {
                    var rank = item.品阶 || '普通';
                    html += '<span class="slot-item"><span class="rank-' + rank + '">[' + rank + ']</span> ' + escapeAttr(item.物品名 || '未知装备');
                    html += renderEquipEffects(item);
                    html += '</span>';
                    html += '<button class="jrpg-unequip-btn" data-slot="' + slot + '">卸下</button>';
                } else {
                    html += '<span class="slot-item" style="color:#bbb;font-style:italic;">— 空 —</span>';
                }
                html += '</div>';
            });
            $container.html(html);
        }

                // ===== 装备属性 → 变量加成（面板效果/附加词条 的纯数值项，键名映射角色变量路径） =====
        // 例：防具面板效果 {防御值: '2'} → 角色.防御值 +2；{敏捷: '1'} → 角色.基础属性.敏捷 +1；
        //     {HP上限: '10'} → 角色.基础状态.HP.最大 +10；卸下后自动还原
        // 值须为纯数字（'2'、'+3'、'1.5'），其他格式（'防御+2'、'2d4'）不解析不生效
        var EQUIP_BONUS_PATH = {
            '防御值': '防御值',
            'HP上限': '基础状态.HP.最大',
            'MP上限': '基础状态.MP.最大',
            'SP上限': '基础状态.SP.最大',
            '力量': '基础属性.力量',
            '敏捷': '基础属性.敏捷',
            '体质': '基础属性.体质',
            '智力': '基础属性.智力',
            '感知': '基础属性.感知',
            '魅力': '基础属性.魅力'
        };
        function parseEffectNum(v) {
            if (v === undefined || v === null || v === '') return 0;
            var s = String(v).replace(/\s+/g, '');
            var m = s.match(/^[+-]?\d+(\.\d+)?$/);
            return m ? parseFloat(m[0]) : 0;
        }
        function calcEquipBonus(item) {
            var bonus = {};
            if (!item || typeof item !== 'object') return bonus;
            var sources = [item.面板效果, item.附加词条];
            sources.forEach(function (src) {
                if (!src || typeof src !== 'object') return;
                Object.keys(src).forEach(function (k) {
                    var num = parseEffectNum(src[k]);
                    if (num !== 0 && bonus[k] === undefined) bonus[k] = num;
                });
            });
            return bonus;
        }
        function applyEquipBonusTo(target, bonus, sign) {
            if (!target || !bonus) return;
            Object.keys(bonus).forEach(function (k) {
                var path = EQUIP_BONUS_PATH[k];
                if (!path) {
                    // 兼容：角色顶层同名字段（如 攻击力，角色卡顶层有此数字字段才生效）
                    if (typeof target[k] === 'number') {
                        target[k] = Math.max(0, (target[k] || 0) + sign * bonus[k]);
                    }
                    return;
                }
                var cur = _.get(target, path);
                if (typeof cur !== 'number') {
                    // 目标字段缺失 → 初始化默认值后加成（基础属性 10，上限类 0）
                    cur = path.indexOf('基础属性') !== -1 ? 10 : 0;
                }
                _.set(target, path, Math.max(0, cur + sign * bonus[k]));
            });
        }
        // 装备栏显示：面板效果全键通用渲染（防御+2 / 敏捷+1 / HP上限+10 …）+ 词条 + 特别机制
        function renderEquipEffects(item) {
            var html = '';
            var bp = item && item.面板效果 ? item.面板效果 : null;
            if (bp) {
                Object.keys(bp).forEach(function (k) {
                    var v = bp[k];
                    if (v === undefined || v === null || v === '') return;
                    var color = (k === '防御值' || k.indexOf('上限') !== -1) ? '#2980b9' : (k === '攻击力' ? '#c0392b' : '#8e44ad');
                    html += ' <span style="color:' + color + ';">' + k + '+' + v + '</span>';
                });
            }
            var tc = item && item.附加词条 && typeof item.附加词条 === 'object' ? Object.keys(item.附加词条).map(function (k) { return item.附加词条[k]; }).filter(function (v) { return v; }).join('；') : '';
            if (tc) html += ' <span style="color:#a06020;">词条：' + escapeAttr(tc) + '</span>';
            var spec = item && item.特别机制 ? String(item.特别机制).trim() : '';
            if (spec) html += ' <span style="color:#8e44ad;font-weight:bold;">特：' + escapeAttr(spec) + '</span>';
            return html;
        }

        async function equipItem(itemName) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var inv = _.get(stat, '主角.资产与能力.物品栏', {});
                var item = inv[itemName];
                if (!item) { if (window.toastr) toastr.warning('物品「' + itemName + '」不在物品栏中'); return; }
                var slot = item.装备位 || '无';
                if (slot !== '头部' && slot !== '颈部' && slot !== '躯干' && slot !== '腿部' && slot !== '双手') {
                    if (window.toastr) toastr.error('「' + itemName + '」没有可用的装备部位词条，无法装备'); return;
                }
                var equip = _.get(stat, '主角.资产与能力.装备栏', {});
                if (!equip || Object.keys(equip).length === 0) { equip = { 头部: {}, 颈部: {}, 躯干: {}, 腿部: {}, 双手: {} }; _.set(stat, '主角.资产与能力.装备栏', equip); }
                // 该部位已有装备 → 先退回物品栏（并撤销旧装备的属性加成）
                var old = equip[slot] || {};
                if (old && Object.keys(old).length > 0 && old.物品名) {
                    applyEquipBonusTo(stat.主角, calcEquipBonus(old), -1);
                    if (inv[old.物品名]) {
                        var oq = parseInt(inv[old.物品名].数量 || 1, 10) || 1;
                        inv[old.物品名].数量 = oq + 1;
                    } else {
                        inv[old.物品名] = _.omit(old, ['物品名']);
                    }
                }
                // 写入新装备（保留物品名便于卸下）并应用属性加成
                equip[slot] = _.extend({}, item, { 物品名: itemName });
