                // 该部位已有装备 → 先退回物品栏（并撤销旧装备的属性加成）
                var old = equip[slot] || {};
                if (old && Object.keys(old).length > 0 && old.物品名) {
                    applyEquipBonusTo(comp, calcEquipBonus(old), -1);
                    if (inv[old.物品名]) {
