        let editorDataCopy = null;
        // 全局修改器打开时的原始快照：保存时对比等级/属性变化，调升级脚本补齐三维/技能点
        let editorOriginalCopy = null;

        // ===== 全局修改器·上帝模式补齐三维 =====
        // diff 单个角色：返回 { jobs: {职业名:+N}, attr: {六维:Δ} }；仅职业等级正增量会补三维（降级/删职业不回收）
        function diffActorGrowth(oldA, newA) {
            var jobs = {}, attr = {};
            var oj = (oldA && oldA.基础状态 && oldA.基础状态.职业信息) || {};
            var nj = (newA && newA.基础状态 && newA.基础状态.职业信息) || {};
            Object.keys(nj).forEach(function(k) {
                var nl = parseInt(nj[k] && nj[k].等级, 10) || 0;
                var ol = parseInt((oj[k] && oj[k].等级), 10) || 0;
                var d = nl - ol;
                if (d > 0) jobs[k] = d;
            });
            var oa = (oldA && oldA.基础属性) || {};
            var na = (newA && newA.基础属性) || {};
            ['力量', '敏捷', '体质', '智力', '感知', '魅力'].forEach(function(a) {
                var d = (parseInt(na[a], 10) || 0) - (parseInt(oa[a], 10) || 0);
                if (d !== 0) attr[a] = d;
            });
            return { jobs: jobs, attr: attr };
        }
        // 对比 打开前/保存后 的 stat_data，对主角/同伴的职业等级与属性变化调用升级脚本补齐三维/技能点
        async function applyVarEditorGrowth(original, edited) {
            if (!original || !edited) return;
            var upgradeApi = (typeof window !== 'undefined' && window.升级脚本) || (window.parent && window.parent.升级脚本);
            if (!upgradeApi || typeof upgradeApi.应用分配 !== 'function') {
                if (window.toastr) toastr.error('⚠️ 已保存，但未找到「升级代码」脚本，等级/属性变化不会补三维！请加载「升级代码」后重试');
                return;
            }
            var growth = {};
            if (original.主角 && edited.主角) {
                var d = diffActorGrowth(original.主角, edited.主角);
                if (Object.keys(d.jobs).length || Object.keys(d.attr).length) growth['主角'] = d;
            }
            var compsO = original.同伴 || {}, compsN = edited.同伴 || {};
            Object.keys(compsN).forEach(function(name) {
                if (!compsO[name]) return;
                var d = diffActorGrowth(compsO[name], compsN[name]);
                if (Object.keys(d.jobs).length || Object.keys(d.attr).length) growth[name] = d;
            });
            var targets = Object.keys(growth);
            for (var i = 0; i < targets.length; i++) {
                var t = targets[i];
                try { await upgradeApi.应用分配({ target: t, jobs: growth[t].jobs, attr: growth[t].attr }); }
                catch (e) { console.error('全局修改器补齐三维失败:', e); if (window.toastr) toastr.error('补齐三维失败：' + (e && e.message ? e.message : e)); }
            }
            if (targets.length && window.toastr) {
                toastr.success('✅ 已保存，并为 ' + targets.length + ' 个角色补齐了等级/属性对应的 HP/MP/SP/技能点');
            }
        }

        // ===== 全局修改器·快捷分区 =====
        // 分区名 → stat_data 下的路径（'' = 整个 stat_data）
        let vtSections = [
            { label: '全部', path: '' },
            { label: '世界', path: '世界' },
            { label: '主角·基础状态', path: '主角.基础状态' },
            { label: '主角·基础属性', path: '主角.基础属性' },
            { label: '主角·职业信息', path: '主角.基础状态.职业信息' },
            { label: '主角·资产与能力', path: '主角.资产与能力' },
            { label: '主角·任务', path: '主角.任务' },
            { label: '英灵', path: '英灵' },
            { label: '同伴', path: '同伴' },
            { label: '主要NPC', path: '主要NPC' },
            { label: '家族', path: '家族' },
            { label: '产业', path: '产业' },
            { label: '领地', path: '领地' },
            { label: '$customSkillTrees', path: '$customSkillTrees' },
            { label: '$flags', path: '$flags' }
        ];
        let vtCurrentSection = '';
        // 当前激活页签 → 默认编辑分区（打开修改器时自动定位到正在看的页签）
        function vtSectionForActiveTab() {
            const map = {
                'tab-basic': '主角.基础状态',
                'tab-assets': '主角.资产与能力',
                'tab-quests': '主角.任务',
                'tab-knowledge': '世界',
                'tab-party': '同伴',
                'tab-advanced': '主角.资产与能力',
                'tab-skilltree': '主角.基础状态.职业信息',
                'tab-alloc': '主角.基础状态.职业信息',
                'tab-family': '家族',
                'tab-industry': '产业',
                'tab-territory': '领地'
            };
            const $tab = $('.jrpg-status-wrapper .jrpg-tab-btn.active');
            const id = $tab.length ? $tab.data('tab') : '';
            return map[id] || '主角.基础状态';
        }
        // 渲染分区导航按钮
        function renderVtNav() {
            let html = '';
            vtSections.forEach(function(s) {
                const active = s.path === vtCurrentSection ? ' active' : '';
                html += '<button class="vt-nav-btn' + active + '" data-vt-sec="' + s.path + '">' + s.label + '</button>';
            });
            $('#vt-nav').html(html);
        }
        // 递归判断某子树是否含关键词匹配（用于搜索剪枝）
        function vtChildMatches(obj, keyword) {
            if (obj === null || obj === undefined) return false;
            for (let k in obj) {
                let v = obj[k];
                if (typeof v === 'object' && v !== null) { if (vtChildMatches(v, keyword)) return true; }
                else if (String(k).toLowerCase().indexOf(keyword) !== -1 || String(v).toLowerCase().indexOf(keyword) !== -1) return true;
            }
            return false;
        }

        // 渲染变量树；keyword 非空时按「键名/值」剪枝过滤
        function renderVarTree(obj, path, keyword) {
            keyword = (keyword || '').trim().toLowerCase();
            let html = '<ul class="vt-ul">';
            for (let key in obj) {
                let val = obj[key];
                let currentPath = path ? path + '.' + key : key;
                let valType = Array.isArray(val) ? 'array' : (val === null ? 'null' : typeof val);
                let keyHit = keyword && String(key).toLowerCase().indexOf(keyword) !== -1;

                // 搜索剪枝：键名不匹配时，对象需子树含匹配、叶子需值匹配，否则整支隐藏
                if (keyword) {
                    if (valType === 'object' || valType === 'array') {
                        if (!keyHit && !vtChildMatches(val, keyword)) continue;
                    } else {
                        if (!keyHit && String(val).toLowerCase().indexOf(keyword) === -1) continue;
                    }
                }

                html += '<li class="vt-li">';
                if (valType === 'object' || valType === 'array') {
                    html += `<div class="vt-row"><span class="vt-key vt-folder" data-path="${currentPath}">📁 ${key}</span><span class="vt-type-badge">${valType === 'array' ? '列表' : '对象'}</span><button class="vt-btn-add" data-path="${currentPath}" title="添加子项">➕ 新增</button><button class="vt-btn-del" data-path="${currentPath}" title="删除此项">❌ 删</button></div>`;
                    html += `<div class="vt-children" data-path="${currentPath}">${renderVarTree(val, currentPath, keyword)}</div>`;
                } else {
                    html += `<div class="vt-row"><span class="vt-key">📝 ${key}:</span><input type="text" class="vt-input" data-path="${currentPath}" value="${(val+'').replace(/"/g, '&quot;')}"><span class="vt-type-badge">${valType}</span><button class="vt-btn-del" data-path="${currentPath}" title="删除此项">❌ 删</button></div>`;
                }
                html += '</li>';
            }
            html += '</ul>';
            return html;
        }

        function initVarEditor() {
            // ★ 全局修改器：点击进入/退出「修改模式」（数值点击直接编辑、条目垃圾桶删除，自动写回+热加载）
            $('#btn-open-editor').on('click', function() {
                if (typeof Mvu === 'undefined') return alert('MVU框架未初始化');
                toggleEditMode();
            });

            $('#btn-close-editor').on('click', function() {
                $('#var-editor-inline').slideUp(150);
                editorDataCopy = null;
                editorOriginalCopy = null;
                vtCurrentSection = '';
                $('#vt-search').val('');
            });

            // 快捷分区导航 + 搜索过滤
            $('#vt-nav').on('click', '.vt-nav-btn', function() {
                vtCurrentSection = $(this).data('vt-sec') || '';
                renderVtNav();
                refreshEditorView();
            });
            $('#vt-search').on('input', function() { refreshEditorView(); });
            $('#vt-search-clear').on('click', function() { $('#vt-search').val(''); refreshEditorView(); });



            $('#var-tree-container').on('change', '.vt-input', function() {
                let path = $(this).data('path');
                let rawVal = $(this).val();
                let finalVal = rawVal;
                if (!isNaN(rawVal) && rawVal.trim() !== '') {
                    finalVal = Number(rawVal);
                } else if (rawVal.toLowerCase() === 'true') {
                    finalVal = true;
                } else if (rawVal.toLowerCase() === 'false') {
                    finalVal = false;
                }
                _.set(editorDataCopy, path, finalVal);
                vtCommitWriteback();
            });

            $('#var-tree-container').on('click', '.vt-folder', function() {
                let path = $(this).data('path');
                $(`.vt-children[data-path="${path}"]`).slideToggle(150);
            });

            $('#var-tree-container').on('click', '.vt-btn-del', function() {
                let path = $(this).data('path');
                if (confirm(`确定要删除 [${path}] 吗？\n删除后不可恢复！`)) {
                    let pathArr = path.split('.');
                    if (pathArr.length === 1) {
                        delete editorDataCopy[path];
                    } else {
                        let key = pathArr.pop();
                        let parentPath = pathArr.join('.');
                        let parentObj = _.get(editorDataCopy, parentPath);
                        if (Array.isArray(parentObj)) {
                            parentObj.splice(parseInt(key), 1);
                        } else {
                            delete parentObj[key];
                        }
                    }
                    vtCommitWriteback();
                }
            });

            $('#var-tree-container').on('click', '.vt-btn-add', function() {
                let path = $(this).data('path');
                let parentObj = _.get(editorDataCopy, path);
                let isArr = Array.isArray(parentObj);
                let newKey = isArr ? parentObj.length : prompt(`要在 [${path}] 下新增键，请输入新键名：`);
                if (newKey === null || (!isArr && newKey.trim() === '')) return;
                let typeStr = prompt(`请选择新增内容的类型：\n1. 文本/数字\n2. 对象(包含子属性)\n3. 列表(数组)\n请输入数字 1、2 或 3：`, "1");
                let newVal = "";
                if (typeStr === "2") newVal = {};
                else if (typeStr === "3") newVal = [];
                else if (typeStr !== "1") return;
                if (isArr) { parentObj.push(newVal); } else { parentObj[newKey] = newVal; }
                vtCommitWriteback();
            });
        }

        // 全局修改器·点击即改即写回（热加载）：修改/删除/新增后立即写回楼层并刷新界面
        // ===== 修改模式：数值点击直接编辑 / 条目垃圾桶删除，自动写回 + 热加载 =====
        var editMode = false;
        function toggleEditMode() {
            editMode = !editMode;
            $('.jrpg-status-wrapper').toggleClass('edit-mode', editMode);
            if (editMode) {
                try {
                    var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    editorDataCopy = JSON.parse(JSON.stringify(mvuData.stat_data || {}));
                    editorOriginalCopy = JSON.parse(JSON.stringify(mvuData.stat_data || {}));
                } catch (e) {}
                if (window.toastr) toastr.info('🔧 已进入修改模式：数值点击直接编辑，条目带 🗑 可删除，改动自动写回并热加载');
            } else {
                if (window.toastr) toastr.success('已退出修改模式');
            }
            populateCharacterData();
        }
        // 修改模式：给主角面板数值绑定可编辑（下划线 + 点击输入）
        function editBindMainValues() {
            var binds = [
                ['#val-world-date', '世界.日期'],
                ['#val-world-time', '世界.时间'],
                ['#val-world-weather', '世界.天气'],
