        async function vtCommitWriteback() {
            if (!editorDataCopy || typeof Mvu === 'undefined') return;
            try {
                const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                mvuData.stat_data = editorDataCopy;
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                try { await applyVarEditorGrowth(editorOriginalCopy, editorDataCopy); } catch (e) { console.error('[状态栏] 全局修改器补齐三维失败:', e); }
                editorOriginalCopy = JSON.parse(JSON.stringify(editorDataCopy));
                populateCharacterData();
                // 同伴弹窗开着时刷新（修改同伴字段后热加载）
                if (window.__curCompDetail && $('#companion-detail-modal').length && $('#companion-detail-modal').is(':visible')) {
                    try { renderCompanionDetail(window.__curCompDetail); } catch (e2) {}
                }
            } catch (e) {
                console.error('[状态栏] 全局修改器写回失败:', e);
                if (window.toastr) toastr.error('写回失败：' + (e && e.message ? e.message : e));
            }
        }

        function refreshEditorView() {
            if (!editorDataCopy) return;
            const keyword = $('#vt-search').val();
            const data = vtCurrentSection ? _.get(editorDataCopy, vtCurrentSection) : editorDataCopy;
            if (data === undefined || data === null) {
                $('#var-tree-container').html('<div class="jrpg-list-empty">该分区暂无数据（可切回「全部」，或在对应位置用 ➕ 新增）</div>');
                return;
            }
            $('#var-tree-container').html(renderVarTree(data, vtCurrentSection, keyword));
        }

        // ============================================================
        //  主角系统字段只读：总等级 / 经验值.升级所需（AI 不可写，脚本托管）
        //  仅拦截主角；同伴的同名字段不受影响（AI 可正常维护）
        // ============================================================
        function filterProtagonistReadonlyCommands(commands) {
            if (!commands || !commands.length) return;
            // 命中主角只读字段（前缀匹配，防止整体替换绕过）：
            //   - 主角.基础状态.总等级[/...]
            //   - 主角.基础状态.经验值.升级所需[/...]
            //   - 主角.基础状态.经验值（整体 replace 会顺带覆盖升级所需，一并拦截；
            //     经验值.当前 的 delta/add 不受影响，AI 加经验照常）
            function hitReadonlySegs(segs) {
                if (!segs || segs.length < 3 || segs[0] !== '主角') return false;
                if (segs[1] !== '基础状态') return false;
                if (segs[2] === '总等级') return true;
                if (segs[2] === '经验值') {
                    if (segs.length === 3) return true;           // 整体经验值
                    if (segs[3] === '升级所需') return true;      // 升级所需及其子路径
                }
                return false;
            }
            for (var i = commands.length - 1; i >= 0; i--) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                var segs = pathToSegments(cmd.args[0]);
                // 兼容 stat_data. 前缀（zod 解析前的原始路径可能带前缀）
                if (segs[0] === 'stat_data' || segs[0] === 'status_current_variables') segs = segs.slice(1);
                var hit = hitReadonlySegs(segs);
                // move 的目标指向只读字段也拒绝
                if (cmd.type === 'move' && cmd.args.length > 1) {
                    var toSegs = pathToSegments(cmd.args[1]);
                    if (toSegs[0] === 'stat_data' || toSegs[0] === 'status_current_variables') toSegs = toSegs.slice(1);
                    if (hitReadonlySegs(toSegs)) hit = true;
                }
                if (hit) {
                    commands.splice(i, 1);
                }
            }
        }

        // ============================================================
        //  ★ 追踪记录硬拦截：世界.追踪记录 只允许 insert（新增一条流水）
        //  replace/remove/add/move 一律丢弃 —— AI 可见可写但不可覆盖/删除历史流水
        // ============================================================
        function filterTrackRecordCommands(commands) {
            if (!commands || !commands.length) return;
            function hitTrackSegs(segs) {
                if (!segs || segs.length < 2) return false;
                if (segs[0] === 'stat_data' || segs[0] === 'status_current_variables') segs = segs.slice(1);
                if (segs.length < 2 || segs[0] !== '世界' || segs[1] !== '追踪记录') return false;
                return true;
            }
            for (var i = commands.length - 1; i >= 0; i--) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                var segs = pathToSegments(cmd.args[0]);
                if (segs[0] === 'stat_data' || segs[0] === 'status_current_variables') segs = segs.slice(1);
                var isTrack = hitTrackSegs(segs);
                var isMoveToTrack = false;
                if (cmd.type === 'move' && cmd.args.length > 1) {
                    var toSegs = pathToSegments(cmd.args[1]);
                    if (toSegs[0] === 'stat_data' || toSegs[0] === 'status_current_variables') toSegs = toSegs.slice(1);
                    isMoveToTrack = hitTrackSegs(toSegs);
                }
                // 命中追踪记录：仅放行「向容器新增单条」的 insert（路径恰好 世界/追踪记录/记录ID），
                // 且条目「类型」必须命中六类白名单（金盾入账/支出、购买/出售/更换物品、物品获得/失去、经验获取、货币变动）
                var isOneInsert = cmd.type === 'insert' && segs.length === 3;
                if (isTrack || isMoveToTrack) {
                    if (isOneInsert) {
                        var TRACK_TYPES = ['金盾入账', '金盾支出', '购买物品', '出售物品', '更换物品', '物品获得', '物品失去', '经验获取', '货币变动'];
                        var tVal = cmd.args[1] && cmd.args[1].类型 ? String(cmd.args[1].类型).trim() : '';
                        if (TRACK_TYPES.indexOf(tVal) === -1) {
                            commands.splice(i, 1);           // 类型不在白名单：丢弃
                            if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning('⚠️ 已拦截 AI 写入追踪记录的类型「' + (tVal || '未标明类型') + '」（仅允许：金盾入账/支出、购买/出售/更换物品、物品获得/失去、经验获取、货币变动）', '追踪记录');
                        }
                        continue;                            // 放行：新增一条合法流水
                    }
                    commands.splice(i, 1);                   // 其余一律丢弃
                    if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning('⚠️ 已拦截 AI 对 追踪记录 的 ' + cmd.type + ' 操作（仅允许新增流水）', '追踪记录');
                }
            }
        }

        // ============================================================
        //  ★ 家族/产业写入守卫：
        //  - 产业：放行 insert 新产业（/产业/名）与子字段 replace（描述/状态/每期收益/位置等）；
        //          拦截 remove（防删账）、整条 replace（防覆盖脚本托管的 上次结算）、对 上次结算 的任何写入
        //  - 家族.成员：放行 insert 新成员与子字段 replace（称谓/存亡/好感度/描述等）；
        //          拦截 remove（死亡用 replace 存亡，禁删成员）、整条 replace（防覆盖 培养计划）、
        //          对 培养计划/培养记录 的写入（玩家在状态栏设置、结算脚本维护）、出生年月日 的改写（首次补写除外）
        // ============================================================
        function famBirthFromAge(age, nowStr) {
            var m = String(nowStr || '').match(/(\d{4})年?\s*(\d{1,2})?月?\s*(\d{1,2})?日?/);
            if (!m) return '';
            var y = parseInt(m[1], 10), mo = parseInt(m[2] || 1, 10), d = parseInt(m[3] || 1, 10);
            var by = y - (parseInt(age, 10) || 0);
            if (mo === 2 && d === 29 && by % 4 !== 0) d = 28;
            return '圣光历' + by + '年' + mo + '月' + d + '日';
        }
        function filterFamilyIndustryCommands(commands) {
            if (!commands || !commands.length) return;
            var stat = null;
            try { stat = _.get(Mvu.getMvuData({ type: 'message', message_id: 'latest' }), 'stat_data', {}); } catch (e) {}
            function stripRoot(segs) {
                if (segs.length && (segs[0] === 'stat_data' || segs[0] === 'status_current_variables')) return segs.slice(1);
                return segs;
            }
            function block(i, msg) {
                commands.splice(i, 1);
                if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning(msg, '状态栏');
            }
            for (var i = commands.length - 1; i >= 0; i--) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                var segs = stripRoot(pathToSegments(cmd.args[0]));
                var root = segs[0];
                if (root !== '产业' && root !== '家族') continue;
                if (cmd.type === 'move') { block(i, '⚠️ 已拦截 AI 对 ' + root + ' 的 move 操作'); continue; }
                if (root === '产业') {
                    if (cmd.type === 'insert' && segs.length === 2) continue;   // 新增产业：放行
                    if (cmd.type === 'replace' && segs.length >= 3) {
                        if (segs[2] === '上次结算') { block(i, '⛔ 产业的 上次结算 由结算脚本托管，AI 禁止修改'); continue; }
                        continue;                                               // 子字段修改：放行
                    }
                    block(i, '⚠️ 已拦截 AI 对 产业「' + (segs[1] || '') + '」的 ' + cmd.type + ' 操作（仅允许新增产业或修改其子字段；停业请 replace 状态）');
                    continue;
                }
                // —— 家族 ——
                if (segs.length === 2 && cmd.type === 'replace') continue;      // /家族/谱系说明
                if (segs[1] !== '成员' || segs.length < 3) { block(i, '⚠️ 已拦截 AI 对 家族 的非法操作（成员按 /家族/成员/姓名 路径写入）'); continue; }
                var name = segs[2];
                var member = (stat && stat.家族 && stat.家族.成员) ? stat.家族.成员[name] : null;
                if (cmd.type === 'insert' && segs.length === 3) {
                    // 整条新成员：无出生年月日但有年龄 → 自动换算（与主要NPC收录逻辑一致）
                    var val = cmd.args[1];
                    if (val && typeof val === 'object' && !val.出生年月日 && val.年龄) {
                        var bv = famBirthFromAge(val.年龄, _.get(stat, '世界.日期', '') || '');
                        if (bv) { val.出生年月日 = bv; delete val.年龄; }
                    }
                    continue;
                }
                if (segs.length >= 4) {
                    var field = segs[3];
                    if (field === '培养记录') { block(i, '⛔ 培养记录由结算脚本维护，AI 禁止修改'); continue; }
                    if (field === '培养计划') {
                        // 唯一放行：重大成长节点演化 期望职业（replace /家族/成员/名/培养计划/期望职业，见规则）
                        if (cmd.type === 'replace' && segs.length === 5 && segs[4] === '期望职业') continue;
                        block(i, '⛔ 培养计划由玩家托管（仅「期望职业」可在成长节点由 AI 演化）'); continue;
                    }
                    if (field === '技能') { continue; }   // AI 可 insert 新技能 / replace 等级（拜师/传承授予）
                    if (field === '出生年月日') {
                        if (cmd.type === 'replace' && member && member.出生年月日) { block(i, '⛔ 已拦截对家族成员「' + name + '」出生年月日的修改：一经确定不改'); continue; }
                        if (cmd.type !== 'replace') { block(i, '⛔ 已拦截 AI 对家族成员「' + name + '」出生年月日的 ' + cmd.type + ' 操作'); continue; }
                        continue;                                               // 首次补写：放行
                    }
                    if (field === '年龄') {
                        if (member && member.出生年月日) { block(i, '⛔ 家族成员「' + name + '」年龄按出生日期自动计算，AI 禁止改写'); continue; }
                        var bva = famBirthFromAge(cmd.args[1], _.get(stat, '世界.日期', '') || '');
                        if (bva) { cmd.type = 'replace'; cmd.args[0] = '家族.成员.' + name + '.出生年月日'; cmd.args[1] = bva; }
                        continue;
                    }
                    if (cmd.type === 'replace') continue;                       // 子字段修改：放行
                    block(i, '⚠️ 已拦截 AI 对家族成员「' + name + '」子字段的 ' + cmd.type + ' 操作');
                    continue;
                }
                block(i, '⚠️ 已拦截 AI 对 家族成员「' + name + '」的 ' + cmd.type + ' 操作（死亡/失踪用 replace 存亡，禁删成员）');
            }
        }

        // ============================================================
        //  名字段规范化 + 已有键 insert 合并（主要NPC/同伴/契约兽/召唤物）
        //  解决：① AI 把「亚伦·伍德」写成 亚伦_伍德 / 亚伦.伍德 / 亚伦・伍德
        //        → 多出残缺条目、同名分叉、只有一句心里话的"幽灵NPC"
        //        ② insert 整条到已存在键 → 覆盖丢字段
        //  做法：字符归一（_/・/•/．→·）+ 被拆断的名字段合并（与现有键对齐）
        //        + insert 目标已存在时展开为逐字段 set（只更新出现字段，不覆盖其他）
        // ============================================================
        function normalizeNpcNameCommands(commands) {
            if (!commands || !commands.length) return;
            var CONTAINERS = ['主要NPC', '同伴', '契约兽', '召唤物'];
            var FIELDS = {
                '主要NPC': ['好感度', '心里话', '年龄', '身份', '当前位置', '关键事件', '关系描述', '关系时间线', '关系分类'],
                '同伴': ['好感度', '心里话', '外貌', '性格', '背景故事', '所属势力', '种族', '身份', '当前位置', '等阶', '基础属性', '基础状态', '防御值', '技能', '物品栏', '装备栏', '资质', '_属性锁定'],
                '契约兽': ['种族', '职业', '契约主', '当前位置', '等阶', '等级', '体型', '元素属性', '羁绊', '防御值', '移动速度', '先攻修正', '外貌', '性格', '所属势力', '背景故事', '状态', '基础属性', '基础状态', '攻击', '能力', '吐息'],
                '召唤物': []   // 动态字段：不做段合并（仅字符归一+现有键对齐）
            };
            var stat = null;
            try { stat = _.get(Mvu.getMvuData({ type: 'message', message_id: 'latest' }), 'stat_data', {}); } catch (e) { return; }
            function fixNameChar(s) { return String(s).replace(/[_\u30fb\u2022\uff0e.]/g, '·'); }
            // 名字段规范化：容器 + 名字（字符归一、拆段合并、与现有键对齐）
            function normNameSegs(segs) {
                var container = segs[0];
                var fields = FIELDS[container] || [];
                // 召唤物：仅字符归一（字段动态，不能按白名单合段）
                if (container === '召唤物') {
                    var n0 = fixNameChar(segs[1]);
                    var k0 = null;
                    var cur0 = (stat && stat[container]) || {};
                    Object.keys(cur0).forEach(function (k) { if (!k0 && (k === n0 || fixNameChar(k) === n0)) k0 = k; });
                    return [container, k0 || n0].concat(segs.slice(2));
                }
                var nameParts = [segs[1]];
                var i = 2;
                while (i < segs.length && fields.indexOf(segs[i]) === -1) { nameParts.push(segs[i]); i++; }
                var nameStr = fixNameChar(nameParts.join('·'));
                var known = null;
                var cur = (stat && stat[container]) || {};
                Object.keys(cur).forEach(function (k) { if (!known && (k === nameStr || fixNameChar(k) === nameStr)) known = k; });
                return [container, known || nameStr].concat(segs.slice(i));
            }
            function addSegs(segs) {
                if (segs[0] === 'stat_data' || segs[0] === 'status_current_variables') return segs.slice(1);
                return segs;
            }
            // insert 整条到已存在键 → 展开为逐字段 set（不覆盖未出现的字段）
            function expandInsert(baseSegs, value, out) {
                var isObj = value && typeof value === 'object' && !Array.isArray(value);
                if (!isObj) {
                    if (value !== undefined) out.push({ type: 'set', full_match: '', args: [baseSegs.join('.'), JSON.stringify(value === null ? '' : value)], reason: '[名字规范化] 已有条目字段写入' });
                    return;
                }
                var keys = Object.keys(value);
                if (!keys.length) { out.push({ type: 'set', full_match: '', args: [baseSegs.join('.'), '{}'], reason: '[名字规范化] 已有条目字段写入' }); return; }
                keys.forEach(function (k) { expandInsert(baseSegs.concat([k]), value[k], out); });
            }
            function mergeIfExisting(commands, idx, segs) {
                var cmd = commands[idx];
                var container = segs[0], name = segs[1];
                var cur = (stat[container] || {});
                if (cmd.type !== 'insert' || segs.length !== 2 || !cur[name]) return false;
                var merged = [];
                expandInsert(segs, cmd.args[1], merged);
                if (!merged.length) return false;
                commands.splice(idx, 1);                 // 移除原 insert
                for (var m = 0; m < merged.length; m++) commands.splice(idx + m, 0, merged[m]);
                return true;
            }
            for (var i = 0; i < commands.length; i++) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                var segs = addSegs(pathToSegments(cmd.args[0]));
                if (segs.length < 2 || CONTAINERS.indexOf(segs[0]) === -1) continue;
                var newSegs = normNameSegs(segs);
                var changed = newSegs.join('.') !== segs.join('.');
                if (cmd.type === 'move' && cmd.args.length > 1) {
                    var tSegs = addSegs(pathToSegments(cmd.args[1]));
                    if (tSegs.length >= 2 && CONTAINERS.indexOf(tSegs[0]) !== -1) {
                        var ntSegs = normNameSegs(tSegs);
                        if (ntSegs.join('.') !== tSegs.join('.')) cmd.args[1] = ntSegs.join('.');
                    }
                }
                if (changed) {
                    cmd.args[0] = newSegs.join('.');
                    cmd.reason = (cmd.reason ? cmd.reason + '；' : '') + '[名字规范化] ' + segs.join('.') + ' → ' + newSegs.join('.');
                    if (mergeIfExisting(commands, i, newSegs)) i += mergedLenHint(commands, i, newSegs);
                } else if (mergeIfExisting(commands, i, newSegs)) {
                    i += mergedLenHint(commands, i, newSegs);
                }
            }
            // 返回本次展开新增的命令数（insert 已被移除，改从当前位置继续）
            function mergedLenHint(commands, idx, segs) {
                var added = 0;
                for (var j = idx; j < commands.length; j++) {
                    if (commands[j] && commands[j].reason && commands[j].reason.indexOf('[名字规范化] 已有条目字段写入') !== -1) added++;
                    else break;
                }
                return Math.max(0, added - 1);
            }
        }
        window.normalizeNpcNameCommands = normalizeNpcNameCommands;

        // ============================================================
        //  出生年月日/年龄 只读守卫：出生年月日一经确定不改；年龄由系统按当前日期自动计算
        //  拦截 主要NPC/同伴 的 .年龄 与 .出生年月日 的 replace/insert/remove/add
        // ============================================================
        function filterImmutableNpcFields(commands) {
            if (!commands || !commands.length) return;
            var stat = null;
            try { stat = _.get(Mvu.getMvuData({ type: 'message', message_id: 'latest' }), 'stat_data', {}); } catch (e) {}
            // 由年龄反推出生年月日：当前纪年日期 倒扣 年龄（月日保留同日，2/29 边界取 28）
            function genBirthFromAge(age, nowStr) {
                var m = String(nowStr || '').match(/(\d{4})年?\s*(\d{1,2})?月?\s*(\d{1,2})?日?/);
                if (!m) return '';
                var y = parseInt(m[1], 10), mo = parseInt(m[2] || 1, 10), d = parseInt(m[3] || 1, 10);
                var by = y - (parseInt(age, 10) || 0);
                if (mo === 2 && d === 29 && by % 4 !== 0) d = 28;
                return '圣光历' + by + '年' + mo + '月' + d + '日';
            }
            for (var i = commands.length - 1; i >= 0; i--) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                var segs = pathToSegments(cmd.args[0]);
                if (segs[0] === 'stat_data' || segs[0] === 'status_current_variables') segs = segs.slice(1);
                if (segs.length < 2 || (segs[0] !== '主要NPC' && segs[0] !== '同伴')) continue;
                var actor = (stat && stat[segs[0]]) ? stat[segs[0]][segs[1]] : null;
                var nowStr = _.get(stat, '世界.日期', '') || '';
                // ── 情况 A：写子路径 /名/年龄 ──
                if (segs.length === 3 && segs[2] === '年龄') {
                    if (actor && actor.出生年月日) {
                        // 已有出生年月日：年龄由系统计算，改写一律拦截
                        commands.splice(i, 1);
                        if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning('⛔ 已拦截对 ' + segs[0] + '「' + segs[1] + '」的年龄改写：出生年月日已定（' + actor.出生年月日 + '），年龄按当前日期自动计算', '状态栏');
                    } else {
                        // 无出生年月日：把「写年龄」自动转换为「写出生年月日」（当前纪年倒扣年龄），年龄由系统接管
                        var birthVal = genBirthFromAge(cmd.args[1], nowStr);
                        if (birthVal) {
                            cmd.type = 'replace';
                            cmd.args[0] = segs[0] + '.' + segs[1] + '.出生年月日';
                            cmd.args[1] = birthVal;
                            cmd.reason = (cmd.reason ? cmd.reason + '；' : '') + '[年龄换算] 由年龄 ' + cmd.args[1] + '（当前纪年倒扣）自动生成出生年月日，年龄将按日期自动计算';
                            if (typeof toastr !== 'undefined' && toastr.info) toastr.info('🔄 已将 ' + segs[0] + '「' + segs[1] + '」的年龄换算为出生年月日：' + birthVal + '（此后年龄自动计算）', '状态栏');
                        }
                    }
                    continue;
                }
                // ── 情况 B：insert 整条新角色且 value 含 年龄（无出生年月日）→ 自动补出生年月日 ──
                if (cmd.type === 'insert' && segs.length === 2 && cmd.args[1] && typeof cmd.args[1] === 'object' && !cmd.args[1].出生年月日 && cmd.args[1].年龄) {
                    var bv = genBirthFromAge(cmd.args[1].年龄, nowStr);
                    if (bv) {
                        cmd.args[1].出生年月日 = bv;
                        delete cmd.args[1].年龄;   // 由出生日期接管（不残留固定年龄）
                        if (typeof toastr !== 'undefined' && toastr.info) toastr.info('🔄 收录 ' + segs[0] + '「' + segs[1] + '」时已自动生成出生年月日：' + bv + '（原年龄换算，此后年龄自动计算；出生年月日一经确定不改）', '状态栏');
                    }
                    continue;
                }
                // ── 情况 C：写/删 出生年月日 子路径：首次 insert 放行，改写/删除拦截 ──
                if (segs.length === 3 && segs[2] === '出生年月日') {
                    if (cmd.type === 'insert' && !(actor && actor.出生年月日)) continue;
                    commands.splice(i, 1);
                    if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning('⛔ 已拦截对 ' + segs[0] + '「' + segs[1] + '」的出生年月日修改：一经确定不改（当前：' + ((actor && actor.出生年月日) || '未设置') + '）', '状态栏');
                }
            }
        }

        // ============================================================
        //  同伴母路径锁定（AI 不能删除/替换整条同伴，但可修改其下属性）
        //  同伴物品栏物品锁定（支持写入·拒绝删除整件锁定物品）
        // ============================================================
        function pathToSegments(path) {
            if (path === undefined || path === null) return [];
            if (String(path).charAt(0) === '/') {
                // JSONPatch 斜杠路径：/同伴/莉莉丝/好感度
                return String(path).split('/').filter(function(s) { return s !== ''; }).map(function(s) {
                    return s.replace(/~1/g, '/').replace(/~0/g, '~');
                });
            }
            // MVU 点号路径：同伴.莉莉丝.好感度
            return String(path).split('.');
        }

        // ============================================================
        //  ★ 经验值增加弹窗确认：拦截 AI 通过指令增加「经验值.当前」，必须点击允许才写入
        //  （只拦 +delta 的 add；replace/整体经验值仍由 filterProtagonistReadonlyCommands 拦截）
        // ============================================================
        function filterExperienceConfirmCommands(commands) {
            if (!commands || !commands.length) return;
            var hasPending = false;
            for (var i = commands.length - 1; i >= 0; i--) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                if (cmd.type !== 'add') continue;                    // 只拦增量增加
                var segs = pathToSegments(cmd.args[0]);
                if (segs[0] === 'stat_data' || segs[0] === 'status_current_variables') segs = segs.slice(1);
                if (segs.join('.') !== '主角.基础状态.经验值.当前') continue;
                var amt = parseInt(cmd.args[1], 10) || 0;
                if (amt <= 0) continue;                              // 只拦增加经验
                // 从原命令流移除（无论允许与否都由本函数落账，避免二次加 / 丢失）
                commands.splice(i, 1);
                hasPending = true;
                // 点击允许才写入
                var ok = false;
                try { ok = confirm('⚠️ AI 试图增加经验 +' + amt + '\n\n是否允许写入（经验值.当前）？\n「确定」= 写入 · 「取消」= 忽略该条经验'); } catch (e) { ok = false; }
                if (ok) {
                    try {
                        var mvuD = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (mvuD && mvuD.stat_data && mvuD.stat_data.主角) {
                            mvuD.stat_data.主角.基础状态 = mvuD.stat_data.主角.基础状态 || {};
                            mvuD.stat_data.主角.基础状态.经验值 = mvuD.stat_data.主角.基础状态.经验值 || { 当前: 0, 升级所需: 100 };
                            mvuD.stat_data.主角.基础状态.经验值.当前 = (parseInt(mvuD.stat_data.主角.基础状态.经验值.当前, 10) || 0) + amt;
                            Mvu.replaceMvuData(mvuD, { type: 'message', message_id: 'latest' });
                        }
                        // 记录经验获取（并入追踪记录流水账）
                        try { trackPush({ 时间: '', 类型: '经验获取', 金额: amt, 物品: '', 数量: 0, 余额: -1, 说明: '主角经验 +' + amt + '（点击允许写入）' }); } catch (e) {}
                        if (typeof toastr !== 'undefined' && toastr.success) toastr.success('已允许写入经验 +' + amt, '经验确认');
                    } catch (e) {
                        if (typeof toastr !== 'undefined' && toastr.error) toastr.error('写入经验失败：' + e.message);
                    }
                } else {
                    if (typeof toastr !== 'undefined' && toastr.warning) toastr.warning('已忽略本次经验 +' + amt, '经验确认');
                }
            }
            if (hasPending && typeof populateCharacterData === 'function') setTimeout(populateCharacterData, 50);
        }

        function filterLockedCompanionCommands(commands) {
            if (!commands || !commands.length) return;
            var mvuData;
            try { mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' }); } catch (e) { return; }
            var comps = _.get(mvuData, 'stat_data.同伴', {});
            // 合并持久锁定（跨楼层）——最新楼层快照可能缺失锁定字段，守卫仍需生效
            try { mergePersistLocksTo({ 同伴: comps }); } catch (e) {}
            var locked = Object.keys(comps || {});   // 所有同伴名（母路径锁定）
            // 收集"物品级锁定"：同伴.{名}.物品栏.{物品名}（物品 _锁定 === true）
            var lockedItemPaths = {};  // 同伴名 -> [物品名]
            var lockedInvPaths = {};   // 同伴名 -> true（含锁定物品，整栏也不允许被删除/替换）
            // 收集"属性级锁定"：同伴 _属性锁定 === true（禁止 AI 修改 基础属性/待分配职业等级/职业信息）
            var attrLockedComps = {};
            var fullLockedComps = {};
            Object.entries(comps || {}).forEach(function(ce) {
                var compName = ce[0];
                var comp = ce[1] || {};
                if (comp._属性锁定 === true) attrLockedComps[compName] = true;
                if (comp._全锁定 === true) fullLockedComps[compName] = true;
                var inv = comp.物品栏 || {};
                var names = [];
                Object.entries(inv).forEach(function(ie) {
                    if ((ie[1] || {})._锁定 === true) names.push(ie[0]);
                });
                if (names.length) {
                    lockedItemPaths[compName] = names;
                    lockedInvPaths[compName] = true;
                }
            });

            function hitLockedSegs(segs) {
                if (!segs || segs.length < 2 || segs[0] !== '同伴') return false;
                // 整条同伴
                if (segs.length === 2 && locked.indexOf(segs[1]) !== -1) return true;
                // 整个物品栏（含锁定物品）
                if (segs.length === 3 && segs[2] === '物品栏' && !!lockedInvPaths[segs[1]]) return true;
                // 整件锁定物品
                // 一键全锁：物品栏任意深度（含子字段如 .数量/.描述）完全只读，拒绝 AI 修改/删除
                if (segs.length >= 3 && segs[2] === '物品栏' && fullLockedComps[segs[1]]) return true;
                // 一键全锁：装备栏同样只读（拒绝 AI 修改/删除/替换装备），跨楼层经 persistLocks 持久
                if (segs.length >= 3 && segs[2] === '装备栏' && fullLockedComps[segs[1]]) return true;
                if (segs.length === 4 && segs[2] === '物品栏' &&
                    lockedItemPaths[segs[1]] && lockedItemPaths[segs[1]].indexOf(segs[3]) !== -1) return true;
                return false;
            }

            // 属性锁定：命中 同伴.{名}.基础属性[/…] / 基础状态.待分配职业等级 / 基础状态.职业信息[/…]
            // （基础状态其余字段如 HP/MP/SP/经验值/自身状态 仍可由 AI 更新；技能不在此锁定范围）
            function hitLockedAttrSegs(segs) {
                if (!segs || segs.length < 3 || segs[0] !== '同伴') return false;
                if (!attrLockedComps[segs[1]]) return false;
                var base = segs[2];
                if (base === '基础属性') return true;                       // 整棵基础属性（六维+未分配点数）
                if (base === '基础状态' && segs.length >= 4) {
                    var sub = segs[3];
                    if (sub === '待分配职业等级' || sub === '职业信息') return true;
                }
                return false;
            }

            for (var i = commands.length - 1; i >= 0; i--) {
                var cmd = commands[i];
                if (!cmd || !cmd.args || !cmd.args.length) continue;
                var segs = pathToSegments(cmd.args[0]);
                // 命中锁定路径：整条同伴 / 整个物品栏 / 整件锁定物品 / 锁定属性
                // （不允许 set/delete/insert/add/move 覆盖或移除；物品子字段如 .数量/.描述 仍可写入）
                var hitLocked = hitLockedSegs(segs) || hitLockedAttrSegs(segs);
                if (hitLocked) {
                    commands.splice(i, 1);
                    continue;
                }
                // move 的目标指向锁定路径也拒绝
                if (cmd.type === 'move' && cmd.args.length > 1) {
                    var toSegs = pathToSegments(cmd.args[1]);
                    if (hitLockedSegs(toSegs) || hitLockedAttrSegs(toSegs)) {
                        commands.splice(i, 1);
                    }
                }
            }
        }

        // ============================================================
        //  锁定状态持久化（跨楼层）——修复"锁定在下一楼层失效"
        // ============================================================
        // 原实现只把锁定字段写入"最新楼层"的 stat_data，而 MVU 每楼一份快照、
        // 跨楼层传播依赖快照复制，一旦新楼层缺失锁定字段就会"失效"。
        // 这里把锁定状态额外同步到「聊天变量」（跨楼层持久）：
        //   - 渲染时合并，保证任意楼层都显示锁定；
        //   - AI 变量更新结束后回注到最新楼层，保证过滤守卫/物品还原有据可依。
        var PERSIST_LOCK_KEY = 'stat_data.$locks';
        function getPersistLocks() {
            try {
                var v = getVariables({ type: 'chat' });
                return _.get(v, PERSIST_LOCK_KEY, {});
            } catch (e) { return {}; }
        }
        function savePersistLocks(locks) {
            try {
                var v = getVariables({ type: 'chat' });
                _.set(v, PERSIST_LOCK_KEY, locks);
                replaceVariables(v, { type: 'chat' });
            } catch (e) { console.error('[状态栏] 保存持久锁定失败:', e); }
        }
        // 把持久锁定合并到目标 stat_data 对象（渲染显示 / 守卫读取共用）
        function mergePersistLocksTo(statData) {
            if (!statData || typeof statData !== 'object') return;
            var locks = getPersistLocks();
            var comps = (locks && locks.同伴) || {};
            Object.keys(comps).forEach(function(compName) {
                var lockInfo = comps[compName] || {};
                var comp = _.get(statData, ['同伴', compName]);
                if (!comp || typeof comp !== 'object') return;
                if (lockInfo._属性锁定 === true) comp._属性锁定 = true;
                if (lockInfo._全锁定 === true) comp._全锁定 = true;
                var inv = comp.物品栏;
                if (inv && typeof inv === 'object') {
                    var itemLocks = lockInfo.物品栏 || {};
                    Object.keys(itemLocks).forEach(function(itemName) {
                        if (itemLocks[itemName] && itemLocks[itemName]._锁定 === true &&
                            inv[itemName] && typeof inv[itemName] === 'object') {
                            inv[itemName]._锁定 = true;
                        }
                    });
                }
            });
        }
        // 把持久锁定回注到最新楼层并写回（AI 更新结束后调用）
        function applyPersistLocksToLatest() {
            try {
                if (typeof Mvu === 'undefined') return;
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = mvuData.stat_data || (mvuData.stat_data = {});
                mergePersistLocksTo(stat);
                Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
            } catch (e) { console.error('[状态栏] 回注持久锁定失败:', e); }
        }

        // ============================================================
        //  同伴物品栏物品锁定：切换 / 快照 / 拒绝删除守卫
        // ============================================================
        // 记录每个同伴已锁定物品的上次数据快照: { 同伴名: { 物品名: 物品数据 } }
        var compLockedItemSnapshot = {};

        // 依据当前数据重建锁定快照；"完全消失"的已锁定物品保留旧快照继续守卫（防止异步写回期间丢失保护）
        function updateCompLockedItemSnapshot() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var companions = _.get(all, 'stat_data.同伴', {});
            var next = {};
            Object.entries(companions).forEach(function(entry) {
                var compName = entry[0];
                var c = entry[1] || {};
                var inv = c.物品栏 || {};
                Object.entries(inv).forEach(function(invEntry) {
                    var itemName = invEntry[0];
                    var item = invEntry[1] || {};
                    if (item._锁定 === true) {
                        if (!next[compName]) next[compName] = {};
                        next[compName][itemName] = JSON.parse(JSON.stringify(item));
                    }
                });
            });
            // 保留上一个快照中"仍然锁定、但当前键完全消失"的条目（存在但已解锁的条目正常清除）
            Object.entries(compLockedItemSnapshot).forEach(function(compEntry) {
                var compName = compEntry[0];
                var comp = companions[compName];
                if (!comp || typeof comp !== 'object') return; // 同伴整体被移除 → 不强行保留
                var curInv = comp.物品栏 || {};
                Object.entries(compEntry[1] || {}).forEach(function(itemEntry) {
                    var itemName = itemEntry[0];
                    var prevItem = itemEntry[1];
                    if (prevItem && prevItem._锁定 === true && !(itemName in curInv)) {
                        if (!next[compName]) next[compName] = {};
                        next[compName][itemName] = JSON.parse(JSON.stringify(prevItem));
                    }
                });
            });
            compLockedItemSnapshot = next;
        }

        // 锁定守卫：锁定物品若从同伴物品栏消失（被 AI/脚本/玩家删除），自动还原，拒绝删除
        function enforceCompItemLocks() {
            if (typeof Mvu === 'undefined') return false;
            var changed = false;
            var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            var stat = mvuData.stat_data || (mvuData.stat_data = {});
            Object.entries(compLockedItemSnapshot).forEach(function(compEntry) {
                var compName = compEntry[0];
                var lockedItems = compEntry[1] || {};
                if (Object.keys(lockedItems).length === 0) return;
                var comp = _.get(stat, ['同伴', compName], null);
                if (!comp || typeof comp !== 'object') return; // 同伴整体不存在则不强建
                if (!comp.物品栏 || typeof comp.物品栏 !== 'object') {
                    comp.物品栏 = {};
                    changed = true;
                }
                Object.entries(lockedItems).forEach(function(itemEntry) {
                    var itemName = itemEntry[0];
                    if (!comp.物品栏[itemName]) {
                        comp.物品栏[itemName] = JSON.parse(JSON.stringify(itemEntry[1]));
                        changed = true;
                        if (window.toastr) toastr.warning('🔒 已还原被删除的锁定物品「' + itemName + '」（同伴「' + compName + '」）');
                    }
                });
            });
            if (changed) {
                Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
            }
            return changed;
        }

        // ============================================================
        //  同伴整体锁定：整条同伴被 AI 删除时按快照重建（变量更新结束触发）
        // ============================================================
        // 记录每个"已锁定同伴"（_全锁定/_属性锁定/含锁定物品）的整体快照: { 同伴名: 整个同伴对象 }
        var compLockedFullSnapshot = {};

        function updateCompLockedFullSnapshot() {
            var all = typeof getAllVariables === 'function' ? getAllVariables() : {};
            var companions = _.get(all, 'stat_data.同伴', {});
            var next = {};
            Object.entries(companions || {}).forEach(function(entry) {
                var compName = entry[0];
                var c = entry[1];
                if (!c || typeof c !== 'object') return;
                var isLocked = c._全锁定 === true || c._属性锁定 === true;
                if (!isLocked) {
                    var inv = c.物品栏 || {};
                    Object.keys(inv).forEach(function(itemName) {
                        if ((inv[itemName] || {})._锁定 === true) isLocked = true;
                    });
                }
                if (isLocked) next[compName] = JSON.parse(JSON.stringify(c));
            });
            // 旧快照中已锁定、但当前整条消失的同伴保留旧快照（供重建）
            Object.entries(compLockedFullSnapshot).forEach(function(entry) {
                var compName = entry[0];
                if (!companions[compName] && Object.keys(entry[1] || {}).length) {
                    next[compName] = JSON.parse(JSON.stringify(entry[1]));
                }
            });
            compLockedFullSnapshot = next;
        }

        // 同伴整条被 AI 删除时：用快照重建（挂在 VARIABLE_UPDATE_ENDED，任何写回都会触发）
        function enforceCompPresence() {
            if (typeof Mvu === 'undefined') return false;
            if (!Object.keys(compLockedFullSnapshot).length) return false;
            var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            var stat = mvuData.stat_data || (mvuData.stat_data = {});
            if (!stat.同伴 || typeof stat.同伴 !== 'object') stat.同伴 = {};
            var changed = false;
            Object.entries(compLockedFullSnapshot).forEach(function(entry) {
                var compName = entry[0];
                var snap = entry[1] || {};
                if (!Object.keys(snap).length) return;
                var comp = stat.同伴[compName];
                if (!comp || typeof comp !== 'object' || Object.keys(comp).length === 0) {
                    stat.同伴[compName] = JSON.parse(JSON.stringify(snap));
                    changed = true;
                    if (window.toastr) toastr.warning('🔒 已还原被 AI 删除的同伴「' + compName + '」（锁定保护）');
                }
            });
            if (changed) {
                Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
            }
            return changed;
        }

        // 同伴数据规范化：兼容旧版载入格式（顶层 等级/HP/MP/SP/职业信息/自身状态 → 迁移到 基础状态），
        // 并补齐 基础属性/装备栏/物品栏 等缺省字段，保证预览卡与弹窗都能正确显示
        function normalizeCompanionData() {
            if (typeof Mvu === 'undefined') return false;
            var changed = false;
            var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            var comps = _.get(mvuData, 'stat_data.同伴', {});
            Object.entries(comps || {}).forEach(function(ce) {
                var c = ce[1] || {};
                if (!c || typeof c !== 'object') return;
                if (!c.基础状态 || typeof c.基础状态 !== 'object') {
                    c.基础状态 = {};
                    changed = true;
                }
                var bs = c.基础状态;
                // 旧格式迁移：顶层残留字段 → 基础状态，并清理
                if (c.等级 !== undefined) {
                    if (bs.总等级 === undefined) bs.总等级 = c.等级;
                    delete c.等级; changed = true;
                }
                if (c.HP && typeof c.HP === 'object') {
                    if (!bs.HP) bs.HP = c.HP;
                    delete c.HP; changed = true;
                }
                if (c.MP && typeof c.MP === 'object') {
                    if (!bs.MP) bs.MP = c.MP;
                    delete c.MP; changed = true;
                }
                if (c.SP && typeof c.SP === 'object') {
                    if (!bs.SP) bs.SP = c.SP;
                    delete c.SP; changed = true;
                }
                if (c.职业信息 && typeof c.职业信息 === 'object') {
                    if (!bs.职业信息) bs.职业信息 = c.职业信息;
                    delete c.职业信息; changed = true;
                }
                if (c.自身状态 && typeof c.自身状态 === 'object') {
                    if (!bs.自身状态) bs.自身状态 = c.自身状态;
                    delete c.自身状态; changed = true;
                }
                // 补齐缺省
                if (!bs.HP || typeof bs.HP !== 'object') { bs.HP = { 当前: 0, 最大: 0 }; changed = true; }
                if (!bs.MP || typeof bs.MP !== 'object') { bs.MP = { 当前: 0, 最大: 0 }; changed = true; }
                if (!bs.SP || typeof bs.SP !== 'object') { bs.SP = { 当前: 0, 最大: 0 }; changed = true; }
                if (bs.总等级 === undefined) { bs.总等级 = 1; changed = true; }
                if (bs.冒险者等级 === undefined) { bs.冒险者等级 = 'F'; }
                if (bs.待分配职业等级 === undefined) { bs.待分配职业等级 = 0; changed = true; }
                if (!bs.经验值 || typeof bs.经验值 !== 'object') { bs.经验值 = { 当前: 0, 升级所需: 100 }; changed = true; }
                if (!bs.自身状态 || typeof bs.自身状态 !== 'object') { bs.自身状态 = {}; changed = true; }
                if (!bs.职业信息 || typeof bs.职业信息 !== 'object') { bs.职业信息 = {}; changed = true; }
                if (!c.基础属性 || typeof c.基础属性 !== 'object') { c.基础属性 = { 力量:10, 敏捷:10, 体质:10, 智力:10, 感知:10, 魅力:10 }; changed = true; }
                if (c.基础属性 && c.基础属性.未分配点数 === undefined) { c.基础属性.未分配点数 = 0; changed = true; }
                if (c.防御值 === undefined) { c.防御值 = 10; changed = true; }
                if (!c.装备栏 || typeof c.装备栏 !== 'object') { c.装备栏 = { 头部:{}, 颈部:{}, 躯干:{}, 腿部:{}, 双手:{} }; changed = true; }
                if (!c.物品栏 || typeof c.物品栏 !== 'object') { c.物品栏 = {}; changed = true; }
            });
            if (changed) {
                Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
            }
            return changed;
        }

        // 切换同伴物品锁定状态（锁定后：支持写入更新，拒绝删除）
                // 一键锁定/解锁同伴（属性 + 物品栏完全只读，拒绝 AI 删除/修改）
        async function toggleCompFullLock(compName) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var comp = _.get(stat, ['同伴', compName], null);
                if (!comp) { if (window.toastr) toastr.warning('未找到同伴「' + compName + '」'); return; }
                var inv = comp.物品栏 || {};
                var invNames = Object.keys(inv);
                var isFullLocked = comp._全锁定 === true;
                if (isFullLocked) {
                    delete comp._全锁定;
                    delete comp._属性锁定;
                    invNames.forEach(function (n) { if (inv[n]) delete inv[n]._锁定; });
                    if (window.toastr) toastr.info('已解锁「' + compName + '」全部（属性与物品栏恢复可写）');
                } else {
                    comp._全锁定 = true;
                    comp._属性锁定 = true;
                    invNames.forEach(function (n) { if (inv[n]) inv[n]._锁定 = true; });
                    if (window.toastr) toastr.success('🔒 已一键锁定「' + compName + '」（属性+物品栏只读，拒绝删除）');
                }
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                try {
                    var persistLocks = getPersistLocks();
                    var pl = _.get(persistLocks, ['同伴', compName]) || {};
                    _.set(persistLocks, ['同伴', compName], pl);
                    if (comp._全锁定 === true) pl._全锁定 = true; else delete pl._全锁定;
                    if (comp._属性锁定 === true) pl._属性锁定 = true; else delete pl._属性锁定;
                    pl.物品栏 = pl.物品栏 || {};
                    invNames.forEach(function (n) {
                        if (inv[n] && inv[n]._锁定 === true) pl.物品栏[n] = { _锁定: true };
                        else delete pl.物品栏[n];
                    });
                    if (Object.keys(pl.物品栏).length === 0) delete pl.物品栏;
                    if (Object.keys(pl).length === 0) delete persistLocks.同伴[compName];
                    savePersistLocks(persistLocks);
                } catch (e) { console.error('[状态栏] 同步全锁定持久化失败:', e); }
                populateCharacterData();
                renderCompanionDetail(compName);
            } catch (e) {
                console.error('切换同伴全锁定失败:', e);
                if (window.toastr) toastr.error('切换全锁定失败：' + (e && e.message ? e.message : e));
            }
        }

        async function toggleCompItemLock(compName, itemName) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var comp = _.get(stat, ['同伴', compName], null);
                if (!comp) { if (window.toastr) toastr.warning('未找到同伴「' + compName + '」'); return; }
                var inv = comp.物品栏 || {};
                var item = inv[itemName];
                if (!item) { if (window.toastr) toastr.warning('物品「' + itemName + '」不在同伴物品栏中'); return; }
                if (item._锁定 === true) {
                    delete item._锁定;
                    if (window.toastr) toastr.info('已解锁「' + itemName + '」（现在可被删除/装备）');
                } else {
                    item._锁定 = true;
                    if (window.toastr) toastr.success('🔒 已锁定「' + itemName + '」（支持写入更新，拒绝删除）');
                }
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                // 同步持久锁定（跨楼层）：解锁后移除记录，锁定后写入
                try {
                    var persistLocks = getPersistLocks();
                    if (item._锁定 === true) _.set(persistLocks, ['同伴', compName, '物品栏', itemName, '_锁定'], true);
                    else _.unset(persistLocks, ['同伴', compName, '物品栏', itemName]);
                    savePersistLocks(persistLocks);
                } catch (e) { console.error('[状态栏] 同步物品持久锁定失败:', e); }
                populateCharacterData();
                // 重新渲染模态框（直接渲染，锁定按钮就地刷新为「已锁定/未锁定」）
                renderCompanionDetail(compName);
            } catch (e) {
                console.error('切换同伴物品锁定失败:', e);
                if (window.toastr) toastr.error('切换锁定失败：' + (e && e.message ? e.message : e));
            }
        }

        // 切换同伴属性栏锁定（锁定后：禁止 AI 修改 基础属性/待分配职业等级/职业信息，只能通过升级分配写入）
        async function toggleCompAttrLock(compName) {
            try {
                if (typeof Mvu === 'undefined') { if (window.toastr) toastr.error('MVU 框架未初始化'); return; }
                var mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                var stat = _.get(mvuData, 'stat_data', {});
                var comp = _.get(stat, ['同伴', compName], null);
                if (!comp) { if (window.toastr) toastr.warning('未找到同伴「' + compName + '」'); return; }
                if (comp._属性锁定 === true) {
                    delete comp._属性锁定;
                    if (window.toastr) toastr.info('已解锁「' + compName + '」属性（AI 可修改属性）');
                } else {
                    comp._属性锁定 = true;
                    if (window.toastr) toastr.success('🔒 已锁定「' + compName + '」属性（禁止 AI 修改，只能通过升级分配写入）');
                }
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                // 同步持久锁定（跨楼层）：解锁后移除记录，锁定后写入
                try {
                    var persistLocks = getPersistLocks();
                    if (comp._属性锁定 === true) _.set(persistLocks, ['同伴', compName, '_属性锁定'], true);
                    else _.unset(persistLocks, ['同伴', compName, '_属性锁定']);
                    savePersistLocks(persistLocks);
                } catch (e) { console.error('[状态栏] 同步属性持久锁定失败:', e); }
                populateCharacterData();
                renderCompanionDetail(compName);
            } catch (e) {
                console.error('切换同伴属性锁定失败:', e);
                if (window.toastr) toastr.error('切换属性锁定失败：' + (e && e.message ? e.message : e));
            }
        }

        async function init() {
            await waitGlobalInitialized('Mvu');
            populateCharacterData();
            initVarEditor();
            // 检测自创职业并询问是否生成定制技能树（首次加载）
            checkCustomJobsAndPrompt();

            // ===== 新增同伴拦截弹窗（AI 写入新增同伴时确认） =====
            var pendingNewComps = [];
            var isCompConfirmBusy = false;
            var rejectedCompNames = [];   // 用户拒绝的同伴名：后续 AI 写回若再次新增则自动删除（持续拦截）
            function detectNewComps(newV, oldV) {
                if (!newV || !newV.stat_data) return;
                var newComps = (newV.stat_data.同伴) || {};
                var oldComps = (oldV && oldV.stat_data && oldV.stat_data.同伴) || {};
                // 持续拦截：被拒同伴名若又被 AI 写回 → 直接删除
                var needClean = false;
                var mv = null;
                rejectedCompNames.forEach(function (nm) {
                    if (newComps[nm]) {
                        if (!mv) mv = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (mv.stat_data && mv.stat_data.同伴) {
                            delete mv.stat_data.同伴[nm];
                            needClean = true;
                        }
                    }
                });
                if (needClean && mv) {
                    Mvu.replaceMvuData(mv, { type: 'message', message_id: 'latest' });
                    return;
                }
                if (isCompConfirmBusy) return;   // 用户正处理弹窗/防抖期间不再重复弹
                // 收集新增（与已有挂起合并去重，不遗漏）
                var added = [];
                Object.keys(newComps).forEach(function (nm) {
                    if (!oldComps[nm] && pendingNewComps.indexOf(nm) === -1) added.push(nm);
                });
                if (!added.length) return;
                pendingNewComps = pendingNewComps.concat(added);
                $('#comp-confirm-body').html('检测到新增了以下同伴：<br><strong>' + pendingNewComps.map(function (x) { return escapeAttr(x); }).join('、') + '</strong><br><br>是否确认将其加入同伴？');
                $('#comp-confirm-modal').css('display', 'flex');
            }
            $('#btn-comp-confirm-yes').on('click', function () {
                isCompConfirmBusy = true;
                // 确认放行：解除这些同伴之前可能存在的「拒绝」标记
                pendingNewComps.forEach(function (nm) {
                    var idx = rejectedCompNames.indexOf(nm);
                    if (idx !== -1) rejectedCompNames.splice(idx, 1);
                });
                pendingNewComps = [];
                $('#comp-confirm-modal').css('display', 'none');
                setTimeout(function () { isCompConfirmBusy = false; }, 100);
            });
            $('#btn-comp-confirm-no').on('click', function () {
                if (!pendingNewComps.length) { $('#comp-confirm-modal').css('display', 'none'); return; }
                isCompConfirmBusy = true;
                try {
                    var mv = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    pendingNewComps.forEach(function (nm) {
                        if (mv.stat_data.同伴) delete mv.stat_data.同伴[nm];
                        if (rejectedCompNames.indexOf(nm) === -1) rejectedCompNames.push(nm);
                    });
                    var toRemove = pendingNewComps.slice();
                    pendingNewComps = [];
                    $('#comp-confirm-modal').css('display', 'none');
                    Promise.resolve(Mvu.replaceMvuData(mv, { type: 'message', message_id: 'latest' })).then(function () {
                        populateCharacterData();
                        isCompConfirmBusy = false;
                    });
                } catch (e) {
                    console.error('[状态栏] 移除新增同伴失败:', e);
                    pendingNewComps = [];
                    $('#comp-confirm-modal').css('display', 'none');
                    isCompConfirmBusy = false;
                }
            });
            $('#btn-close-comp-confirm').on('click', function () { pendingNewComps = []; $('#comp-confirm-modal').css('display', 'none'); });

            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function(newV, oldV) {
                detectNewComps(newV, oldV);
                // AI 更新结束后：把持久锁定回注到最新楼层（供过滤守卫/物品还原使用），再刷新界面
                applyPersistLocksToLatest();
                // 锁定同伴整条被 AI 删除时：按快照重建（挂在变量更新结束，任何写回都会触发）
                enforceCompPresence();
                populateCharacterData();
                // 刷新后更新同伴整体快照（供下次删除还原）
                updateCompLockedFullSnapshot();
                // 只有职业集合发生变化（新增职业/职业名改变）时才检测自创职业，
                // 避免每次变量更新/每层楼都全量扫描；其余更新（HP、等级、物品等）不触发检测。
                if (jobNamesChanged(newV, oldV)) {
                    if (_customJobPromptTimer) clearTimeout(_customJobPromptTimer);
                    _customJobPromptTimer = setTimeout(checkCustomJobsAndPrompt, 1500);
                }
            });

            // 同伴母路径锁定：AI 不能删除/替换整条同伴，但可修改其下属性（好感度/心里话/基础属性等）
            eventOn(Mvu.events.COMMAND_PARSED, filterLockedCompanionCommands);
            // 追踪记录硬拦截：只允许 insert 追加流水，禁止 replace/remove/add/move 覆盖或删除
            eventOn(Mvu.events.COMMAND_PARSED, filterTrackRecordCommands);
            // 家族/产业写入守卫：产业禁删/禁改结算锚点；家族成员禁删/出生年月日禁改/培养计划玩家托管
            eventOn(Mvu.events.COMMAND_PARSED, filterFamilyIndustryCommands);
            // 名字段规范化：主要NPC/同伴/契约兽/召唤物 名字写错（_/・/拆段）自动修正并与现有键对齐（防同名分叉/幽灵条目）
            eventOn(Mvu.events.COMMAND_PARSED, normalizeNpcNameCommands);
            // 出生年月日/年龄只读：出生年月日一经确定不改；年龄按当前日期自动计算（AI 禁写）
            eventOn(Mvu.events.COMMAND_PARSED, filterImmutableNpcFields);
            // 主角系统字段只读：总等级 / 经验值.升级所需（AI 不可写；同伴不受影响）
            eventOn(Mvu.events.COMMAND_PARSED, filterProtagonistReadonlyCommands);
            eventOn(Mvu.events.COMMAND_PARSED, filterExperienceConfirmCommands);
            // 被动年龄成长：每次变量更新结束（每层）静默检测，够就自动补、不够不管
            try {
                if (typeof Mvu !== 'undefined' && Mvu.events && Mvu.events.VARIABLE_UPDATE_ENDED) {
                    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function () { passiveAgeGrowthCheck(); });
                }
            } catch (e) { console.warn('[年龄成长] 事件注册失败:', e); }

            // 标签页切换
            $('.jrpg-status-wrapper').on('click', '.jrpg-tab-btn', function() {
                var $this = $(this);
                var tabId = $this.data('tab');
                var $wrapper = $this.closest('.jrpg-status-wrapper');
                $wrapper.find('.jrpg-tab-btn').removeClass('active');
                $wrapper.find('.jrpg-tab-content').removeClass('active');
                $this.addClass('active');
                $wrapper.find('#' + tabId).addClass('active');
                if (tabId === 'tab-track') { if (typeof renderTrackTab === 'function') renderTrackTab(); }
                if (tabId === 'tab-family') { if (typeof renderFamilyTab === 'function') renderFamilyTab(); }
                if (tabId === 'tab-industry') { if (typeof renderIndustryTab === 'function') renderIndustryTab(); }
            });

            // 物品栏折叠事件（主角物品栏 + 同伴物品栏）
            $('.jrpg-status-wrapper').on('click', '.jrpg-item-summary', function() {
                var $card = $(this).closest('.jrpg-item-card');
                var $detail = $card.find('.jrpg-item-detail');
                var $arrow = $(this).find('.jrpg-item-summary-arrow');
                $detail.toggleClass('open');
                $arrow.toggleClass('open');
            });

            // ===== 🧺 追踪记录：只读展示（AI 按「变量更新规则·追踪记录」用 MVU insert 写入 世界.追踪记录） =====
            // 数据流：AI 在叙事中发生 金盾入账/支出、购买/出售/更换物品、物品获得/失去、经验获取、货币变动
            //        → 用标准 MVU JSONPatch 在 /世界/追踪记录/{记录ID} insert 一条 → 状态栏本页签直接显示流水账
            function readTrack() {
                try {
                    var mvuD = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    var rec = mvuD && mvuD.stat_data && mvuD.stat_data.世界 ? mvuD.stat_data.世界.追踪记录 : null;
                    if (!rec || typeof rec !== 'object') return [];
                    return Object.keys(rec).map(function(k) {
                        var e = rec[k] || {};
                        return {
                            时间: String(e.时间 || ''),
                            类型: String(e.类型 || '其他'),
                            金额: parseInt(e.金额, 10) || 0,
                            物品: String(e.物品 || ''),
                            数量: parseInt(e.数量, 10) || 0,
                            余额: (e.余额 === undefined || e.余额 === null || e.余额 === '') ? -1 : (parseInt(e.余额, 10) || 0),
                            说明: String(e.说明 || '')
                        };
                    });
                } catch (e) { return []; }
            }
            function renderTrackTab() {
                var box = document.getElementById('track-inner'); if (!box) return;
                var arr = readTrack();
                if (!arr.length) {
                    box.innerHTML = '<div class="jrpg-list-empty">暂无追踪记录。AI 在叙事中发生金盾入账/支出、购买/出售/更换物品、物品获得/失去、经验获取、货币变动这六类事件时，会按「变量更新规则」写入 世界.追踪记录，本页签直接显示流水账。</div>';
                    renderTrackMoney();
                    return;
                }
                var html = '<div style="max-height:320px;overflow:auto;">';
                arr.slice().reverse().forEach(function(e) {
                    var dt = e.时间 || '—';
                    var amount = '';
                    // 经验获取：金额=经验增量，按 EXP 展示（非金盾）
                    if (e.类型 === '经验获取') amount = '<b style="color:#16a085;">✦ ' + (e.金额 > 0 ? '+' : '') + e.金额 + ' EXP</b>';
                    // 金额单位=铜盾（与 stat_data.货币 一致），用 formatCurrency 分级显示（金盾/银盾/铜盾）
                    else if (e.金额 !== 0) amount = '<b style="color:' + (e.金额 >= 0 ? '#27ae60' : '#c0392b') + ';">' + (e.金额 >= 0 ? '+' : '') + formatCurrency(Math.abs(e.金额)) + '</b>';
                    else if (e.数量 !== 0) amount = '<b style="color:' + (e.数量 >= 0 ? '#27ae60' : '#c0392b') + ';">' + (e.数量 > 0 ? '+' : '') + e.数量 + ' ' + (e.物品 || '') + '</b>';
                    html += '<div style="border-bottom:1px dashed #d2b48c;padding:4px 2px;font-size:11px;color:#4a3623;">';
                    html += '<span style="color:#8b6b4a;font-size:10px;">' + escapeAttr(dt) + '</span>　<span style="color:#5a4430;">[' + escapeAttr(e.类型) + ']</span>　' + amount + (e.说明 ? '　<span style="color:#7f8c8d;">' + escapeAttr(e.说明) + '</span>' : '');
                    html += '</div>';
                });
                html += '</div>';
                html += '<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap;">';
                var fullMode = readTrackFullFlag();
                html += '<button id="btn-track-full" class="jrpg-btn-sm" title="切换 状态变量输出 的流水数量：默认近5条省token，全量时AI全文可见" style="padding:3px 10px;font-size:11px;background:' + (fullMode ? '#8e44ad' : '#7f8c8d') + ';color:#fff;border:1px solid ' + (fullMode ? '#8e44ad' : '#7f8c8d') + ';border-radius:4px;">' + (fullMode ? '📜 全量输出' : '📄 近5条') + '</button>';
                html += '<button id="btn-clear-track" class="jrpg-btn-sm" style="padding:3px 10px;font-size:11px;background:#c0392b;color:#fff;border:1px solid #c0392b;border-radius:4px;">🗑 清空</button>';
                html += '</div>';
                box.innerHTML = html;
                renderTrackMoney();
            }
            function readTrackFullFlag() {
                try {
                    var mvuD = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                    return !!(mvuD && mvuD.stat_data && mvuD.stat_data.$flags && mvuD.stat_data.$flags.追踪记录全量);
                } catch (e) { return false; }
            }
            function renderTrackMoney() {
                var box = document.getElementById('track-money'); if (!box) return;
                var mvuD = (window.Mvu && Mvu.getMvuData) ? Mvu.getMvuData({ type: 'message', message_id: 'latest' }) : null;
                var curMoney = mvuD && mvuD.stat_data && mvuD.stat_data.主角 && mvuD.stat_data.主角.资产与能力 ? mvuD.stat_data.主角.资产与能力.货币 : null;
                var lastMoney = lastTrackMoney();
                box.innerHTML = '<div style="font-size:12px;color:#4a3623;">stat_data.货币：<b>' + (curMoney === null ? '（未读取）' : formatCurrency(curMoney)) + '</b>　·　流水账最后余额：<b>' + (lastMoney === null ? '—' : formatCurrency(lastMoney)) + '</b></div>';
                box.innerHTML += '<div style="margin-top:6px;"><button id="btn-fix-money" class="jrpg-btn-sm" style="padding:3px 10px;font-size:11px;background:#27ae60;color:#fff;border:1px solid #27ae60;border-radius:4px;">🔧 一键修正货币为流水账余额</button><span style="font-size:11px;color:#7f8c8d;margin-left:6px;">若不一致，点击后把 stat_data.货币 写为流水账最后余额。</span></div>';
            }
            function lastTrackMoney() {
                var me = readTrack(), last = null;
