                    f *= (_.get(m, '魔力回路.品阶', '无回路') !== '无回路') ? 1.1 : 0.8;
                } else {
                    var pools = { '武技': '力量', '信仰': '感知', '学识': '智力', '商业': '魅力', '技艺': '敏捷', '综合': '力量' };
