<body>
    <script>
    /* ============================================================
       聊天正文美化（羊皮纸多风格）· 设置持久化补丁
       ------------------------------------------------------------
       BUG 原因：世界书/正则注入消息的 HTML 中 <script> 会被
       SillyTavern 净化器剥离，因此「聊天背景_多风格羊皮纸.html」
       自带的 localStorage 持久化脚本从不执行 —— 当层切换靠纯 CSS
       即时生效，但每层新消息都是默认主题/字号（看起来像“又变回默认”）。
       本补丁随状态栏脚本每层执行：仅首次把“修改监听 + 新楼层回放”
       安装到所有可达宿主文档（本窗口 / parent / top），
       任一层切换的主题/字号写入 localStorage，后续所有楼层自动回放。
       幂等：宿主 window.__isuriaPtPersist 标记，只安装一次。
       访问不到宿主（跨域等）时静默跳过，不影响羊皮纸本身显示。
       ============================================================ */
    (function () {
        try {
            var PT_T = 'pt_theme', PT_F = 'pt_font';
            function install(win) {
                try {
                    if (!win || win.__isuriaPtPersist) return;
                    win.__isuriaPtPersist = true;
                    var doc = win.document;
                    if (!doc || !doc.addEventListener || !doc.querySelectorAll) return;
                    var ls = win.localStorage;
                    function readSaved() {
                        var t = null, f = null;
                        try { t = ls.getItem(PT_T); } catch (e) {}
                        try { f = ls.getItem(PT_F); } catch (e) {}
                        return { t: t, f: f };
                    }
                    function applyBox(box, t, f) {
                        if (!box || box.__ptApplied) return;
                        box.__ptApplied = true;
                        if (t) {
                            var rs = box.querySelectorAll('input[name="pt-theme"]');
                            for (var i = 0; i < rs.length; i++) if (rs[i].value === t) { rs[i].checked = true; break; }
                        }
                        if (f) {
                            var fs = box.querySelectorAll('input[name="pt-font"]');
                            for (var j = 0; j < fs.length; j++) if (fs[j].value === f) { fs[j].checked = true; break; }
                        }
                    }
                    function rescan() {
                        if (!doc.querySelectorAll) return;
                        var saved = readSaved();
                        if (!saved.t && !saved.f) return;
                        var boxes = doc.querySelectorAll('[data-parchment]');
                        for (var k = 0; k < boxes.length; k++) applyBox(boxes[k], saved.t, saved.f);
                    }
                    // ① 用户修改主题/字号 → 写 localStorage（捕获阶段，防止被中间 handler 拦截）
                    doc.addEventListener('change', function (ev) {
                        var el = ev && ev.target;
                        if (!el || !el.name) return;
                        if (el.name !== PT_T && el.name !== PT_F) return;
                        try { ls.setItem(el.name, el.value); } catch (e) {}
                    }, true);
                    // ② 已存在的历史楼层回放
                    rescan();
                    // ③ 后续新楼层：消息注入时自动回放（安装一次即持续生效）
                    if (typeof MutationObserver !== 'undefined' && doc.body) {
                        new MutationObserver(function () { rescan(); }).observe(doc.body, { childList: true, subtree: true });
                    } else if (doc.addEventListener) {
                        doc.addEventListener('DOMNodeInserted', function () { rescan(); }, true);
                    }
                } catch (e) { /* 跨域/只读环境静默 */ }
            }
            install(window);
            try { install(window.parent); } catch (e) {}
            try { if (window.top && window.top !== window.parent) install(window.top); } catch (e) {}
        } catch (e) { console.warn('[正文美化持久化] 安装失败（不影响羊皮纸显示）:', e); }
    })();
    </script>
    <script>
    /* ============================================================
       时空存档·读档补丁（正文渲染器按钮排交互）
       按钮由卡内正则（正文美化暗色）渲染：data-iz-save / data-iz-load / data-iz-info
       楼层号从点击处最近的 [mesid]/[message_id]/[mes] DOM 祖先解析。
       存档数据存聊天变量 isuria_save_slots（type:'chat'，分聊天隔离）：
       { "1": {floor:12, date:"圣光历1497年3月4日", snippet:"..."}, ... }
       读档 = 删除存档楼之后的所有楼层并刷新（等效回档）。
       幂等：window.__isuriaSavePatch 标记，只安装一次。
       ============================================================ */
    (function () {
        try {
            // 幂等按【文档】算而不是按 window 算：酒馆助手更新楼层会重写消息 iframe 的 document，
            // 旧文档上的监听器随之销毁；新文档没有 __isuriaSavePatchDoc 标记，周期扫描会自动重装（自愈）。
            function install(win) {
                try {
                    if (!win || !win.document || !win.document.addEventListener) return;
                    var doc = win.document;
                    if (doc.__isuriaSavePatchDoc) return;
                    doc.__isuriaSavePatchDoc = true;
                    function TH() { return (win.TavernHelper) || (win.parent && win.parent.TavernHelper) || (win.top && win.top.TavernHelper) || null; }
                    function floorOf(el) {
                        while (el && el !== doc.body) {
                            var m = el.getAttribute && (el.getAttribute('mesid') || el.getAttribute('message_id') || el.getAttribute('mes'));
                            if (m !== null && m !== undefined && m !== '') { var n = parseInt(m, 10); if (!isNaN(n)) return n; }
                            el = el.parentNode;
                        }
                        return null;
                    }
                    function getSlots(cb) {
                        var th = TH(); if (!th || !th.getVariables) { cb({}); return; }
                        th.getVariables({ type: 'chat' }).then(function (v) { cb(v && v.isuria_save_slots ? v.isuria_save_slots : {}); }).catch(function () { cb({}); });
                    }
                    function setSlots(slots, cb) {
                        var th = TH(); if (!th || !th.insertOrAssignVariables) { cb && cb(false); return; }
                        th.insertOrAssignVariables({ isuria_save_slots: slots }, { type: 'chat' }).then(function () { cb && cb(true); }).catch(function () { cb && cb(false); });
                    }
                    function dateOfFloor(floor) {
                        try {
                            var th = TH();
                            var ctx = th && th.getChatMessages ? th.getChatMessages(floor) : null;
                            var mes = ctx && ctx.message ? String(ctx.message) : '';
                            var m = mes.match(/圣光历\d+年(?:\s*\d+月)?(?:\s*\d+日)?/);
                            return m ? m[0] : '';
                        } catch (e) { return ''; }
                    }
                    function refreshInfo() {
                        var boxes = doc.querySelectorAll('[data-iz-savebar]');
                        if (!boxes.length) return;
                        getSlots(function (slots) {
                            for (var i = 0; i < boxes.length; i++) {
                                var box = boxes[i];
                                var msg = box.closest ? box.closest('[mesid],[message_id],[mes]') : null;
                                var spans = box.querySelectorAll('[data-iz-info]');
                                for (var s = 0; s < spans.length; s++) {
                                    var parts = [];
                                    for (var k = 1; k <= 3; k++) {
                                        var sl = slots[k];
                                        parts.push('存' + k + ':' + (sl ? ('楼' + sl.floor + (sl.date ? '·' + sl.date : '')) : '空'));
                                    }
                                    spans[s].textContent = parts.join('　');
                                }
                                var btns = box.querySelectorAll('[data-iz-load]');
                                for (var b = 0; b < btns.length; b++) {
                                    var sl2 = slots[btns[b].getAttribute('data-iz-load')];
                                    btns[b].style.opacity = sl2 ? '1' : '.45';
                                }
                            }
                        });
                    }
                    // ★ 捕获阶段委托：即使正文渲染器内部 stopPropagation 也拦不住
                    doc.addEventListener('click', function (ev) {
                        var t = ev.target;
                        while (t && t !== doc.body && !(t.getAttribute && (t.getAttribute('data-iz-save') || t.getAttribute('data-iz-load')))) t = t.parentNode;
                        if (!t || t === doc.body) return;
                        var th = TH();
                        if (!th) { if (win.console && win.console.warn) win.console.warn('[时空存档] 未找到 TavernHelper 接口，读档按钮不可用'); return; }
                        var bar = t.closest ? t.closest('[data-iz-savebar]') : null;
                        var floor = floorOf(bar || t);
                        if (floor === null) { alert('未能定位当前楼层'); return; }
                        var sv = t.getAttribute('data-iz-save');
                        if (sv) {
                            getSlots(function (slots) {
                                var slotsNow = slots || {};
                                slotsNow[sv] = { floor: floor, date: dateOfFloor(floor), snippet: '' };
                                setSlots(slotsNow, function (okr) {
                                    if (okr !== false) { if (th.toastr) th.toastr.success('已存档：楼' + floor, '时空存档'); refreshInfo(); }
                                    else if (th.toastr) th.toastr.error('存档失败', '时空存档');
                                });
                            });
                            return;
                        }
                        var ld = t.getAttribute('data-iz-load');
                        if (ld) {
                            getSlots(function (slots) {
                                var sl = slots && slots[ld];
                                if (!sl || sl.floor === undefined) { if (th.toastr) th.toastr.info('该存档槽为空', '时空存档'); return; }
                                var latest = th.getLastMessageId ? th.getLastMessageId() : null;
                                if (latest === null || latest <= sl.floor) { if (th.toastr) th.toastr.info('当前已在存档点或更早，无需读档', '时空存档'); return; }
                                if (!win.confirm('读档将回溯到 第' + sl.floor + '楼' + (sl.date ? '（' + sl.date + '）' : '') + '，其后的所有剧情将被删除。确定吗？')) return;
                                var ids = []; for (var f2 = sl.floor + 1; f2 <= latest; f2++) ids.push(f2);
                                th.deleteChatMessages(ids).then(function () {
                                    if (th.toastr) th.toastr.success('已回溯到 第' + sl.floor + '楼', '时空存档');
                                }).catch(function (e2) { if (th.toastr) th.toastr.error('读档失败: ' + (e2 && e2.message || e2), '时空存档'); });
                            });
                        }
                    }, true);
                    setInterval(function () {
                        // 文档被替换（楼层重渲染）后此定时器随旧文档闲置，自清防止堆积
                        try { if (doc.defaultView === null) { clearInterval(this); return; } } catch (e) {}
                        refreshInfo();
                    }, 3000);
                    setTimeout(refreshInfo, 800);
                    // ★ 防御性样式：正文渲染器若给按钮排误设 pointer-events:none / 缺手型，这里强制恢复
                    try {
                        var st = doc.createElement('style');
                        st.textContent = '[data-iz-savebar],[data-iz-savebar] *{pointer-events:auto !important;}[data-iz-savebar] [data-iz-save],[data-iz-savebar] [data-iz-load]{cursor:pointer !important;}';
                        (doc.head || doc.documentElement).appendChild(st);
                    } catch (e) {}
                } catch (e) { console.warn('[时空存档补丁] 安装失败:', e); }
            }
            // ★ 全树扫描：状态栏只活在最新楼层，旧楼层的存档按钮排靠把补丁装进所有可达的同源 iframe 文档来覆盖
            function installAll(win) {
                try {
                    if (!win) return;
                    install(win);
                    var docs = [];
                    try { if (win.parent && win.parent.document) docs.push(win.parent.document); } catch (e) {}
                    try { if (win.top && win.top.document && win.top.document !== win.parent.document) docs.push(win.top.document); } catch (e) {}
                    for (var d = 0; d < docs.length; d++) {
                        try {
                            install(docs[d].defaultView);
                            var frames = docs[d].querySelectorAll('iframe');
                            for (var i = 0; i < frames.length; i++) {
                                try { if (frames[i].contentWindow) install(frames[i].contentWindow); } catch (e) {}
                            }
                        } catch (e) {}
                    }
                } catch (e) { console.warn('[时空存档补丁] 扫描安装失败:', e); }
            }
            try { installAll(window); } catch (e) {}
            // 楼层 iframe 随消息更新/新增不断重建：周期重扫（幂等按文档标记，重复扫描开销可忽略）
            setInterval(function () { try { installAll(window); } catch (e) {} }, 1500);
        } catch (e) { console.warn('[时空存档补丁] 外层异常:', e); }
    })();
    </script>
